insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','A school has 1,200 students and one teacher for every 30 of them. If 300 more students join, how many more teachers must be appointed so that there are no more than 24 students for each teacher?','एक विद्यालय में 1,200 विद्यार्थी हैं और हर 30 विद्यार्थियों पर एक शिक्षक। यदि 300 और विद्यार्थी आ जाएँ, तो कितने और शिक्षक नियुक्त करने होंगे ताकि हर शिक्षक पर 24 से अधिक विद्यार्थी न हों?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 1}'::jsonb,'[{"id": "a", "body": "10", "body_hi": "10", "isCorrect": false}, {"id": "b", "body": "20", "body_hi": "20", "isCorrect": false}, {"id": "c", "body": "22", "body_hi": "22", "isCorrect": false}, {"id": "d", "body": "23", "body_hi": "23", "isCorrect": true}]'::jsonb,2.5,0.83,'There are now 1,200 ÷ 30 = 40 teachers. 1,500 students at no more than 24 a teacher need at least 1,500 ÷ 24 = 62.5 teachers -- that is, 63, since 62 would leave more than 24 to some teacher. So 63 - 40 = 23 more. 22 rounds 62.5 down; 10 keeps the old ratio of 30 for the 300 new students; 20 has no basis.','अभी 1,200 ÷ 30 = 40 शिक्षक हैं। प्रति शिक्षक 24 से अधिक नहीं की दर से 1,500 विद्यार्थियों को कम से कम 1,500 ÷ 24 = 62.5 शिक्षक चाहिए -- यानी 63, क्योंकि 62 होने पर किसी शिक्षक के पास 24 से अधिक रह जाएँगे। अतः 63 - 40 = 23 और। 22, 62.5 को नीचे की ओर पूर्णांकित करता है; 10, 300 नए विद्यार्थियों के लिए पुराना 30 का अनुपात रखता है; 20 का कोई आधार नहीं।','csat-l4-s05-qa-rm-teachers-needed-for-a-lower-ratio','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','medium','The numbers 1 to 6 are written once each, one at every corner of a triangle and one at the middle of every side, so that the three numbers along each side add up to 9. What do the three numbers at the corners add up to?','संख्याएँ 1 से 6 एक-एक बार लिखी जाती हैं, एक त्रिभुज के हर कोने पर एक और हर भुजा के मध्य में एक, ऐसे कि हर भुजा की तीनों संख्याओं का योग 9 हो। कोनों की तीनों संख्याओं का योग क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 2}'::jsonb,'[{"id": "a", "body": "6", "body_hi": "6", "isCorrect": true}, {"id": "b", "body": "9", "body_hi": "9", "isCorrect": false}, {"id": "c", "body": "12", "body_hi": "12", "isCorrect": false}, {"id": "d", "body": "15", "body_hi": "15", "isCorrect": false}]'::jsonb,2.5,0.83,'Add the three side totals: 3 × 9 = 27. This counts every number once and each corner twice, since a corner lies on two sides. All six numbers add up to 21, so the corners add up to 27 - 21 = 6 -- which forces them to be 1, 2 and 3 (with 6, 4 and 5 in the middles). 9 is a side total, not the corners''; 12 and 15 would make the side totals larger than 9.','तीनों भुजाओं के योग जोड़िए: 3 × 9 = 27। इसमें हर संख्या एक बार और हर कोना दो बार गिना जाता है, क्योंकि कोना दो भुजाओं पर होता है। छहों संख्याओं का योग 21 है, इसलिए कोनों का योग 27 - 21 = 6 है -- जिससे वे 1, 2 और 3 ही हो सकते हैं (मध्य में 6, 4 और 5)। 9 एक भुजा का योग है, कोनों का नहीं; 12 और 15 भुजाओं के योग को 9 से बड़ा कर देंगे।','csat-l4-s05-qa-ph-a-magic-triangle','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','In how many ways can 30 be written as the sum of two prime numbers, if the order of the two does not matter?','30 को दो अभाज्य संख्याओं के योग के रूप में कितने तरीक़ों से लिखा जा सकता है, यदि दोनों का क्रम मायने न रखे?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 3}'::jsonb,'[{"id": "a", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "b", "body": "2", "body_hi": "2", "isCorrect": false}, {"id": "c", "body": "3", "body_hi": "3", "isCorrect": true}, {"id": "d", "body": "6", "body_hi": "6", "isCorrect": false}]'::jsonb,2.5,0.83,'Try each prime up to 15 and see whether 30 minus it is prime: 7 + 23, 11 + 19 and 13 + 17 work, while 2, 3 and 5 leave 28, 27 and 25, none of them prime. That is 3 ways. 1 + 29 does not count, since 1 is not a prime, and 15 + 15 fails because 15 is not prime; 6 counts each pair twice, in both orders; 2 misses one pair.','15 तक की हर अभाज्य संख्या लेकर देखिए कि 30 में से उसे घटाने पर अभाज्य बचता है या नहीं: 7 + 23, 11 + 19 और 13 + 17 चलते हैं, जबकि 2, 3 और 5 से 28, 27 और 25 बचते हैं, जिनमें कोई अभाज्य नहीं। यानी 3 तरीक़े। 1 + 29 नहीं गिना जाता, क्योंकि 1 अभाज्य नहीं है, और 15 + 15 विफल है क्योंकि 15 अभाज्य नहीं; 6 हर जोड़े को दोनों क्रमों में दो बार गिनता है; 2 एक जोड़ा छोड़ देता है।','csat-l4-s05-qa-nt-thirty-as-a-sum-of-two-primes','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','hard','A survey of a town found that every household that owns a car also owns a bicycle; that some households that own a bicycle do not own a television; and that no household without a television owns a car. Which one of the following must be true?','एक नगर के सर्वेक्षण में पाया गया कि कार रखने वाला हर परिवार साइकिल भी रखता है; कि साइकिल रखने वाले कुछ परिवार टेलीविज़न नहीं रखते; और कि टेलीविज़न न रखने वाला कोई भी परिवार कार नहीं रखता। निम्नलिखित में से कौन-सा अवश्य सत्य है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 4}'::jsonb,'[{"id": "a", "body": "Every household that owns a bicycle also owns a car.", "body_hi": "साइकिल रखने वाला हर परिवार कार भी रखता है।", "isCorrect": false}, {"id": "b", "body": "Some households that own a bicycle do not own a car.", "body_hi": "साइकिल रखने वाले कुछ परिवार कार नहीं रखते।", "isCorrect": true}, {"id": "c", "body": "Some households that own a car do not own a television.", "body_hi": "कार रखने वाले कुछ परिवार टेलीविज़न नहीं रखते।", "isCorrect": false}, {"id": "d", "body": "Every household that owns a television also owns a car.", "body_hi": "टेलीविज़न रखने वाला हर परिवार कार भी रखता है।", "isCorrect": false}]'::jsonb,2.5,0.83,'Take the households that own a bicycle but no television; the survey says there are some. No household without a television owns a car, so none of these owns a car. So some households that own a bicycle do not own a car. That same fact rules out ''every household with a bicycle owns a car''; ''some car owners have no television'' contradicts the third finding, which means every car owner has a television; and the third finding does not run backwards -- a television does not bring a car with it.','उन परिवारों को लीजिए जिनके पास साइकिल है पर टेलीविज़न नहीं; सर्वेक्षण कहता है कि ऐसे कुछ हैं। टेलीविज़न न रखने वाला कोई परिवार कार नहीं रखता, इसलिए इनमें से किसी के पास कार नहीं। अतः साइकिल रखने वाले कुछ परिवार कार नहीं रखते। यही तथ्य ''साइकिल रखने वाला हर परिवार कार रखता है'' को ख़ारिज करता है; ''कुछ कार वालों के पास टेलीविज़न नहीं'' तीसरी खोज का खंडन करता है, जिसका अर्थ है कि हर कार वाले के पास टेलीविज़न है; और तीसरी खोज उलटी नहीं चलती -- टेलीविज़न अपने साथ कार नहीं लाता।','csat-l4-s05-lr-sc-what-a-household-survey-guarantees','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1970 the economist George Akerlof described a market for used cars in which every seller knows whether a car is sound or a ''lemon'', but no buyer can tell. Unable to tell them apart, buyers will offer only a price suited to a car of average quality. The owners of good cars find that price too low and keep their cars off the market. The cars on offer are then worse on average, so buyers offer still less, and more good cars are withdrawn. In the extreme, only lemons are left for sale. The trouble is not that sellers lie, but that what they know cannot be shown to buyers. That is why such markets develop ways for the seller of a good car to prove it -- warranties, independent inspections, and dealers who have a reputation to protect.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1970 में अर्थशास्त्री जॉर्ज एकरलॉफ़ ने पुरानी गाड़ियों के एक ऐसे बाज़ार का वर्णन किया जिसमें हर विक्रेता जानता है कि गाड़ी ठीक है या ''लेमन'' (ख़राब), पर कोई ख़रीदार यह नहीं बता सकता। उन्हें अलग न कर पाने के कारण ख़रीदार केवल औसत गुणवत्ता की गाड़ी के लायक़ मूल्य देंगे। अच्छी गाड़ियों के मालिकों को वह मूल्य बहुत कम लगता है और वे अपनी गाड़ियाँ बाज़ार से दूर रखते हैं। तब बिक्री पर गाड़ियाँ औसतन और ख़राब होती हैं, इसलिए ख़रीदार और भी कम देते हैं, और और अच्छी गाड़ियाँ हट जाती हैं। चरम स्थिति में बिक्री के लिए केवल ख़राब गाड़ियाँ बचती हैं। कठिनाई यह नहीं कि विक्रेता झूठ बोलते हैं, बल्कि यह कि वे जो जानते हैं उसे ख़रीदारों को दिखाया नहीं जा सकता। इसीलिए ऐसे बाज़ारों में अच्छी गाड़ी के विक्रेता के लिए उसे सिद्ध करने के तरीक़े विकसित होते हैं -- वारंटी, स्वतंत्र निरीक्षण, और ऐसे डीलर जिनकी बचाने लायक़ साख हो।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p01", "csat_order": 5}'::jsonb,'[{"id": "a", "body": "When buyers cannot tell good goods from bad, good ones may be driven out unless quality can be shown.", "body_hi": "जब ख़रीदार अच्छे और ख़राब सामान को अलग न कर सकें, तो गुणवत्ता दिखाने के बिना अच्छा सामान बाहर हो सकता है।", "isCorrect": true}, {"id": "b", "body": "Most sellers of used cars are dishonest, and buyers should never trust what any seller says about a car.", "body_hi": "पुरानी गाड़ियों के अधिकांश विक्रेता बेईमान हैं, और ख़रीदारों को किसी विक्रेता की बात पर कभी भरोसा नहीं करना चाहिए।", "isCorrect": false}, {"id": "c", "body": "Every used car on sale is likely to be a lemon, so buying a new car is always the wiser choice.", "body_hi": "बिक्री पर हर पुरानी गाड़ी के ख़राब होने की संभावना है, इसलिए नई गाड़ी ख़रीदना हमेशा अधिक समझदारी है।", "isCorrect": false}, {"id": "d", "body": "Warranties and inspections are the main reason why so many poor cars are offered on the used-car market.", "body_hi": "वारंटी और निरीक्षण ही वह मुख्य कारण हैं जिससे पुरानी गाड़ियों के बाज़ार में इतनी ख़राब गाड़ियाँ आती हैं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage shows how buyers who cannot judge quality drive good cars out of the market, and ends with the remedies that let sellers prove quality. It says the trouble is ''not that sellers lie'', so dishonesty is not its point; it does not say every used car is a lemon -- only that, in the extreme, lemons are what is left; and it presents warranties as a remedy, not a cause.','परिच्छेद दिखाता है कि गुणवत्ता न आँक पाने वाले ख़रीदार अच्छी गाड़ियों को बाज़ार से कैसे बाहर कर देते हैं, और उन उपायों पर समाप्त होता है जिनसे विक्रेता गुणवत्ता सिद्ध कर सकें। वह कहता है कि कठिनाई ''यह नहीं कि विक्रेता झूठ बोलते हैं'', इसलिए बेईमानी उसकी बात नहीं; वह यह नहीं कहता कि हर पुरानी गाड़ी ख़राब है -- केवल यह कि चरम स्थिति में ख़राब गाड़ियाँ ही बचती हैं; और वह वारंटी को उपाय बताता है, कारण नहीं।','csat-l4-s05-rc-p01-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1970 the economist George Akerlof described a market for used cars in which every seller knows whether a car is sound or a ''lemon'', but no buyer can tell. Unable to tell them apart, buyers will offer only a price suited to a car of average quality. The owners of good cars find that price too low and keep their cars off the market. The cars on offer are then worse on average, so buyers offer still less, and more good cars are withdrawn. In the extreme, only lemons are left for sale. The trouble is not that sellers lie, but that what they know cannot be shown to buyers. That is why such markets develop ways for the seller of a good car to prove it -- warranties, independent inspections, and dealers who have a reputation to protect.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1970 में अर्थशास्त्री जॉर्ज एकरलॉफ़ ने पुरानी गाड़ियों के एक ऐसे बाज़ार का वर्णन किया जिसमें हर विक्रेता जानता है कि गाड़ी ठीक है या ''लेमन'' (ख़राब), पर कोई ख़रीदार यह नहीं बता सकता। उन्हें अलग न कर पाने के कारण ख़रीदार केवल औसत गुणवत्ता की गाड़ी के लायक़ मूल्य देंगे। अच्छी गाड़ियों के मालिकों को वह मूल्य बहुत कम लगता है और वे अपनी गाड़ियाँ बाज़ार से दूर रखते हैं। तब बिक्री पर गाड़ियाँ औसतन और ख़राब होती हैं, इसलिए ख़रीदार और भी कम देते हैं, और और अच्छी गाड़ियाँ हट जाती हैं। चरम स्थिति में बिक्री के लिए केवल ख़राब गाड़ियाँ बचती हैं। कठिनाई यह नहीं कि विक्रेता झूठ बोलते हैं, बल्कि यह कि वे जो जानते हैं उसे ख़रीदारों को दिखाया नहीं जा सकता। इसीलिए ऐसे बाज़ारों में अच्छी गाड़ी के विक्रेता के लिए उसे सिद्ध करने के तरीक़े विकसित होते हैं -- वारंटी, स्वतंत्र निरीक्षण, और ऐसे डीलर जिनकी बचाने लायक़ साख हो।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["A seller who offers a long warranty is, on the passage''s reasoning, more likely to be selling a sound car.", "In the market described, buyers end up paying more than good cars are worth."], "statements_hi": ["परिच्छेद के तर्क से, लंबी वारंटी देने वाले विक्रेता के ठीक गाड़ी बेचने की संभावना अधिक है।", "वर्णित बाज़ार में ख़रीदार अंततः अच्छी गाड़ियों के मूल्य से अधिक चुकाते हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p01", "csat_order": 6}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 1 is valid. A long warranty costs the seller of a lemon dearly, since it will break down and have to be repaired; the seller of a sound car can offer one cheaply. So, on the passage''s reasoning, a warranty is a way for the seller of a good car to prove it. 2 reverses the passage: buyers offer a price suited to average quality, which is too little for good cars -- that is why their owners withdraw them.','केवल 1 वैध है। लंबी वारंटी ख़राब गाड़ी के विक्रेता को बहुत महँगी पड़ती है, क्योंकि गाड़ी ख़राब होगी और ठीक करनी पड़ेगी; ठीक गाड़ी का विक्रेता उसे सस्ते में दे सकता है। इसलिए, परिच्छेद के तर्क से, वारंटी अच्छी गाड़ी के विक्रेता के लिए उसे सिद्ध करने का एक तरीक़ा है। 2 परिच्छेद को उलट देता है: ख़रीदार औसत गुणवत्ता के लायक़ मूल्य देते हैं, जो अच्छी गाड़ियों के लिए बहुत कम है -- इसीलिए उनके मालिक उन्हें हटा लेते हैं।','csat-l4-s05-rc-p01-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1970 the economist George Akerlof described a market for used cars in which every seller knows whether a car is sound or a ''lemon'', but no buyer can tell. Unable to tell them apart, buyers will offer only a price suited to a car of average quality. The owners of good cars find that price too low and keep their cars off the market. The cars on offer are then worse on average, so buyers offer still less, and more good cars are withdrawn. In the extreme, only lemons are left for sale. The trouble is not that sellers lie, but that what they know cannot be shown to buyers. That is why such markets develop ways for the seller of a good car to prove it -- warranties, independent inspections, and dealers who have a reputation to protect.

According to the passage, why do the owners of good cars keep them off the market?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1970 में अर्थशास्त्री जॉर्ज एकरलॉफ़ ने पुरानी गाड़ियों के एक ऐसे बाज़ार का वर्णन किया जिसमें हर विक्रेता जानता है कि गाड़ी ठीक है या ''लेमन'' (ख़राब), पर कोई ख़रीदार यह नहीं बता सकता। उन्हें अलग न कर पाने के कारण ख़रीदार केवल औसत गुणवत्ता की गाड़ी के लायक़ मूल्य देंगे। अच्छी गाड़ियों के मालिकों को वह मूल्य बहुत कम लगता है और वे अपनी गाड़ियाँ बाज़ार से दूर रखते हैं। तब बिक्री पर गाड़ियाँ औसतन और ख़राब होती हैं, इसलिए ख़रीदार और भी कम देते हैं, और और अच्छी गाड़ियाँ हट जाती हैं। चरम स्थिति में बिक्री के लिए केवल ख़राब गाड़ियाँ बचती हैं। कठिनाई यह नहीं कि विक्रेता झूठ बोलते हैं, बल्कि यह कि वे जो जानते हैं उसे ख़रीदारों को दिखाया नहीं जा सकता। इसीलिए ऐसे बाज़ारों में अच्छी गाड़ी के विक्रेता के लिए उसे सिद्ध करने के तरीक़े विकसित होते हैं -- वारंटी, स्वतंत्र निरीक्षण, और ऐसे डीलर जिनकी बचाने लायक़ साख हो।

परिच्छेद के अनुसार, अच्छी गाड़ियों के मालिक उन्हें बाज़ार से दूर क्यों रखते हैं?','{"craft": "precision", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p01", "csat_order": 7}'::jsonb,'[{"id": "a", "body": "There are too few buyers in such a market for anyone to sell a car quickly.", "body_hi": "ऐसे बाज़ार में इतने कम ख़रीदार हैं कि कोई भी अपनी गाड़ी जल्दी नहीं बेच सकता।", "isCorrect": false}, {"id": "b", "body": "The price buyers offer suits a car of average quality, which is too little for a good one.", "body_hi": "ख़रीदारों का दिया मूल्य औसत गाड़ी के लायक़ है, जो अच्छी गाड़ी के लिए बहुत कम है।", "isCorrect": true}, {"id": "c", "body": "Their owners fear that an independent inspection would find hidden faults in the car.", "body_hi": "उनके मालिकों को डर है कि स्वतंत्र निरीक्षण गाड़ी में छिपी ख़राबियाँ पकड़ लेगा।", "isCorrect": false}, {"id": "d", "body": "The law in such markets does not allow good cars to be sold at a higher price than poor ones.", "body_hi": "ऐसे बाज़ारों में क़ानून अच्छी गाड़ियों को ख़राब गाड़ियों से ऊँचे मूल्य पर बेचने नहीं देता।", "isCorrect": false}]'::jsonb,2.5,0.83,'Buyers who cannot tell good cars from bad offer a price suited to average quality, and the owners of good cars find that too low. The passage does not say that good cars are hard to sell for lack of buyers, that owners fear inspections, or that the law forbids their sale.','जो ख़रीदार अच्छी और ख़राब गाड़ियों में भेद नहीं कर सकते, वे औसत गुणवत्ता के लायक़ मूल्य देते हैं, और अच्छी गाड़ियों के मालिकों को वह बहुत कम लगता है। परिच्छेद यह नहीं कहता कि ख़रीदारों की कमी से अच्छी गाड़ियाँ बेचना कठिन है, कि मालिक निरीक्षण से डरते हैं, या कि क़ानून उनकी बिक्री रोकता है।','csat-l4-s05-rc-p01-why-good-cars-are-withdrawn','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','medium','A shirt marked ₹1,000 can be bought with a 10 per cent discount and a coupon worth ₹100 off. The shop applies the two in whichever order the customer chooses. How much does the customer save by choosing the better order?','₹1,000 अंकित मूल्य की एक कमीज़ 10 प्रतिशत छूट और ₹100 की कटौती वाले एक कूपन के साथ ख़रीदी जा सकती है। दुकान दोनों को उस क्रम में लागू करती है जो ग्राहक चुने। बेहतर क्रम चुनकर ग्राहक कितना बचाता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 8}'::jsonb,'[{"id": "a", "body": "₹0", "body_hi": "₹0", "isCorrect": false}, {"id": "b", "body": "₹10", "body_hi": "₹10", "isCorrect": true}, {"id": "c", "body": "₹90", "body_hi": "₹90", "isCorrect": false}, {"id": "d", "body": "₹100", "body_hi": "₹100", "isCorrect": false}]'::jsonb,2.5,0.83,'Discount first: 10 per cent off ₹1,000 gives ₹900, and the coupon then brings it to ₹800. Coupon first: ₹900, and 10 per cent off that gives ₹810. Taking the discount first is better, by ₹10 -- because the discount then applies to the larger amount. ₹0 assumes the order cannot matter; ₹90 and ₹100 have no basis.','पहले छूट: ₹1,000 पर 10 प्रतिशत छूट से ₹900, और फिर कूपन से ₹800। पहले कूपन: ₹900, और उस पर 10 प्रतिशत छूट से ₹810। पहले छूट लेना ₹10 से बेहतर है -- क्योंकि तब छूट बड़ी राशि पर लगती है। ₹0 मान लेता है कि क्रम से कोई फ़र्क़ नहीं पड़ता; ₹90 और ₹100 का कोई आधार नहीं।','csat-l4-s05-qa-pp-a-coupon-before-or-after-a-discount','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','hard','A car''s speedometer shows a speed 10 per cent higher than the car''s true speed. The driver keeps the needle steady at 66 km/h for 2 hours. How far does the car actually travel?','एक गाड़ी का स्पीडोमीटर गाड़ी की वास्तविक चाल से 10 प्रतिशत अधिक चाल दिखाता है। चालक 2 घंटे तक सुई को 66 किमी/घंटा पर स्थिर रखता है। गाड़ी वास्तव में कितनी दूरी तय करती है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 9}'::jsonb,'[{"id": "a", "body": "118.8 km", "body_hi": "118.8 किमी", "isCorrect": false}, {"id": "b", "body": "120 km", "body_hi": "120 किमी", "isCorrect": true}, {"id": "c", "body": "132 km", "body_hi": "132 किमी", "isCorrect": false}, {"id": "d", "body": "145.2 km", "body_hi": "145.2 किमी", "isCorrect": false}]'::jsonb,2.5,0.83,'The reading is 110 per cent of the true speed, so the true speed is 66 ÷ 1.1 = 60 km/h, and in 2 hours the car covers 120 km. 118.8 km takes 10 per cent off the reading (66 × 0.9 = 59.4), but the 10 per cent is of the true speed, not of the reading; 132 km trusts the reading; 145.2 km adds 10 per cent instead of removing it.','पाठ्यांक वास्तविक चाल का 110 प्रतिशत है, इसलिए वास्तविक चाल 66 ÷ 1.1 = 60 किमी/घंटा है, और 2 घंटों में गाड़ी 120 किमी चलती है। 118.8 किमी पाठ्यांक में से 10 प्रतिशत घटाता है (66 × 0.9 = 59.4), पर 10 प्रतिशत वास्तविक चाल का है, पाठ्यांक का नहीं; 132 किमी पाठ्यांक पर भरोसा करता है; 145.2 किमी 10 प्रतिशत हटाने के बजाय जोड़ता है।','csat-l4-s05-qa-sdt-a-speedometer-that-reads-high','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Syllogism','statement_based','easy','Statements: Some bottles are green. All green things are recyclable.

Which of the following conclusions follow(s) from the statements?','कथन: कुछ बोतलें हरी हैं। सभी हरी वस्तुएँ पुनर्चक्रण योग्य हैं।

निम्नलिखित में से कौन-सा/से निष्कर्ष कथनों से निकलता/निकलते है/हैं?','{"statements": ["Some bottles are recyclable.", "Some recyclable things are bottles."], "statements_hi": ["कुछ बोतलें पुनर्चक्रण योग्य हैं।", "कुछ पुनर्चक्रण योग्य वस्तुएँ बोतलें हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "numbering": "roman", "csat_set": "csat-l4-s05", "csat_order": 10}'::jsonb,'[{"id": "a", "body": "I only", "body_hi": "केवल I", "isCorrect": false}, {"id": "b", "body": "II only", "body_hi": "केवल II", "isCorrect": false}, {"id": "c", "body": "Both I and II", "body_hi": "I और II दोनों", "isCorrect": true}, {"id": "d", "body": "Neither I nor II", "body_hi": "न तो I, न ही II", "isCorrect": false}]'::jsonb,2.5,0.83,'Both follow. The green bottles are green things, and all green things are recyclable, so those bottles are recyclable (I). And if some bottles are recyclable, then some recyclable things are bottles -- the same fact read the other way round (II).','दोनों निकलते हैं। हरी बोतलें हरी वस्तुएँ हैं, और सभी हरी वस्तुएँ पुनर्चक्रण योग्य हैं, इसलिए वे बोतलें पुनर्चक्रण योग्य हैं (I)। और यदि कुछ बोतलें पुनर्चक्रण योग्य हैं, तो कुछ पुनर्चक्रण योग्य वस्तुएँ बोतलें हैं -- वही तथ्य उलटी ओर से पढ़ा गया (II)।','csat-l4-s05-lr-sy-bottles-that-are-green','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','Which is the greater of √5 + √3 and √6 + √2?','√5 + √3 और √6 + √2 में से कौन-सा बड़ा है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 11}'::jsonb,'[{"id": "a", "body": "√6 + √2", "body_hi": "√6 + √2", "isCorrect": false}, {"id": "b", "body": "They are equal", "body_hi": "दोनों बराबर हैं", "isCorrect": false}, {"id": "c", "body": "It cannot be told without working out each root", "body_hi": "हर मूल निकाले बिना नहीं बताया जा सकता", "isCorrect": false}, {"id": "d", "body": "√5 + √3", "body_hi": "√5 + √3", "isCorrect": true}]'::jsonb,2.5,0.83,'Both sums are positive, so compare their squares. (√5 + √3)² = 5 + 3 + 2√15 = 8 + 2√15, and (√6 + √2)² = 6 + 2 + 2√12 = 8 + 2√12. Since 15 > 12, √5 + √3 is the greater (about 3.97 against 3.86). Both sums add numbers whose total under the roots is 8, which tempts one to call them equal; and squaring settles it without working out any root.','दोनों योग धनात्मक हैं, इसलिए उनके वर्गों की तुलना कीजिए। (√5 + √3)² = 5 + 3 + 2√15 = 8 + 2√15, और (√6 + √2)² = 6 + 2 + 2√12 = 8 + 2√12। चूँकि 15 > 12, √5 + √3 बड़ा है (लगभग 3.97 बनाम 3.86)। दोनों योगों में मूलों के भीतर की संख्याओं का जोड़ 8 है, जो उन्हें बराबर कहने को लुभाता है; और वर्ग करने से बिना कोई मूल निकाले बात तय हो जाती है।','csat-l4-s05-qa-nt-two-sums-of-square-roots-compared','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In an experiment published in 1990, the economists Daniel Kahneman, Jack Knetsch and Richard Thaler gave coffee mugs to half the students in a class, chosen at random, and let them trade with the others. Since the mugs had gone to students at random, about half should have ended up with those who valued them most, and many mugs should have changed hands. Few did. The owners'' typical asking price was more than twice what the others were willing to pay. Owning the mug, even for a few minutes, seemed to make it worth more to its owner. A common explanation is that giving something up is felt as a loss, and losses weigh more heavily than gains of the same size. The effect is not universal, though: studies of experienced traders, who buy things in order to sell them, find it much weaker.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1990 में प्रकाशित एक प्रयोग में अर्थशास्त्री डेनियल काह्नमन, जैक नेच और रिचर्ड थेलर ने एक कक्षा के आधे विद्यार्थियों को, यादृच्छिक रूप से चुनकर, कॉफ़ी के मग दिए और उन्हें बाक़ी के साथ लेन-देन करने दिया। चूँकि मग यादृच्छिक रूप से दिए गए थे, लगभग आधे उन तक पहुँचने चाहिए थे जो उन्हें सबसे अधिक महत्त्व देते, और बहुत-से मग हाथ बदलने चाहिए थे। बहुत कम बदले। मालिकों का सामान्य माँगा गया मूल्य उससे दोगुने से भी अधिक था जो बाक़ी देने को तैयार थे। मग का मालिक होना, कुछ मिनटों के लिए भी, उसे उसके मालिक के लिए अधिक मूल्यवान बनाता लगा। एक आम व्याख्या यह है कि कुछ छोड़ना हानि जैसा लगता है, और हानियाँ उतने ही बड़े लाभों से अधिक भारी पड़ती हैं। फिर भी यह प्रभाव सार्वभौमिक नहीं: अनुभवी व्यापारियों के अध्ययन, जो चीज़ें बेचने के लिए ही ख़रीदते हैं, इसे बहुत कमज़ोर पाते हैं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p02", "csat_order": 12}'::jsonb,'[{"id": "a", "body": "The students refused to trade at all, because they had been given the mugs as a gift.", "body_hi": "विद्यार्थियों ने लेन-देन से ही पूरी तरह मना कर दिया, क्योंकि मग उन्हें उपहार में मिले थे।", "isCorrect": false}, {"id": "b", "body": "The mugs given to the owners were better than those the other students could buy elsewhere.", "body_hi": "मालिकों को दिए गए मग उनसे बेहतर थे जो बाक़ी विद्यार्थी कहीं और ख़रीद सकते थे।", "isCorrect": false}, {"id": "c", "body": "People tend to value a thing more once they own it, though trading experience weakens this.", "body_hi": "लोग किसी चीज़ का मालिक बनने पर उसे अधिक महत्त्व देते हैं, यद्यपि व्यापार का अनुभव इसे कमज़ोर करता है।", "isCorrect": true}, {"id": "d", "body": "Owning a thing makes everyone value it more, and no amount of experience can change this.", "body_hi": "किसी चीज़ का मालिक होना हर व्यक्ति के लिए उसका मूल्य बढ़ा देता है, और कोई भी अनुभव इसे नहीं बदल सकता।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage reports that owning a mug made its owner value it more, explains this by the weight of losses, and limits the claim: experienced traders show the effect much less. It says few mugs changed hands, not that students refused to trade at all; it treats the effect as weaker among traders, not as absent everywhere; and it gives no reason to think the mugs differed in quality.','परिच्छेद बताता है कि मग का मालिक होना मालिक के लिए उसका मूल्य बढ़ा देता था, इसे हानियों के भार से समझाता है, और दावे को सीमित करता है: अनुभवी व्यापारियों में प्रभाव बहुत कम दिखता है। वह कहता है कि बहुत कम मग हाथ बदले, यह नहीं कि विद्यार्थियों ने लेन-देन से ही मना कर दिया; वह प्रभाव को व्यापारियों में कमज़ोर बताता है, हर जगह अनुपस्थित नहीं; और यह मानने का कोई कारण नहीं देता कि मग गुणवत्ता में अलग थे।','csat-l4-s05-rc-p02-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In an experiment published in 1990, the economists Daniel Kahneman, Jack Knetsch and Richard Thaler gave coffee mugs to half the students in a class, chosen at random, and let them trade with the others. Since the mugs had gone to students at random, about half should have ended up with those who valued them most, and many mugs should have changed hands. Few did. The owners'' typical asking price was more than twice what the others were willing to pay. Owning the mug, even for a few minutes, seemed to make it worth more to its owner. A common explanation is that giving something up is felt as a loss, and losses weigh more heavily than gains of the same size. The effect is not universal, though: studies of experienced traders, who buy things in order to sell them, find it much weaker.

Which one of the following is best explained by the effect the passage describes?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1990 में प्रकाशित एक प्रयोग में अर्थशास्त्री डेनियल काह्नमन, जैक नेच और रिचर्ड थेलर ने एक कक्षा के आधे विद्यार्थियों को, यादृच्छिक रूप से चुनकर, कॉफ़ी के मग दिए और उन्हें बाक़ी के साथ लेन-देन करने दिया। चूँकि मग यादृच्छिक रूप से दिए गए थे, लगभग आधे उन तक पहुँचने चाहिए थे जो उन्हें सबसे अधिक महत्त्व देते, और बहुत-से मग हाथ बदलने चाहिए थे। बहुत कम बदले। मालिकों का सामान्य माँगा गया मूल्य उससे दोगुने से भी अधिक था जो बाक़ी देने को तैयार थे। मग का मालिक होना, कुछ मिनटों के लिए भी, उसे उसके मालिक के लिए अधिक मूल्यवान बनाता लगा। एक आम व्याख्या यह है कि कुछ छोड़ना हानि जैसा लगता है, और हानियाँ उतने ही बड़े लाभों से अधिक भारी पड़ती हैं। फिर भी यह प्रभाव सार्वभौमिक नहीं: अनुभवी व्यापारियों के अध्ययन, जो चीज़ें बेचने के लिए ही ख़रीदते हैं, इसे बहुत कमज़ोर पाते हैं।

परिच्छेद में वर्णित प्रभाव निम्नलिखित में से किसकी सबसे अच्छी व्याख्या करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p02", "csat_order": 13}'::jsonb,'[{"id": "a", "body": "A car dealer who sells most of the cars on the lot within a week of buying them", "body_hi": "ऐसा कार डीलर जो अहाते की अधिकांश गाड़ियाँ ख़रीदने के एक सप्ताह के भीतर बेच देता है", "isCorrect": false}, {"id": "b", "body": "A shopper who checks the price of a phone in three different shops before deciding to buy it", "body_hi": "ऐसा ख़रीदार जो फ़ोन ख़रीदने का निर्णय लेने से पहले तीन अलग-अलग दुकानों में उसका दाम देखता है", "isCorrect": false}, {"id": "c", "body": "A shop that raises the price of umbrellas on the first rainy day of the season", "body_hi": "ऐसी दुकान जो मौसम के पहले बरसाती दिन छातों के दाम बढ़ा देती है", "isCorrect": false}, {"id": "d", "body": "A family that would not sell its scooter at a price it would not pay for the same model", "body_hi": "ऐसा परिवार जो अपना स्कूटर उस मूल्य पर नहीं बेचेगा जो वह वैसे ही मॉडल के लिए नहीं देगा", "isCorrect": true}]'::jsonb,2.5,0.83,'The effect is that owning a thing raises the value its owner puts on it, because giving it up feels like a loss. A family that would not sell its old scooter for the price it would not pay for an identical one shows exactly that gap between selling and buying. A dealer who sells stock quickly is the experienced trader in whom the effect is weak; a buyer comparing prices is ordinary shopping; and a shop raising prices when demand rises is about the market, not about ownership.','प्रभाव यह है कि किसी चीज़ का मालिक होना उस पर मालिक द्वारा लगाया गया मूल्य बढ़ा देता है, क्योंकि उसे छोड़ना हानि जैसा लगता है। जो परिवार अपना पुराना स्कूटर उस मूल्य पर नहीं बेचेगा जिस पर वह वैसा ही दूसरा स्कूटर ख़रीदेगा भी नहीं, वह बेचने और ख़रीदने के बीच ठीक वही अंतर दिखाता है। माल जल्दी बेचने वाला डीलर वही अनुभवी व्यापारी है जिसमें प्रभाव कमज़ोर है; दाम मिलाने वाला ख़रीदार सामान्य ख़रीदारी है; और माँग बढ़ने पर दाम बढ़ाने वाली दुकान बाज़ार के बारे में है, स्वामित्व के बारे में नहीं।','csat-l4-s05-rc-p02-what-the-effect-explains','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In an experiment published in 1990, the economists Daniel Kahneman, Jack Knetsch and Richard Thaler gave coffee mugs to half the students in a class, chosen at random, and let them trade with the others. Since the mugs had gone to students at random, about half should have ended up with those who valued them most, and many mugs should have changed hands. Few did. The owners'' typical asking price was more than twice what the others were willing to pay. Owning the mug, even for a few minutes, seemed to make it worth more to its owner. A common explanation is that giving something up is felt as a loss, and losses weigh more heavily than gains of the same size. The effect is not universal, though: studies of experienced traders, who buy things in order to sell them, find it much weaker.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1990 में प्रकाशित एक प्रयोग में अर्थशास्त्री डेनियल काह्नमन, जैक नेच और रिचर्ड थेलर ने एक कक्षा के आधे विद्यार्थियों को, यादृच्छिक रूप से चुनकर, कॉफ़ी के मग दिए और उन्हें बाक़ी के साथ लेन-देन करने दिया। चूँकि मग यादृच्छिक रूप से दिए गए थे, लगभग आधे उन तक पहुँचने चाहिए थे जो उन्हें सबसे अधिक महत्त्व देते, और बहुत-से मग हाथ बदलने चाहिए थे। बहुत कम बदले। मालिकों का सामान्य माँगा गया मूल्य उससे दोगुने से भी अधिक था जो बाक़ी देने को तैयार थे। मग का मालिक होना, कुछ मिनटों के लिए भी, उसे उसके मालिक के लिए अधिक मूल्यवान बनाता लगा। एक आम व्याख्या यह है कि कुछ छोड़ना हानि जैसा लगता है, और हानियाँ उतने ही बड़े लाभों से अधिक भारी पड़ती हैं। फिर भी यह प्रभाव सार्वभौमिक नहीं: अनुभवी व्यापारियों के अध्ययन, जो चीज़ें बेचने के लिए ही ख़रीदते हैं, इसे बहुत कमज़ोर पाते हैं।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["People who trade often never value the things they own more than other people do.", "Handing out the mugs at random was what allowed the gap in prices to be put down to owning them."], "statements_hi": ["बार-बार व्यापार करने वाले लोग अपनी चीज़ों को कभी भी दूसरों से अधिक महत्त्व नहीं देते।", "मगों को यादृच्छिक रूप से बाँटने से ही दामों के अंतर का कारण स्वामित्व को माना जा सका।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p02", "csat_order": 14}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is valid. The mugs went to students at random, so whether a student owned one had nothing to do with how much that student liked mugs; the gap between owners and others must come from owning itself. 1 goes too far: the passage reports a weaker effect among experienced traders, not that people who trade often never value what they own more.','केवल 2 वैध है। मग विद्यार्थियों को यादृच्छिक रूप से मिले थे, इसलिए किसी विद्यार्थी के पास मग होने का इससे कोई संबंध नहीं था कि उसे मग कितने पसंद थे; मालिकों और बाक़ी के बीच का अंतर स्वयं स्वामित्व से ही आया होगा। 1 बहुत आगे जाता है: परिच्छेद अनुभवी व्यापारियों में कमज़ोर प्रभाव बताता है, यह नहीं कि बार-बार व्यापार करने वाले अपनी चीज़ को कभी अधिक महत्त्व नहीं देते।','csat-l4-s05-rc-p02-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','hard','A car runs 15 km on a litre of petrol in the city and 20 km on a litre on the highway. On a trip of 60 km in the city and 240 km on the highway, how many kilometres does it run per litre for the trip as a whole?','एक गाड़ी शहर में एक लीटर पेट्रोल में 15 किमी और राजमार्ग पर एक लीटर में 20 किमी चलती है। शहर में 60 किमी और राजमार्ग पर 240 किमी की एक यात्रा में, पूरी यात्रा के लिए वह प्रति लीटर कितने किलोमीटर चलती है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 15}'::jsonb,'[{"id": "a", "body": "17.5 km per litre", "body_hi": "17.5 किमी प्रति लीटर", "isCorrect": false}, {"id": "b", "body": "18.75 km per litre", "body_hi": "18.75 किमी प्रति लीटर", "isCorrect": true}, {"id": "c", "body": "19 km per litre", "body_hi": "19 किमी प्रति लीटर", "isCorrect": false}, {"id": "d", "body": "20 km per litre", "body_hi": "20 किमी प्रति लीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'Find the petrol used: 60 ÷ 15 = 4 litres in the city and 240 ÷ 20 = 12 litres on the highway, 16 litres for 300 km. That is 300 ÷ 16 = 18.75 km per litre. 17.5 averages the two figures as if the trip were split evenly; 19 weights them by distance (0.2 × 15 + 0.8 × 20), but the figures must be weighted by petrol used, not by kilometres; 20 is the highway figure alone.','उपयोग हुआ पेट्रोल निकालिए: शहर में 60 ÷ 15 = 4 लीटर और राजमार्ग पर 240 ÷ 20 = 12 लीटर, 300 किमी के लिए 16 लीटर। यानी 300 ÷ 16 = 18.75 किमी प्रति लीटर। 17.5 दोनों आँकड़ों का ऐसा औसत लेता है मानो यात्रा बराबर बँटी हो; 19 उन्हें दूरी से भारित करता है (0.2 × 15 + 0.8 × 20), पर आँकड़ों को किलोमीटर से नहीं, उपयोग हुए पेट्रोल से भारित करना होता है; 20 केवल राजमार्ग का आँकड़ा है।','csat-l4-s05-qa-rm-fuel-economy-over-a-mixed-trip','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','hard','In a survey of 10,000 adults, those who drank green tea every day had fewer heart attacks over ten years than those who did not. A tea company concludes that drinking green tea protects the heart. Which one of the following, if true, would most strengthen the company''s conclusion?','10,000 वयस्कों के एक सर्वेक्षण में, जो लोग प्रतिदिन ग्रीन टी पीते थे उन्हें दस वर्षों में न पीने वालों की तुलना में कम दिल के दौरे पड़े। एक चाय कंपनी निष्कर्ष निकालती है कि ग्रीन टी पीना दिल की रक्षा करता है। निम्नलिखित में से कौन-सा, यदि सत्य हो, कंपनी के निष्कर्ष को सबसे अधिक मज़बूत करेगा?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 16}'::jsonb,'[{"id": "a", "body": "The daily green tea drinkers in the survey were, on average, younger and more active than the people who did not drink it.", "body_hi": "सर्वेक्षण में प्रतिदिन ग्रीन टी पीने वाले, औसतन, उसे न पीने वालों से कम आयु के और अधिक सक्रिय थे।", "isCorrect": false}, {"id": "b", "body": "Among people alike in diet, exercise and smoking, the daily tea drinkers still had fewer heart attacks.", "body_hi": "आहार, व्यायाम और धूम्रपान में समान लोगों में भी प्रतिदिन चाय पीने वालों को कम दिल के दौरे पड़े।", "isCorrect": true}, {"id": "c", "body": "The survey was paid for by a group of companies that sell green tea in many countries, including the company in question.", "body_hi": "सर्वेक्षण का ख़र्च ऐसी कंपनियों के एक समूह ने उठाया जो इस कंपनी सहित कई देशों में ग्रीन टी बेचती हैं।", "isCorrect": false}, {"id": "d", "body": "Green tea is drunk far more often in some regions of the country than in others, as the survey itself went on to find.", "body_hi": "जैसा सर्वेक्षण ने आगे पाया, देश के कुछ क्षेत्रों में ग्रीन टी दूसरों की तुलना में कहीं अधिक पी जाती है।", "isCorrect": false}]'::jsonb,2.5,0.83,'The survey shows only that tea drinkers had fewer heart attacks. The worry is that they differed in other ways that protect the heart. If the difference remains among people who are alike in diet, exercise and smoking, those other explanations are ruled out and the tea itself becomes the likelier cause. Younger, more active tea drinkers would offer exactly such another explanation, weakening the conclusion; who paid for the survey bears on trust in it, not on whether tea protects the heart; and where tea is drunk is beside the point.','सर्वेक्षण केवल यह दिखाता है कि चाय पीने वालों को कम दिल के दौरे पड़े। चिंता यह है कि वे अन्य ऐसे तरीक़ों से अलग थे जो दिल की रक्षा करते हैं। यदि आहार, व्यायाम और धूम्रपान में समान लोगों में भी अंतर बना रहे, तो वे अन्य व्याख्याएँ ख़ारिज हो जाती हैं और स्वयं चाय अधिक संभावित कारण बनती है। कम आयु के, अधिक सक्रिय चाय पीने वाले ठीक ऐसी ही एक अन्य व्याख्या देते, जो निष्कर्ष को कमज़ोर करती; सर्वेक्षण का ख़र्च किसने उठाया यह उस पर भरोसे से जुड़ा है, इससे नहीं कि चाय दिल की रक्षा करती है या नहीं; और चाय कहाँ पी जाती है, यह अप्रासंगिक है।','csat-l4-s05-lr-sc-what-would-show-that-green-tea-protects-the-heart','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','What is the remainder when 17²³ is divided by 16?','17²³ को 16 से भाग देने पर शेषफल क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 17}'::jsonb,'[{"id": "a", "body": "1", "body_hi": "1", "isCorrect": true}, {"id": "b", "body": "7", "body_hi": "7", "isCorrect": false}, {"id": "c", "body": "15", "body_hi": "15", "isCorrect": false}, {"id": "d", "body": "16", "body_hi": "16", "isCorrect": false}]'::jsonb,2.5,0.83,'17 = 16 + 1, so 17 leaves remainder 1 on division by 16, and so does every power of it: 1 × 1 × ... × 1 = 1. 7 is the last digit of 17, which has nothing to do with division by 16; 15 would be right for 15²³ or for an odd power of a number one less than a multiple of 16; and a remainder on division by 16 can never be 16.','17 = 16 + 1, इसलिए 17 को 16 से भाग देने पर शेष 1 बचता है, और उसकी हर घात के साथ भी: 1 × 1 × ... × 1 = 1। 7, 17 का अंतिम अंक है, जिसका 16 से भाग से कोई संबंध नहीं; 15 तब सही होता जब संख्या 16 के गुणज से एक कम हो और घात विषम; और 16 से भाग देने पर शेष कभी 16 नहीं हो सकता।','csat-l4-s05-qa-nt-17-to-the-23rd-divided-by-16','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Time & Work','mcq','medium','A worker who works 8 hours a day finishes a job in 15 days. How many days would the job take if the worker worked 9 hours a day, but got through only 80 per cent as much in each hour as before?','8 घंटे प्रतिदिन काम करने वाला एक कामगार एक काम 15 दिनों में पूरा करता है। यदि कामगार 9 घंटे प्रतिदिन काम करे, पर हर घंटे में पहले का केवल 80 प्रतिशत काम कर पाए, तो काम कितने दिनों में होगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 18}'::jsonb,'[{"id": "a", "body": "13⅓ days", "body_hi": "13⅓ दिन", "isCorrect": false}, {"id": "b", "body": "15 days", "body_hi": "15 दिन", "isCorrect": false}, {"id": "c", "body": "16⅔ days", "body_hi": "16⅔ दिन", "isCorrect": true}, {"id": "d", "body": "18¾ days", "body_hi": "18¾ दिन", "isCorrect": false}]'::jsonb,2.5,0.83,'The job needs 8 × 15 = 120 hours at the old rate. Each new day gives 9 × 0.8 = 7.2 such hours, so the job takes 120 ÷ 7.2 = 16⅔ days. 13⅓ days counts the longer days but not the slower rate (120 ÷ 9); 18¾ days counts the slower rate but not the longer days (15 ÷ 0.8); 15 days assumes the two cancel out.','पुरानी दर पर काम के लिए 8 × 15 = 120 घंटे चाहिए। हर नया दिन ऐसे 9 × 0.8 = 7.2 घंटे देता है, इसलिए काम 120 ÷ 7.2 = 16⅔ दिनों में होता है। 13⅓ दिन लंबे दिनों को गिनता है पर धीमी दर को नहीं (120 ÷ 9); 18¾ दिन धीमी दर को गिनता है पर लंबे दिनों को नहीं (15 ÷ 0.8); 15 दिन मान लेता है कि दोनों एक-दूसरे को काट देते हैं।','csat-l4-s05-qa-tw-longer-days-at-a-lower-rate','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','medium','A bus travels 200 km at a steady 50 km/h. It stops for 10 minutes after every 50 km, but not at the end of the journey. How long does the whole journey take?','एक बस 200 किमी की दूरी स्थिर 50 किमी/घंटा से तय करती है। वह हर 50 किमी के बाद 10 मिनट रुकती है, पर यात्रा के अंत में नहीं। पूरी यात्रा में कितना समय लगता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 19}'::jsonb,'[{"id": "a", "body": "4 h 10 min", "body_hi": "4 घंटे 10 मिनट", "isCorrect": false}, {"id": "b", "body": "4 h 20 min", "body_hi": "4 घंटे 20 मिनट", "isCorrect": false}, {"id": "c", "body": "4 h 30 min", "body_hi": "4 घंटे 30 मिनट", "isCorrect": true}, {"id": "d", "body": "4 h 40 min", "body_hi": "4 घंटे 40 मिनट", "isCorrect": false}]'::jsonb,2.5,0.83,'Driving takes 200 ÷ 50 = 4 hours. The 200 km fall into four stretches of 50 km, and the bus stops between them -- after 50, 100 and 150 km -- but not after the last, so there are 3 stops, 30 minutes. In all 4 h 30 min. 4 h 40 min adds a fourth stop at the end; 4 h 20 min and 4 h 10 min count only two stops or one.','गाड़ी चलाने में 200 ÷ 50 = 4 घंटे लगते हैं। 200 किमी, 50 किमी के चार हिस्सों में बँटते हैं, और बस उनके बीच रुकती है -- 50, 100 और 150 किमी के बाद -- पर अंतिम के बाद नहीं, इसलिए 3 ठहराव, 30 मिनट। कुल 4 घंटे 30 मिनट। 4 घंटे 40 मिनट अंत में चौथा ठहराव जोड़ता है; 4 घंटे 20 मिनट और 4 घंटे 10 मिनट केवल दो या एक ठहराव गिनते हैं।','csat-l4-s05-qa-sdt-stops-between-the-stages','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In the 1840s, in the maternity wards of Vienna''s General Hospital, women delivered by doctors and medical students died of childbed fever far more often than women delivered by midwives in the neighbouring ward. The physician Ignaz Semmelweis noticed that the doctors often came to the ward straight from dissecting corpses. In 1847 he made them wash their hands in a solution of chlorinated lime before examining patients, and deaths in their ward fell sharply. Yet many senior doctors rejected his conclusion. Some were offended by the suggestion that they themselves carried disease, and Semmelweis could not explain how matter from corpses caused fever. His practice spread widely only decades later, after the work of Louis Pasteur and Joseph Lister had shown that germs cause infection. The evidence had been there; what was missing was an account of why it should be true.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1840 के दशक में, वियना के जनरल अस्पताल के प्रसूति वार्डों में, डॉक्टरों और चिकित्सा विद्यार्थियों द्वारा प्रसव कराई गई महिलाएँ पड़ोसी वार्ड में दाइयों द्वारा प्रसव कराई गई महिलाओं की तुलना में प्रसूति ज्वर से कहीं अधिक मरती थीं। चिकित्सक इग्नाज़ सेमेलवाइस ने देखा कि डॉक्टर प्रायः शवों की चीर-फाड़ से सीधे वार्ड में आते थे। 1847 में उन्होंने उन्हें रोगियों की जाँच से पहले क्लोरीनयुक्त चूने के घोल में हाथ धोने को कहा, और उनके वार्ड में मौतें तेज़ी से घटीं। फिर भी कई वरिष्ठ डॉक्टरों ने उनके निष्कर्ष को ठुकरा दिया। कुछ इस सुझाव से आहत हुए कि वे स्वयं रोग ले जाते हैं, और सेमेलवाइस यह नहीं समझा सके कि शवों का पदार्थ ज्वर कैसे पैदा करता है। उनकी प्रथा दशकों बाद ही व्यापक रूप से फैली, जब लुई पाश्चर और जोसेफ़ लिस्टर के काम ने दिखाया कि कीटाणु संक्रमण पैदा करते हैं। प्रमाण मौजूद था; जो अनुपस्थित था वह इस बात की व्याख्या थी कि वह सत्य क्यों होना चाहिए।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p03", "csat_order": 20}'::jsonb,'[{"id": "a", "body": "Midwives in Vienna were better trained than the doctors and medical students of the hospital.", "body_hi": "वियना की दाइयाँ अस्पताल के डॉक्टरों और चिकित्सा विद्यार्थियों से बेहतर प्रशिक्षित थीं।", "isCorrect": false}, {"id": "b", "body": "The doctors were right to reject Semmelweis''s claim, since his evidence was too weak to trust.", "body_hi": "डॉक्टरों का सेमेलवाइस के दावे को ठुकराना सही था, क्योंकि उनका प्रमाण भरोसे के लिए बहुत कमज़ोर था।", "isCorrect": false}, {"id": "c", "body": "Strong evidence can be resisted for years when it wounds pride and no one can yet explain it.", "body_hi": "मज़बूत प्रमाण का वर्षों तक विरोध हो सकता है जब वह अहं को चोट पहुँचाए और कोई उसे अभी समझा न सके।", "isCorrect": true}, {"id": "d", "body": "Washing hands in chlorinated lime is still the best protection against all infections in hospitals.", "body_hi": "क्लोरीनयुक्त चूने से हाथ धोना आज भी अस्पतालों में सभी संक्रमणों से सबसे अच्छी सुरक्षा है।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage tells how clear evidence that handwashing saved lives was resisted -- partly from pride, partly because no one could yet explain it -- until germ theory supplied the explanation. It says deaths fell sharply, so the evidence was not weak; it does not say midwives were better trained; and it presents the rejection as a failure, not as sound caution that was later proved right.','परिच्छेद बताता है कि हाथ धोने से जान बचने के स्पष्ट प्रमाण का विरोध हुआ -- कुछ अहं से, कुछ इसलिए कि तब कोई उसे समझा नहीं सकता था -- जब तक कीटाणु सिद्धांत ने व्याख्या नहीं दी। वह कहता है कि मौतें तेज़ी से घटीं, इसलिए प्रमाण कमज़ोर नहीं था; वह यह नहीं कहता कि दाइयाँ बेहतर प्रशिक्षित थीं; और वह अस्वीकृति को एक विफलता के रूप में रखता है, ऐसी समझदार सावधानी के रूप में नहीं जो बाद में सही सिद्ध हुई।','csat-l4-s05-rc-p03-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In the 1840s, in the maternity wards of Vienna''s General Hospital, women delivered by doctors and medical students died of childbed fever far more often than women delivered by midwives in the neighbouring ward. The physician Ignaz Semmelweis noticed that the doctors often came to the ward straight from dissecting corpses. In 1847 he made them wash their hands in a solution of chlorinated lime before examining patients, and deaths in their ward fell sharply. Yet many senior doctors rejected his conclusion. Some were offended by the suggestion that they themselves carried disease, and Semmelweis could not explain how matter from corpses caused fever. His practice spread widely only decades later, after the work of Louis Pasteur and Joseph Lister had shown that germs cause infection. The evidence had been there; what was missing was an account of why it should be true.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1840 के दशक में, वियना के जनरल अस्पताल के प्रसूति वार्डों में, डॉक्टरों और चिकित्सा विद्यार्थियों द्वारा प्रसव कराई गई महिलाएँ पड़ोसी वार्ड में दाइयों द्वारा प्रसव कराई गई महिलाओं की तुलना में प्रसूति ज्वर से कहीं अधिक मरती थीं। चिकित्सक इग्नाज़ सेमेलवाइस ने देखा कि डॉक्टर प्रायः शवों की चीर-फाड़ से सीधे वार्ड में आते थे। 1847 में उन्होंने उन्हें रोगियों की जाँच से पहले क्लोरीनयुक्त चूने के घोल में हाथ धोने को कहा, और उनके वार्ड में मौतें तेज़ी से घटीं। फिर भी कई वरिष्ठ डॉक्टरों ने उनके निष्कर्ष को ठुकरा दिया। कुछ इस सुझाव से आहत हुए कि वे स्वयं रोग ले जाते हैं, और सेमेलवाइस यह नहीं समझा सके कि शवों का पदार्थ ज्वर कैसे पैदा करता है। उनकी प्रथा दशकों बाद ही व्यापक रूप से फैली, जब लुई पाश्चर और जोसेफ़ लिस्टर के काम ने दिखाया कि कीटाणु संक्रमण पैदा करते हैं। प्रमाण मौजूद था; जो अनुपस्थित था वह इस बात की व्याख्या थी कि वह सत्य क्यों होना चाहिए।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Semmelweis was wrong to think that the doctors'' hands carried the cause of the fever.", "The senior doctors rejected Semmelweis''s conclusion only because it hurt their pride."], "statements_hi": ["सेमेलवाइस का यह सोचना ग़लत था कि डॉक्टरों के हाथ ज्वर का कारण ले जाते थे।", "वरिष्ठ डॉक्टरों ने सेमेलवाइस के निष्कर्ष को केवल इसलिए ठुकराया कि उससे उनके अहं को चोट पहुँची।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p03", "csat_order": 21}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2.5,0.83,'Neither is valid. 1 goes beyond the passage: it says Semmelweis could not explain how matter from corpses caused fever, but nothing in it says he was wrong that hands carried it -- the fall in deaths and the later germ theory both support him. 2 also goes too far: the passage says some doctors were offended, and that the explanation was missing, but not that they rejected the idea only out of pride; it names two reasons.','कोई भी वैध नहीं। 1 परिच्छेद से आगे जाता है: वह कहता है कि सेमेलवाइस समझा नहीं सके कि शवों का पदार्थ ज्वर कैसे पैदा करता है, पर उसमें कुछ भी यह नहीं कहता कि हाथों के उसे ले जाने के बारे में वे ग़लत थे -- मौतों का घटना और बाद का कीटाणु सिद्धांत दोनों उनका समर्थन करते हैं। 2 भी बहुत आगे जाता है: परिच्छेद कहता है कि कुछ डॉक्टर आहत हुए, और कि व्याख्या अनुपस्थित थी, पर यह नहीं कि उन्होंने विचार को केवल अहं के कारण ठुकराया; वह दो कारण बताता है।','csat-l4-s05-rc-p03-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In the 1840s, in the maternity wards of Vienna''s General Hospital, women delivered by doctors and medical students died of childbed fever far more often than women delivered by midwives in the neighbouring ward. The physician Ignaz Semmelweis noticed that the doctors often came to the ward straight from dissecting corpses. In 1847 he made them wash their hands in a solution of chlorinated lime before examining patients, and deaths in their ward fell sharply. Yet many senior doctors rejected his conclusion. Some were offended by the suggestion that they themselves carried disease, and Semmelweis could not explain how matter from corpses caused fever. His practice spread widely only decades later, after the work of Louis Pasteur and Joseph Lister had shown that germs cause infection. The evidence had been there; what was missing was an account of why it should be true.

Why does the passage mention that the women delivered by midwives died less often?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1840 के दशक में, वियना के जनरल अस्पताल के प्रसूति वार्डों में, डॉक्टरों और चिकित्सा विद्यार्थियों द्वारा प्रसव कराई गई महिलाएँ पड़ोसी वार्ड में दाइयों द्वारा प्रसव कराई गई महिलाओं की तुलना में प्रसूति ज्वर से कहीं अधिक मरती थीं। चिकित्सक इग्नाज़ सेमेलवाइस ने देखा कि डॉक्टर प्रायः शवों की चीर-फाड़ से सीधे वार्ड में आते थे। 1847 में उन्होंने उन्हें रोगियों की जाँच से पहले क्लोरीनयुक्त चूने के घोल में हाथ धोने को कहा, और उनके वार्ड में मौतें तेज़ी से घटीं। फिर भी कई वरिष्ठ डॉक्टरों ने उनके निष्कर्ष को ठुकरा दिया। कुछ इस सुझाव से आहत हुए कि वे स्वयं रोग ले जाते हैं, और सेमेलवाइस यह नहीं समझा सके कि शवों का पदार्थ ज्वर कैसे पैदा करता है। उनकी प्रथा दशकों बाद ही व्यापक रूप से फैली, जब लुई पाश्चर और जोसेफ़ लिस्टर के काम ने दिखाया कि कीटाणु संक्रमण पैदा करते हैं। प्रमाण मौजूद था; जो अनुपस्थित था वह इस बात की व्याख्या थी कि वह सत्य क्यों होना चाहिए।

परिच्छेद यह उल्लेख क्यों करता है कि दाइयों द्वारा प्रसव कराई गई महिलाएँ कम मरती थीं?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p03", "csat_order": 22}'::jsonb,'[{"id": "a", "body": "It is a comparison pointing to something the doctors did and the midwives did not.", "body_hi": "यह ऐसी तुलना देता है जिसने उस बात की ओर संकेत किया जो डॉक्टर करते थे और दाइयाँ नहीं।", "isCorrect": true}, {"id": "b", "body": "It shows that midwives were more skilful than doctors at delivering babies safely.", "body_hi": "यह दिखाता है कि दाइयाँ सुरक्षित प्रसव कराने में डॉक्टरों से अधिक कुशल थीं।", "isCorrect": false}, {"id": "c", "body": "It shows that the two wards had different rules about who could visit the mothers.", "body_hi": "यह दिखाता है कि दोनों वार्डों में माताओं से मिलने के नियम अलग-अलग थे।", "isCorrect": false}, {"id": "d", "body": "It proves that germs cause infection, which Pasteur and Lister merely confirmed later.", "body_hi": "यह सिद्ध करता है कि कीटाणु संक्रमण पैदा करते हैं, जिसकी पाश्चर और लिस्टर ने बाद में केवल पुष्टि की।", "isCorrect": false}]'::jsonb,2.5,0.83,'The midwives'' ward is the comparison that pointed to the cause: in the same hospital, women delivered by people who did not come from dissecting corpses died less often. That made the doctors'' hands the thing to look at. The passage does not say midwives were more skilled, that the two wards had different rules about visitors, or that the comparison proved germ theory, which came decades later.','दाइयों का वार्ड वह तुलना है जिसने कारण की ओर संकेत किया: उसी अस्पताल में, जिन महिलाओं का प्रसव शवों की चीर-फाड़ से न आने वाले लोगों ने कराया, वे कम मरीं। इससे डॉक्टरों के हाथ ही देखने लायक़ बात बने। परिच्छेद यह नहीं कहता कि दाइयाँ अधिक कुशल थीं, कि दोनों वार्डों में आगंतुकों के नियम अलग थे, या कि तुलना ने कीटाणु सिद्धांत सिद्ध किया, जो दशकों बाद आया।','csat-l4-s05-rc-p03-why-the-midwives-ward-matters','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','medium','A famous cricketer appears in an advertisement saying that a certain brand of cement is the strongest in the country. A viewer says, ''He is one of the greatest players of our time, so this must be the best cement.'' Which one of the following best describes the flaw in the viewer''s reasoning?','एक प्रसिद्ध क्रिकेटर एक विज्ञापन में कहता है कि सीमेंट का एक ब्रांड देश में सबसे मज़बूत है। एक दर्शक कहता है, ''वह हमारे समय के सबसे महान खिलाड़ियों में से एक है, इसलिए यही सबसे अच्छा सीमेंट होगा।'' निम्नलिखित में से कौन-सा दर्शक के तर्क की त्रुटि का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 23}'::jsonb,'[{"id": "a", "body": "It rejects the claim only because the person making it is being paid to advertise the cement.", "body_hi": "यह दावे को केवल इसलिए ठुकरा देता है कि दावा करने वाले को सीमेंट के विज्ञापन के पैसे मिल रहे हैं।", "isCorrect": false}, {"id": "b", "body": "It concludes that all brands of cement are equally strong because none of them has been tested.", "body_hi": "यह इस आधार पर कि किसी की जाँच नहीं हुई, निष्कर्ष निकालता है कि सीमेंट के सभी ब्रांड बराबर मज़बूत हैं।", "isCorrect": false}, {"id": "c", "body": "It assumes that a cement used by many builders must be stronger than any other cement.", "body_hi": "यह मान लेता है कि कई निर्माताओं द्वारा उपयोग किया जाने वाला सीमेंट किसी भी अन्य सीमेंट से मज़बूत होगा।", "isCorrect": false}, {"id": "d", "body": "It treats excellence in one field as if it gave expert knowledge in an unrelated one.", "body_hi": "यह एक क्षेत्र की उत्कृष्टता को किसी असंबंधित क्षेत्र के विशेषज्ञ ज्ञान जैसा मान लेता है।", "isCorrect": true}]'::jsonb,2.5,0.83,'Being a great cricketer gives no special knowledge of how strong cement is. The viewer accepts the claim because of who made it, though the speaker''s authority lies in a field that has nothing to do with the claim; what would count is evidence from tests of the cement. The viewer accepts the claim rather than rejecting it; draws no conclusion that all brands are equal; and says nothing about how many builders use the cement.','महान क्रिकेटर होना सीमेंट की मज़बूती का कोई विशेष ज्ञान नहीं देता। दर्शक दावे को इसलिए स्वीकार करता है कि उसे किसने किया, जबकि वक्ता का अधिकार ऐसे क्षेत्र में है जिसका दावे से कोई संबंध नहीं; जो मायने रखता वह सीमेंट की जाँच से मिला प्रमाण होता। दर्शक दावे को ठुकराता नहीं, स्वीकार करता है; वह यह निष्कर्ष नहीं निकालता कि सभी ब्रांड बराबर हैं; और यह नहीं कहता कि कितने निर्माता उस सीमेंट का उपयोग करते हैं।','csat-l4-s05-lr-sc-a-cricketer-s-word-on-cement','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','What is the sum of all the whole numbers from 1 to 100 that are not multiples of 3?','1 से 100 तक की उन सभी पूर्ण संख्याओं का योग क्या है जो 3 के गुणज नहीं हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 24}'::jsonb,'[{"id": "a", "body": "1,683", "body_hi": "1,683", "isCorrect": false}, {"id": "b", "body": "3,333", "body_hi": "3,333", "isCorrect": false}, {"id": "c", "body": "3,367", "body_hi": "3,367", "isCorrect": true}, {"id": "d", "body": "5,050", "body_hi": "5,050", "isCorrect": false}]'::jsonb,2.5,0.83,'The numbers from 1 to 100 add up to 5,050. The multiples of 3 among them are 3, 6, ..., 99, that is 3 × (1 + 2 + ... + 33) = 3 × 561 = 1,683. Taking these away leaves 5,050 - 1,683 = 3,367. 1,683 is the sum of the multiples, not of the rest; 5,050 is the sum of all the numbers; 3,333 has no basis.','1 से 100 तक की संख्याओं का योग 5,050 है। उनमें 3 के गुणज 3, 6, ..., 99 हैं, यानी 3 × (1 + 2 + ... + 33) = 3 × 561 = 1,683। इन्हें घटाने पर 5,050 - 1,683 = 3,367 बचता है। 1,683 गुणजों का योग है, बाक़ी का नहीं; 5,050 सभी संख्याओं का योग है; 3,333 का कोई आधार नहीं।','csat-l4-s05-qa-nt-1-to-100-without-the-multiples-of-3','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','easy','₹7,000 is divided among A, B and C so that A gets ₹600 more than B, and B gets ₹200 more than C. How much does A get?','₹7,000 को A, B और C में इस प्रकार बाँटा जाता है कि A को B से ₹600 अधिक और B को C से ₹200 अधिक मिलता है। A को कितना मिलता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 25}'::jsonb,'[{"id": "a", "body": "₹2,000", "body_hi": "₹2,000", "isCorrect": false}, {"id": "b", "body": "₹2,200", "body_hi": "₹2,200", "isCorrect": false}, {"id": "c", "body": "₹2,800", "body_hi": "₹2,800", "isCorrect": true}, {"id": "d", "body": "₹3,000", "body_hi": "₹3,000", "isCorrect": false}]'::jsonb,2.5,0.83,'If C gets x, B gets x + 200 and A gets x + 800, so 3x + 1,000 = 7,000 and x = 2,000. A gets 2,000 + 800 = ₹2,800. ₹2,000 is C''s share and ₹2,200 is B''s; ₹3,000 has no basis.','यदि C को x मिलता है, तो B को x + 200 और A को x + 800, इसलिए 3x + 1,000 = 7,000 और x = 2,000। A को 2,000 + 800 = ₹2,800 मिलते हैं। ₹2,000, C का हिस्सा है और ₹2,200, B का; ₹3,000 का कोई आधार नहीं।','csat-l4-s05-qa-rm-shares-that-differ-by-fixed-amounts','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Truth-Liar','mcq','hard','Of three friends, A, B and C, exactly one always tells the truth and the other two always lie. A says, ''I am the truth-teller.'' B says, ''A is lying.'' C says, ''B is the truth-teller.'' Which one of the following is correct?','तीन मित्रों, A, B और C, में से ठीक एक हमेशा सच बोलता है और बाक़ी दो हमेशा झूठ। A कहता है, ''सच बोलने वाला मैं हूँ।'' B कहता है, ''A झूठ बोल रहा है।'' C कहता है, ''सच बोलने वाला B है।'' निम्नलिखित में से कौन-सा सही है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 26}'::jsonb,'[{"id": "a", "body": "A is the truth-teller.", "body_hi": "सच बोलने वाला A है।", "isCorrect": true}, {"id": "b", "body": "B is the truth-teller.", "body_hi": "सच बोलने वाला B है।", "isCorrect": false}, {"id": "c", "body": "C is the truth-teller.", "body_hi": "सच बोलने वाला C है।", "isCorrect": false}, {"id": "d", "body": "Who tells the truth cannot be decided.", "body_hi": "सच कौन बोलता है, यह तय नहीं किया जा सकता।", "isCorrect": false}]'::jsonb,2.5,0.83,'Try each friend as the truth-teller. If B were, then C''s statement ''B is the truth-teller'' would be true -- but C would be a liar, so that fails. If C were, C''s own statement would make B the truth-teller as well, and there is only one -- that fails too. If A is the truth-teller, A''s statement is true; B''s ''A is lying'' is false, as a liar''s must be; and C''s ''B is the truth-teller'' is false, as it must be. Everything fits, so A is the truth-teller. A''s own claim proves nothing on its own, since a liar could say the same; it is B''s and C''s statements that decide it.','हर मित्र को सच बोलने वाला मानकर देखिए। यदि B होता, तो C का कथन ''सच बोलने वाला B है'' सत्य होता -- पर C झूठा होता, इसलिए यह विफल है। यदि C होता, तो C का अपना कथन B को भी सच बोलने वाला बना देता, जबकि ऐसा केवल एक है -- यह भी विफल। यदि A सच बोलने वाला है, तो A का कथन सत्य है; B का ''A झूठ बोल रहा है'' असत्य है, जैसा झूठे का होना चाहिए; और C का ''सच बोलने वाला B है'' असत्य है, जैसा होना चाहिए। सब ठीक बैठता है, इसलिए A सच बोलने वाला है। A का अपना दावा अकेले कुछ सिद्ध नहीं करता, क्योंकि झूठा भी यही कह सकता है; B और C के कथन ही इसे तय करते हैं।','csat-l4-s05-lr-tl-one-truth-teller-among-three-friends','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Part IV of the Constitution of India sets out the Directive Principles of State Policy: that the State should work towards adequate means of livelihood for all, equal pay for equal work, free and compulsory education for children, and much else. Article 37 says that these principles cannot be enforced by any court, and yet that they are fundamental in the governance of the country and that the State has a duty to apply them in making laws. The framers made them unenforceable not because they thought them unimportant, but because a poor new country could not promise to meet them all at once; they were goals to be reached as the State''s means grew. Over time some have moved closer to enforceable rights. Free and compulsory education for children aged six to fourteen, once a directive, was made a fundamental right by an amendment in 2002. A directive, then, is less a promise broken than a promise deferred.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
भारत के संविधान का भाग IV राज्य के नीति निदेशक तत्त्व बताता है: कि राज्य सबके लिए आजीविका के पर्याप्त साधनों, समान कार्य के लिए समान वेतन, बच्चों के लिए निःशुल्क और अनिवार्य शिक्षा, और बहुत कुछ की दिशा में काम करे। अनुच्छेद 37 कहता है कि ये तत्त्व किसी न्यायालय द्वारा लागू नहीं कराए जा सकते, फिर भी वे देश के शासन में मूलभूत हैं और क़ानून बनाते समय उन्हें लागू करना राज्य का कर्तव्य है। संविधान निर्माताओं ने उन्हें इसलिए अप्रवर्तनीय नहीं बनाया कि वे उन्हें महत्त्वहीन मानते थे, बल्कि इसलिए कि एक निर्धन नया देश उन सबको एक साथ पूरा करने का वचन नहीं दे सकता था; वे लक्ष्य थे जिन तक राज्य के साधन बढ़ने के साथ पहुँचना था। समय के साथ कुछ प्रवर्तनीय अधिकारों के निकट आए हैं। छह से चौदह वर्ष के बच्चों के लिए निःशुल्क और अनिवार्य शिक्षा, जो कभी एक निदेशक तत्त्व थी, 2002 के एक संशोधन द्वारा मौलिक अधिकार बना दी गई। अतः निदेशक तत्त्व टूटा हुआ वचन कम और स्थगित वचन अधिक है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p04", "csat_order": 27}'::jsonb,'[{"id": "a", "body": "The Directive Principles are words of good intention that have had no effect on any law.", "body_hi": "नीति निदेशक तत्त्व अच्छे इरादे के ऐसे शब्द हैं जिनका किसी क़ानून पर कोई प्रभाव नहीं पड़ा।", "isCorrect": false}, {"id": "b", "body": "The Directives were goals a poor country could not yet enforce, to be met as means grew.", "body_hi": "निदेशक तत्त्व निर्धन देश के अप्रवर्तनीय लक्ष्य थे, जिन्हें साधन बढ़ने पर पूरा करना था।", "isCorrect": true}, {"id": "c", "body": "Every Directive Principle can now be enforced in court like any fundamental right.", "body_hi": "हर नीति निदेशक तत्त्व अब किसी भी मौलिक अधिकार की तरह न्यायालय में लागू कराया जा सकता है।", "isCorrect": false}, {"id": "d", "body": "The framers thought the Directives less important than the other parts of the Constitution.", "body_hi": "संविधान निर्माता निदेशक तत्त्वों को संविधान के अन्य भागों से कम महत्त्वपूर्ण मानते थे।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage explains that the Directive Principles were made unenforceable because they could not all be met at once, not because they were unimportant, and shows one of them later becoming a right: a promise deferred. Article 37 calls them fundamental in governance, so they are not mere decoration; the passage does not say courts may enforce them now; and it shows them shaping law, not being ignored.','परिच्छेद बताता है कि नीति निदेशक तत्त्वों को इसलिए अप्रवर्तनीय बनाया गया कि वे सब एक साथ पूरे नहीं किए जा सकते थे, इसलिए नहीं कि वे महत्त्वहीन थे, और उनमें से एक को बाद में अधिकार बनते दिखाता है: एक स्थगित वचन। अनुच्छेद 37 उन्हें शासन में मूलभूत कहता है, इसलिए वे केवल सजावट नहीं; परिच्छेद यह नहीं कहता कि न्यायालय अब उन्हें लागू करा सकते हैं; और वह उन्हें क़ानून को आकार देते दिखाता है, अनदेखा होते नहीं।','csat-l4-s05-rc-p04-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Part IV of the Constitution of India sets out the Directive Principles of State Policy: that the State should work towards adequate means of livelihood for all, equal pay for equal work, free and compulsory education for children, and much else. Article 37 says that these principles cannot be enforced by any court, and yet that they are fundamental in the governance of the country and that the State has a duty to apply them in making laws. The framers made them unenforceable not because they thought them unimportant, but because a poor new country could not promise to meet them all at once; they were goals to be reached as the State''s means grew. Over time some have moved closer to enforceable rights. Free and compulsory education for children aged six to fourteen, once a directive, was made a fundamental right by an amendment in 2002. A directive, then, is less a promise broken than a promise deferred.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
भारत के संविधान का भाग IV राज्य के नीति निदेशक तत्त्व बताता है: कि राज्य सबके लिए आजीविका के पर्याप्त साधनों, समान कार्य के लिए समान वेतन, बच्चों के लिए निःशुल्क और अनिवार्य शिक्षा, और बहुत कुछ की दिशा में काम करे। अनुच्छेद 37 कहता है कि ये तत्त्व किसी न्यायालय द्वारा लागू नहीं कराए जा सकते, फिर भी वे देश के शासन में मूलभूत हैं और क़ानून बनाते समय उन्हें लागू करना राज्य का कर्तव्य है। संविधान निर्माताओं ने उन्हें इसलिए अप्रवर्तनीय नहीं बनाया कि वे उन्हें महत्त्वहीन मानते थे, बल्कि इसलिए कि एक निर्धन नया देश उन सबको एक साथ पूरा करने का वचन नहीं दे सकता था; वे लक्ष्य थे जिन तक राज्य के साधन बढ़ने के साथ पहुँचना था। समय के साथ कुछ प्रवर्तनीय अधिकारों के निकट आए हैं। छह से चौदह वर्ष के बच्चों के लिए निःशुल्क और अनिवार्य शिक्षा, जो कभी एक निदेशक तत्त्व थी, 2002 के एक संशोधन द्वारा मौलिक अधिकार बना दी गई। अतः निदेशक तत्त्व टूटा हुआ वचन कम और स्थगित वचन अधिक है।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["What begins as a Directive Principle can later be turned into a right that courts enforce.", "The framers expected the State''s ability to meet the Directives to grow over time."], "statements_hi": ["जो नीति निदेशक तत्त्व के रूप में शुरू होता है, उसे बाद में न्यायालयों द्वारा लागू कराए जाने वाले अधिकार में बदला जा सकता है।", "संविधान निर्माताओं को आशा थी कि निदेशक तत्त्वों को पूरा करने की राज्य की क्षमता समय के साथ बढ़ेगी।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p04", "csat_order": 28}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are valid. The 2002 amendment that made children''s education a fundamental right shows that a directive can later become an enforceable right (1). And the passage says the directives were goals ''to be reached as the State''s means grew'', so the framers expected the State''s capacity to meet them to increase over time (2).','दोनों वैध हैं। 2002 का संशोधन, जिसने बच्चों की शिक्षा को मौलिक अधिकार बनाया, दिखाता है कि कोई निदेशक तत्त्व बाद में प्रवर्तनीय अधिकार बन सकता है (1)। और परिच्छेद कहता है कि निदेशक तत्त्व ऐसे लक्ष्य थे ''जिन तक राज्य के साधन बढ़ने के साथ पहुँचना था'', इसलिए निर्माताओं को आशा थी कि उन्हें पूरा करने की राज्य की क्षमता समय के साथ बढ़ेगी (2)।','csat-l4-s05-rc-p04-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Part IV of the Constitution of India sets out the Directive Principles of State Policy: that the State should work towards adequate means of livelihood for all, equal pay for equal work, free and compulsory education for children, and much else. Article 37 says that these principles cannot be enforced by any court, and yet that they are fundamental in the governance of the country and that the State has a duty to apply them in making laws. The framers made them unenforceable not because they thought them unimportant, but because a poor new country could not promise to meet them all at once; they were goals to be reached as the State''s means grew. Over time some have moved closer to enforceable rights. Free and compulsory education for children aged six to fourteen, once a directive, was made a fundamental right by an amendment in 2002. A directive, then, is less a promise broken than a promise deferred.

According to the passage, what does Article 37 say about the Directive Principles?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
भारत के संविधान का भाग IV राज्य के नीति निदेशक तत्त्व बताता है: कि राज्य सबके लिए आजीविका के पर्याप्त साधनों, समान कार्य के लिए समान वेतन, बच्चों के लिए निःशुल्क और अनिवार्य शिक्षा, और बहुत कुछ की दिशा में काम करे। अनुच्छेद 37 कहता है कि ये तत्त्व किसी न्यायालय द्वारा लागू नहीं कराए जा सकते, फिर भी वे देश के शासन में मूलभूत हैं और क़ानून बनाते समय उन्हें लागू करना राज्य का कर्तव्य है। संविधान निर्माताओं ने उन्हें इसलिए अप्रवर्तनीय नहीं बनाया कि वे उन्हें महत्त्वहीन मानते थे, बल्कि इसलिए कि एक निर्धन नया देश उन सबको एक साथ पूरा करने का वचन नहीं दे सकता था; वे लक्ष्य थे जिन तक राज्य के साधन बढ़ने के साथ पहुँचना था। समय के साथ कुछ प्रवर्तनीय अधिकारों के निकट आए हैं। छह से चौदह वर्ष के बच्चों के लिए निःशुल्क और अनिवार्य शिक्षा, जो कभी एक निदेशक तत्त्व थी, 2002 के एक संशोधन द्वारा मौलिक अधिकार बना दी गई। अतः निदेशक तत्त्व टूटा हुआ वचन कम और स्थगित वचन अधिक है।

परिच्छेद के अनुसार, अनुच्छेद 37 नीति निदेशक तत्त्वों के बारे में क्या कहता है?','{"craft": "precision", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p04", "csat_order": 29}'::jsonb,'[{"id": "a", "body": "Courts must enforce them whenever a citizen shows that the State has failed to apply one.", "body_hi": "जब भी कोई नागरिक दिखाए कि राज्य ने किसी को लागू नहीं किया, न्यायालयों को उन्हें लागू कराना होगा।", "isCorrect": false}, {"id": "b", "body": "The State may set them aside whenever applying them in a law would prove inconvenient.", "body_hi": "जब भी किसी क़ानून में उन्हें लागू करना असुविधाजनक हो, राज्य उन्हें किनारे कर सकता है।", "isCorrect": false}, {"id": "c", "body": "They bind only the governments of the States, and not the government of the Union.", "body_hi": "वे केवल राज्यों की सरकारों को बाँधते हैं, संघ की सरकार को नहीं।", "isCorrect": false}, {"id": "d", "body": "No court can enforce them, yet the State has a duty to apply them in making laws.", "body_hi": "न्यायालय उन्हें लागू नहीं करा सकते, पर क़ानून बनाने में उन्हें लागू करना राज्य का कर्तव्य है।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage says Article 37 makes the principles unenforceable in any court, yet fundamental in governance, with a duty on the State to apply them in making laws. It does not say they bind the courts, that they may be ignored when inconvenient, or that they apply only to the States and not to the Union.','परिच्छेद कहता है कि अनुच्छेद 37 तत्त्वों को किसी न्यायालय में अप्रवर्तनीय, फिर भी शासन में मूलभूत बनाता है, और क़ानून बनाते समय उन्हें लागू करने का कर्तव्य राज्य पर डालता है। वह यह नहीं कहता कि वे न्यायालयों को बाँधते हैं, कि असुविधा होने पर उन्हें अनदेखा किया जा सकता है, या कि वे केवल राज्यों पर लागू होते हैं, संघ पर नहीं।','csat-l4-s05-rc-p04-what-article-37-says','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','easy','A clerk who walks at 4 km/h takes 30 minutes to reach the office. How much time would the clerk save by cycling there at 12 km/h instead?','4 किमी/घंटा से चलने वाला एक लिपिक दफ़्तर पहुँचने में 30 मिनट लेता है। यदि वह इसके बजाय 12 किमी/घंटा से साइकिल चलाकर जाए, तो कितना समय बचाएगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 30}'::jsonb,'[{"id": "a", "body": "5 minutes", "body_hi": "5 मिनट", "isCorrect": false}, {"id": "b", "body": "10 minutes", "body_hi": "10 मिनट", "isCorrect": false}, {"id": "c", "body": "15 minutes", "body_hi": "15 मिनट", "isCorrect": false}, {"id": "d", "body": "20 minutes", "body_hi": "20 मिनट", "isCorrect": true}]'::jsonb,2.5,0.83,'Half an hour at 4 km/h is 2 km. At 12 km/h, 2 km takes 2 ÷ 12 of an hour, that is 10 minutes, so cycling saves 30 - 10 = 20 minutes. 10 minutes is the time taken by cycle, not the time saved; 5 and 15 minutes have no basis.','4 किमी/घंटा से आधा घंटा यानी 2 किमी। 12 किमी/घंटा से 2 किमी में घंटे का 2 ÷ 12 भाग, यानी 10 मिनट लगते हैं, इसलिए साइकिल से 30 - 10 = 20 मिनट बचते हैं। 10 मिनट साइकिल से लगने वाला समय है, बचा हुआ समय नहीं; 5 और 15 मिनट का कोई आधार नहीं।','csat-l4-s05-qa-sdt-cycling-instead-of-walking','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','hard','A census officer asks a woman the ages of her three children, in whole years. She says that the product of their ages is 36, and that the sum of their ages is the number on the house next door. The officer looks at that number and says that this is still not enough. She adds, ''My eldest child, who is older than the other two, is learning the flute.'' What are the children''s ages?','एक जनगणना अधिकारी एक महिला से उसके तीन बच्चों की आयु, पूरे वर्षों में, पूछता है। वह बताती है कि उनकी आयु का गुणनफल 36 है, और उनकी आयु का योग पड़ोस के घर का नंबर है। अधिकारी वह नंबर देखकर कहता है कि यह अब भी पर्याप्त नहीं है। वह जोड़ती है, ''मेरा सबसे बड़ा बच्चा, जो बाक़ी दोनों से बड़ा है, बाँसुरी सीख रहा है।'' बच्चों की आयु क्या है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 31}'::jsonb,'[{"id": "a", "body": "1, 6 and 6", "body_hi": "1, 6 और 6", "isCorrect": false}, {"id": "b", "body": "3, 3 and 4", "body_hi": "3, 3 और 4", "isCorrect": false}, {"id": "c", "body": "1, 4 and 9", "body_hi": "1, 4 और 9", "isCorrect": false}, {"id": "d", "body": "2, 2 and 9", "body_hi": "2, 2 और 9", "isCorrect": true}]'::jsonb,2.5,0.83,'The sets of three ages with product 36 have the sums 38 (1, 1, 36), 21 (1, 2, 18), 16 (1, 3, 12), 14 (1, 4, 9), 13 (1, 6, 6 and 2, 2, 9), 11 (2, 3, 6) and 10 (3, 3, 4). The officer knows the sum and still cannot tell, so the sum must be 13, the only one shared by two sets. Of 1, 6, 6 and 2, 2, 9, only the second has a single eldest child older than the other two. So the ages are 2, 2 and 9. 1, 6 and 6 has two eldest of the same age; 3, 3 and 4 and 1, 4 and 9 have sums the officer could have settled at once.','36 गुणनफल वाले तीन आयुओं के समूहों के योग हैं 38 (1, 1, 36), 21 (1, 2, 18), 16 (1, 3, 12), 14 (1, 4, 9), 13 (1, 6, 6 और 2, 2, 9), 11 (2, 3, 6) और 10 (3, 3, 4)। अधिकारी योग जानता है और फिर भी तय नहीं कर पाता, इसलिए योग 13 होना चाहिए, जो अकेला दो समूहों में साझा है। 1, 6, 6 और 2, 2, 9 में से केवल दूसरे में एक ऐसा सबसे बड़ा बच्चा है जो बाक़ी दोनों से बड़ा हो। अतः आयु 2, 2 और 9 है। 1, 6 और 6 में एक ही आयु के दो सबसे बड़े हैं; 3, 3 और 4 तथा 1, 4 और 9 के योगों से अधिकारी तुरंत तय कर लेता।','csat-l4-s05-qa-ph-three-children-s-ages-from-their-product','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Direction & Distance','mcq','medium','P''s house is 2 km due west of Q''s house. R''s house is 2 km due north of Q''s house, and S''s house is 2 km due east of R''s house. Which two of the four houses are farthest apart?','P का घर, Q के घर से 2 किमी ठीक पश्चिम में है। R का घर, Q के घर से 2 किमी ठीक उत्तर में है, और S का घर, R के घर से 2 किमी ठीक पूर्व में है। चारों में से कौन-से दो घर एक-दूसरे से सबसे दूर हैं?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 32}'::jsonb,'[{"id": "a", "body": "P and R", "body_hi": "P और R", "isCorrect": false}, {"id": "b", "body": "P and S", "body_hi": "P और S", "isCorrect": true}, {"id": "c", "body": "Q and S", "body_hi": "Q और S", "isCorrect": false}, {"id": "d", "body": "Q and R", "body_hi": "Q और R", "isCorrect": false}]'::jsonb,2.5,0.83,'Put Q at the centre. P is 2 km west, R is 2 km north and S is 2 km north and 2 km east of Q. P and S are then 4 km apart east to west and 2 km north to south: √(4² + 2²) = √20, about 4.5 km. P and R and Q and S are each √(2² + 2²) = √8, about 2.8 km apart; Q and R are just 2 km apart.','Q को केंद्र में रखिए। P, 2 किमी पश्चिम में है, R, 2 किमी उत्तर में और S, Q से 2 किमी उत्तर और 2 किमी पूर्व में। तब P और S पूर्व-पश्चिम में 4 किमी और उत्तर-दक्षिण में 2 किमी दूर हैं: √(4² + 2²) = √20, लगभग 4.5 किमी। P और R तथा Q और S, हर जोड़ा √(2² + 2²) = √8, लगभग 2.8 किमी दूर है; Q और R केवल 2 किमी दूर हैं।','csat-l4-s05-lr-dd-the-two-houses-farthest-apart','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','medium','A room is 5 m long, 4 m wide and 3 m high. Its four walls are to be painted, but not the ceiling or the floor, leaving out one door of 2 m × 1 m and one window of 1.5 m × 1 m. What area is to be painted?','एक कमरा 5 मीटर लंबा, 4 मीटर चौड़ा और 3 मीटर ऊँचा है। उसकी चारों दीवारें रँगी जानी हैं, पर छत या फ़र्श नहीं, और 2 मीटर × 1 मीटर का एक दरवाज़ा तथा 1.5 मीटर × 1 मीटर की एक खिड़की छोड़नी है। कितना क्षेत्रफल रँगा जाना है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 33}'::jsonb,'[{"id": "a", "body": "50.5 m²", "body_hi": "50.5 वर्ग मीटर", "isCorrect": true}, {"id": "b", "body": "54 m²", "body_hi": "54 वर्ग मीटर", "isCorrect": false}, {"id": "c", "body": "57.5 m²", "body_hi": "57.5 वर्ग मीटर", "isCorrect": false}, {"id": "d", "body": "70.5 m²", "body_hi": "70.5 वर्ग मीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'The four walls together are the room''s height times its perimeter: 3 × 2 × (5 + 4) = 54 m². Taking off the door (2 m²) and the window (1.5 m²) leaves 50.5 m². 54 m² forgets the door and window; 57.5 m² adds them instead of taking them off; 70.5 m² paints the ceiling (20 m²) too.','चारों दीवारें मिलकर कमरे की ऊँचाई गुणा उसका परिमाप हैं: 3 × 2 × (5 + 4) = 54 वर्ग मीटर। दरवाज़ा (2 वर्ग मीटर) और खिड़की (1.5 वर्ग मीटर) घटाने पर 50.5 वर्ग मीटर बचता है। 54 वर्ग मीटर दरवाज़े और खिड़की को भूल जाता है; 57.5 वर्ग मीटर उन्हें घटाने के बजाय जोड़ता है; 70.5 वर्ग मीटर छत (20 वर्ग मीटर) को भी रँगता है।','csat-l4-s05-qa-gm-the-walls-of-a-room-to-be-painted','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1965 the engineer Gordon Moore, who later co-founded the chipmaker Intel, observed that the number of components that could be put on a single chip had been doubling every year, and predicted that it would go on doing so; in 1975 he revised the pace to a doubling every two years. For decades the industry kept close to his forecast. Part of the reason is that it stopped being only a forecast. Chipmakers and their suppliers planned research, factories and products around it, each expecting the others to keep pace, so the prediction helped to bring about what it predicted. Some forecasts describe the world; others, once believed, become plans that shape it.

Which one of the following statements best reflects the most logical and rational message conveyed by the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1965 में इंजीनियर गॉर्डन मूर ने, जिन्होंने बाद में चिप निर्माता इंटेल की सह-स्थापना की, देखा कि एक चिप पर रखे जा सकने वाले घटकों की संख्या हर वर्ष दोगुनी होती आई थी, और भविष्यवाणी की कि ऐसा होता रहेगा; 1975 में उन्होंने गति को हर दो वर्ष में दोगुना कर दिया। दशकों तक उद्योग उनके पूर्वानुमान के क़रीब बना रहा। इसका एक कारण यह है कि वह केवल पूर्वानुमान नहीं रहा। चिप निर्माताओं और उनके आपूर्तिकर्ताओं ने अनुसंधान, कारख़ानों और उत्पादों की योजना उसके इर्द-गिर्द बनाई, हर एक यह आशा करते हुए कि बाक़ी साथ चलेंगे, इसलिए भविष्यवाणी ने वही लाने में सहायता की जिसकी उसने भविष्यवाणी की थी। कुछ पूर्वानुमान दुनिया का वर्णन करते हैं; दूसरे, एक बार विश्वास कर लिए जाने पर, ऐसी योजनाएँ बन जाते हैं जो उसे आकार देती हैं।

निम्नलिखित में से कौन-सा कथन परिच्छेद द्वारा दिए गए सबसे तार्किक और विवेकपूर्ण संदेश को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p05", "csat_order": 34}'::jsonb,'[{"id": "a", "body": "Every forecast about technology comes true once enough people have heard of it.", "body_hi": "तकनीक के बारे में हर पूर्वानुमान पर्याप्त लोगों के सुन लेने के बाद सच हो जाता है।", "isCorrect": false}, {"id": "b", "body": "Moore''s forecast held because it was a law of physics that no one could break.", "body_hi": "मूर का पूर्वानुमान इसलिए सही रहा कि वह भौतिकी का ऐसा नियम था जिसे कोई नहीं तोड़ सकता था।", "isCorrect": false}, {"id": "c", "body": "A forecast that people believe and plan around can help to bring itself about.", "body_hi": "जिस पूर्वानुमान पर लोग विश्वास कर योजना बनाएँ, वह स्वयं को सच करने में सहायक हो सकता है।", "isCorrect": true}, {"id": "d", "body": "The chip industry fell far behind Moore''s forecast within a few years of 1975.", "body_hi": "1975 के कुछ ही वर्षों में चिप उद्योग मूर के पूर्वानुमान से बहुत पीछे रह गया।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage''s point is that Moore''s forecast held partly because the industry planned around it: a forecast that is believed can become a plan that helps to make itself come true. It does not say that every forecast fulfils itself, that Moore''s forecast was a law of physics, or that the industry fell behind it.','परिच्छेद की बात यह है कि मूर का पूर्वानुमान आंशिक रूप से इसलिए सही रहा कि उद्योग ने उसके इर्द-गिर्द योजना बनाई: जिस पूर्वानुमान पर विश्वास किया जाए वह ऐसी योजना बन सकता है जो उसे सच करने में सहायता करे। वह यह नहीं कहता कि हर पूर्वानुमान स्वयं को पूरा करता है, कि मूर का पूर्वानुमान भौतिकी का नियम था, या कि उद्योग उससे पीछे रह गया।','csat-l4-s05-rc-p05-message','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1965 the engineer Gordon Moore, who later co-founded the chipmaker Intel, observed that the number of components that could be put on a single chip had been doubling every year, and predicted that it would go on doing so; in 1975 he revised the pace to a doubling every two years. For decades the industry kept close to his forecast. Part of the reason is that it stopped being only a forecast. Chipmakers and their suppliers planned research, factories and products around it, each expecting the others to keep pace, so the prediction helped to bring about what it predicted. Some forecasts describe the world; others, once believed, become plans that shape it.

Which one of the following is most like the way, according to the passage, Moore''s forecast came true?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1965 में इंजीनियर गॉर्डन मूर ने, जिन्होंने बाद में चिप निर्माता इंटेल की सह-स्थापना की, देखा कि एक चिप पर रखे जा सकने वाले घटकों की संख्या हर वर्ष दोगुनी होती आई थी, और भविष्यवाणी की कि ऐसा होता रहेगा; 1975 में उन्होंने गति को हर दो वर्ष में दोगुना कर दिया। दशकों तक उद्योग उनके पूर्वानुमान के क़रीब बना रहा। इसका एक कारण यह है कि वह केवल पूर्वानुमान नहीं रहा। चिप निर्माताओं और उनके आपूर्तिकर्ताओं ने अनुसंधान, कारख़ानों और उत्पादों की योजना उसके इर्द-गिर्द बनाई, हर एक यह आशा करते हुए कि बाक़ी साथ चलेंगे, इसलिए भविष्यवाणी ने वही लाने में सहायता की जिसकी उसने भविष्यवाणी की थी। कुछ पूर्वानुमान दुनिया का वर्णन करते हैं; दूसरे, एक बार विश्वास कर लिए जाने पर, ऐसी योजनाएँ बन जाते हैं जो उसे आकार देती हैं।

परिच्छेद के अनुसार मूर का पूर्वानुमान जिस तरह सच हुआ, निम्नलिखित में से कौन-सा उससे सबसे अधिक मिलता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p05", "csat_order": 35}'::jsonb,'[{"id": "a", "body": "Rumours that a sound bank will fail make so many withdraw their money that it does fail.", "body_hi": "ठीक बैंक के डूबने की अफ़वाहें इतने लोगों से पैसा निकलवाती हैं कि वह सचमुच डूब जाता है।", "isCorrect": true}, {"id": "b", "body": "A tide table printed a year in advance correctly gives the times of high water at a port.", "body_hi": "एक वर्ष पहले छपी ज्वार-तालिका किसी बंदरगाह पर ऊँचे ज्वार के समय सही बताती है।", "isCorrect": false}, {"id": "c", "body": "A weather office''s forecast of heavy rain for the next day turns out to be correct.", "body_hi": "मौसम कार्यालय का अगले दिन भारी वर्षा का पूर्वानुमान सही निकलता है।", "isCorrect": false}, {"id": "d", "body": "A doctor who has seen an X-ray predicts that a broken bone will take six weeks to heal.", "body_hi": "एक्स-रे देख चुका डॉक्टर भविष्यवाणी करता है कि टूटी हुई हड्डी को जुड़ने में छह सप्ताह लगेंगे।", "isCorrect": false}]'::jsonb,2.5,0.83,'Moore''s forecast came true partly because everyone involved planned on it and expected the others to keep pace. Rumours of a bank''s failure that make depositors withdraw their money until the bank does fail work the same way: belief in the forecast brings it about. A tide table describes the moon''s pull, which no one''s belief affects; a weather forecast does not change the weather; and a doctor''s prediction based on an X-ray describes a condition already present.','मूर का पूर्वानुमान आंशिक रूप से इसलिए सच हुआ कि सभी संबंधित पक्षों ने उस पर योजना बनाई और बाक़ी से साथ चलने की आशा की। किसी बैंक के डूबने की अफ़वाहें, जो जमाकर्ताओं से पैसा तब तक निकलवाती हैं जब तक बैंक सचमुच डूब न जाए, इसी तरह काम करती हैं: पूर्वानुमान पर विश्वास उसे घटित कर देता है। ज्वार-तालिका चंद्रमा के खिंचाव का वर्णन करती है, जिस पर किसी के विश्वास का प्रभाव नहीं; मौसम का पूर्वानुमान मौसम नहीं बदलता; और एक्स-रे पर आधारित डॉक्टर की भविष्यवाणी पहले से मौजूद स्थिति का वर्णन करती है।','csat-l4-s05-rc-p05-a-forecast-that-comes-true-the-same-way','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','What is the fraction 1001/1547 in its lowest terms?','भिन्न 1001/1547 अपने न्यूनतम रूप में क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 36}'::jsonb,'[{"id": "a", "body": "7/13", "body_hi": "7/13", "isCorrect": false}, {"id": "b", "body": "7/11", "body_hi": "7/11", "isCorrect": false}, {"id": "c", "body": "11/17", "body_hi": "11/17", "isCorrect": true}, {"id": "d", "body": "13/17", "body_hi": "13/17", "isCorrect": false}]'::jsonb,2.5,0.83,'1001 = 7 × 11 × 13 and 1547 = 7 × 13 × 17. Cancelling the common 7 and 13 leaves 11/17. 7/13 and 13/17 cancel the wrong factors; 7/11 keeps a 7 that both numbers share and should have been cancelled. (The options are arranged in order of size.)','1001 = 7 × 11 × 13 और 1547 = 7 × 13 × 17। साझा 7 और 13 को काटने पर 11/17 बचता है। 7/13 और 13/17 ग़लत गुणनखंड काटते हैं; 7/11 उस 7 को बनाए रखता है जो दोनों संख्याओं में साझा है और कटना चाहिए था। (विकल्प आकार के क्रम में रखे गए हैं।)','csat-l4-s05-qa-nt-1001-over-1547-in-lowest-terms','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','hard','Six friends -- Arun, Bina, Chand, Dev, Esha and Farah -- travel in a train, one in each of six coaches numbered 1 to 6 from the engine. Chand is in coach 4, and Farah is in the coach just in front of Chand''s, nearer the engine. Exactly two coaches lie between Arun''s and Esha''s, and Esha is nearer the engine than Arun. Bina is farther from the engine than Dev. Which one of the following is correct?','छह मित्र -- अरुण, बीना, चाँद, देव, ईशा और फ़राह -- एक रेलगाड़ी में यात्रा करते हैं, इंजन से 1 से 6 तक क्रमांकित छह डिब्बों में से हर एक में एक। चाँद डिब्बा 4 में है, और फ़राह, चाँद के डिब्बे के ठीक आगे वाले डिब्बे में है, इंजन के निकट। अरुण और ईशा के डिब्बों के बीच ठीक दो डिब्बे हैं, और ईशा, अरुण से इंजन के अधिक निकट है। बीना, देव से इंजन से अधिक दूर है। निम्नलिखित में से कौन-सा सही है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 37}'::jsonb,'[{"id": "a", "body": "Bina is in coach 2.", "body_hi": "बीना डिब्बा 2 में है।", "isCorrect": false}, {"id": "b", "body": "Dev is in coach 6.", "body_hi": "देव डिब्बा 6 में है।", "isCorrect": false}, {"id": "c", "body": "Esha is in coach 3.", "body_hi": "ईशा डिब्बा 3 में है।", "isCorrect": false}, {"id": "d", "body": "Arun is in coach 5.", "body_hi": "अरुण डिब्बा 5 में है।", "isCorrect": true}]'::jsonb,2.5,0.83,'Chand is in 4 and Farah in 3. Esha and Arun are three coaches apart with Esha nearer the engine: 1 and 4, 2 and 5, or 3 and 6. Coaches 4 and 3 are taken, which rules out the first and third pairs, so Esha is in 2 and Arun in 5. That leaves coaches 1 and 6 for Bina and Dev, and Bina is the farther from the engine: Dev in 1, Bina in 6. So Arun is in coach 5. Bina is in 6, not 2; Dev is in 1, not 6; and Esha is in 2, not 3 -- the other three options describe a seating that Farah''s place rules out.','चाँद 4 में है और फ़राह 3 में। ईशा और अरुण तीन डिब्बे दूर हैं और ईशा इंजन के निकट है: 1 और 4, 2 और 5, या 3 और 6। डिब्बे 4 और 3 भरे हैं, जिससे पहली और तीसरी जोड़ी ख़ारिज होती हैं, इसलिए ईशा 2 में है और अरुण 5 में। बीना और देव के लिए डिब्बे 1 और 6 बचते हैं, और बीना इंजन से अधिक दूर है: देव 1 में, बीना 6 में। अतः अरुण डिब्बा 5 में है। बीना 6 में है, 2 में नहीं; देव 1 में है, 6 में नहीं; और ईशा 2 में है, 3 में नहीं -- बाक़ी तीन विकल्प ऐसी व्यवस्था बताते हैं जिसे फ़राह का स्थान ख़ारिज कर देता है।','csat-l4-s05-lr-sa-six-friends-in-six-coaches','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','medium','40 litres of a solution are 10 per cent salt. How much water must be boiled off for the solution to become 16 per cent salt?','40 लीटर के एक घोल में 10 प्रतिशत नमक है। घोल में 16 प्रतिशत नमक होने के लिए कितना पानी उबालकर उड़ाना होगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 38}'::jsonb,'[{"id": "a", "body": "6 litres", "body_hi": "6 लीटर", "isCorrect": false}, {"id": "b", "body": "10 litres", "body_hi": "10 लीटर", "isCorrect": false}, {"id": "c", "body": "15 litres", "body_hi": "15 लीटर", "isCorrect": true}, {"id": "d", "body": "24 litres", "body_hi": "24 लीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'The salt stays at 10 per cent of 40 = 4 litres. For 4 litres to be 16 per cent of the solution, the solution must be 4 ÷ 0.16 = 25 litres, so 40 - 25 = 15 litres of water must go. 6 litres takes the 6 percentage points as litres; 24 litres scales 40 up in the ratio 16 : 10 and subtracts, as if water were being added; 10 litres has no basis.','नमक 40 का 10 प्रतिशत = 4 लीटर ही रहता है। 4 लीटर घोल का 16 प्रतिशत हो, इसके लिए घोल 4 ÷ 0.16 = 25 लीटर होना चाहिए, इसलिए 40 - 25 = 15 लीटर पानी जाना चाहिए। 6 लीटर 6 प्रतिशत बिंदुओं को लीटर मान लेता है; 24 लीटर 40 को 16 : 10 के अनुपात में बढ़ाकर घटाता है, मानो पानी मिलाया जा रहा हो; 10 लीटर का कोई आधार नहीं।','csat-l4-s05-qa-pp-water-boiled-off-a-salt-solution','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','easy','Two circles have the same centre and radii of 7 cm and 14 cm. What is the area of the ring between them? (Take π = 22/7.)','दो वृत्तों का केंद्र एक ही है और उनकी त्रिज्याएँ 7 सेमी और 14 सेमी हैं। उनके बीच के वलय का क्षेत्रफल क्या है? (π = 22/7 लीजिए।)','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 39}'::jsonb,'[{"id": "a", "body": "154 cm²", "body_hi": "154 वर्ग सेमी", "isCorrect": false}, {"id": "b", "body": "308 cm²", "body_hi": "308 वर्ग सेमी", "isCorrect": false}, {"id": "c", "body": "462 cm²", "body_hi": "462 वर्ग सेमी", "isCorrect": true}, {"id": "d", "body": "616 cm²", "body_hi": "616 वर्ग सेमी", "isCorrect": false}]'::jsonb,2.5,0.83,'The ring is the larger circle minus the smaller: 22/7 × (14² - 7²) = 22/7 × 147 = 462 cm². 616 cm² is the larger circle and 154 cm² the smaller; 308 cm² multiplies π by the two radii (22/7 × 7 × 14).','वलय बड़े वृत्त में से छोटे वृत्त को घटाकर बनता है: 22/7 × (14² - 7²) = 22/7 × 147 = 462 वर्ग सेमी। 616 वर्ग सेमी बड़ा वृत्त है और 154 वर्ग सेमी छोटा; 308 वर्ग सेमी, π को दोनों त्रिज्याओं से गुणा करता है (22/7 × 7 × 14)।','csat-l4-s05-qa-gm-the-area-of-a-ring','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Adam Smith noticed a puzzle in 1776. Nothing is more useful than water, yet it will buy scarcely anything; a diamond has hardly any use, yet a great quantity of other goods can be had in exchange for it. Economists of the following century found the answer in the difference between the value of a whole supply and the value of one more unit of it. Price is set at the margin -- by how much people care about the next litre or the next stone. Water is usually so plentiful that one more litre matters little, though the whole supply is beyond price; diamonds are so scarce that one more is greatly prized. The answer also explains why the puzzle can vanish: to a traveller lost in a desert, the next litre of water is worth more than any diamond. Price, then, measures what a thing is worth at the margin, not how much it matters overall.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
एडम स्मिथ ने 1776 में एक पहेली देखी। पानी से अधिक उपयोगी कुछ नहीं, फिर भी उससे शायद ही कुछ ख़रीदा जा सकता है; हीरे का लगभग कोई उपयोग नहीं, फिर भी उसके बदले बहुत-सी अन्य वस्तुएँ मिल सकती हैं। अगली शताब्दी के अर्थशास्त्रियों ने इसका उत्तर पूरी आपूर्ति के मूल्य और उसकी एक और इकाई के मूल्य के अंतर में पाया। मूल्य सीमांत पर तय होता है -- इससे कि लोग अगले लीटर या अगले पत्थर की कितनी परवाह करते हैं। पानी प्रायः इतना प्रचुर होता है कि एक और लीटर का कम महत्त्व है, यद्यपि पूरी आपूर्ति अमूल्य है; हीरे इतने दुर्लभ हैं कि एक और का बहुत मूल्य है। यह उत्तर यह भी समझाता है कि पहेली ग़ायब क्यों हो सकती है: रेगिस्तान में भटके यात्री के लिए पानी का अगला लीटर किसी भी हीरे से अधिक मूल्यवान है। अतः मूल्य यह मापता है कि कोई वस्तु सीमांत पर कितनी मूल्यवान है, यह नहीं कि वह कुल मिलाकर कितनी मायने रखती है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p06", "csat_order": 40}'::jsonb,'[{"id": "a", "body": "Water is in truth less useful than diamonds, which is why the market prices it so much lower.", "body_hi": "पानी वास्तव में हीरों से कम उपयोगी है, इसीलिए बाज़ार उसका मूल्य इतना कम आँकता है।", "isCorrect": false}, {"id": "b", "body": "Prices have nothing to do with how useful things are, and are set by fashion and custom alone.", "body_hi": "मूल्यों का वस्तुओं की उपयोगिता से कोई संबंध नहीं, और वे केवल फ़ैशन और रिवाज से तय होते हैं।", "isCorrect": false}, {"id": "c", "body": "Diamonds will always be worth more than water, wherever and whenever they are exchanged.", "body_hi": "हीरे हमेशा पानी से अधिक मूल्यवान रहेंगे, चाहे जहाँ और जब भी उनका विनिमय हो।", "isCorrect": false}, {"id": "d", "body": "A thing''s price reflects the value of one more unit of it, which depends on how scarce it is.", "body_hi": "किसी वस्तु का मूल्य उसकी एक और इकाई का मूल्य दर्शाता है, जो उसकी दुर्लभता पर निर्भर है।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage resolves Smith''s puzzle: price reflects the value of one more unit, which depends on scarcity, not the value of the whole supply. It says water matters more overall, so it does not call water less useful; it does not say prices are unrelated to use, only that they track use at the margin; and it shows the gap reversing in a desert, so diamonds are not always dearer.','परिच्छेद स्मिथ की पहेली सुलझाता है: मूल्य एक और इकाई का मूल्य दर्शाता है, जो दुर्लभता पर निर्भर है, पूरी आपूर्ति का मूल्य नहीं। वह कहता है कि पानी कुल मिलाकर अधिक मायने रखता है, इसलिए वह पानी को कम उपयोगी नहीं कहता; वह यह नहीं कहता कि मूल्यों का उपयोग से कोई संबंध नहीं, केवल यह कि वे सीमांत पर उपयोग का अनुसरण करते हैं; और वह रेगिस्तान में अंतर को उलटता दिखाता है, इसलिए हीरे हमेशा महँगे नहीं।','csat-l4-s05-rc-p06-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Adam Smith noticed a puzzle in 1776. Nothing is more useful than water, yet it will buy scarcely anything; a diamond has hardly any use, yet a great quantity of other goods can be had in exchange for it. Economists of the following century found the answer in the difference between the value of a whole supply and the value of one more unit of it. Price is set at the margin -- by how much people care about the next litre or the next stone. Water is usually so plentiful that one more litre matters little, though the whole supply is beyond price; diamonds are so scarce that one more is greatly prized. The answer also explains why the puzzle can vanish: to a traveller lost in a desert, the next litre of water is worth more than any diamond. Price, then, measures what a thing is worth at the margin, not how much it matters overall.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
एडम स्मिथ ने 1776 में एक पहेली देखी। पानी से अधिक उपयोगी कुछ नहीं, फिर भी उससे शायद ही कुछ ख़रीदा जा सकता है; हीरे का लगभग कोई उपयोग नहीं, फिर भी उसके बदले बहुत-सी अन्य वस्तुएँ मिल सकती हैं। अगली शताब्दी के अर्थशास्त्रियों ने इसका उत्तर पूरी आपूर्ति के मूल्य और उसकी एक और इकाई के मूल्य के अंतर में पाया। मूल्य सीमांत पर तय होता है -- इससे कि लोग अगले लीटर या अगले पत्थर की कितनी परवाह करते हैं। पानी प्रायः इतना प्रचुर होता है कि एक और लीटर का कम महत्त्व है, यद्यपि पूरी आपूर्ति अमूल्य है; हीरे इतने दुर्लभ हैं कि एक और का बहुत मूल्य है। यह उत्तर यह भी समझाता है कि पहेली ग़ायब क्यों हो सकती है: रेगिस्तान में भटके यात्री के लिए पानी का अगला लीटर किसी भी हीरे से अधिक मूल्यवान है। अतः मूल्य यह मापता है कि कोई वस्तु सीमांत पर कितनी मूल्यवान है, यह नहीं कि वह कुल मिलाकर कितनी मायने रखती है।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["The low price of water shows that, taken as a whole, water matters little to people.", "A drought that made water scarce could raise its price without making water any more useful in total."], "statements_hi": ["पानी का कम मूल्य दिखाता है कि कुल मिलाकर पानी लोगों के लिए कम मायने रखता है।", "पानी को दुर्लभ करने वाला सूखा पानी को कुल मिलाकर अधिक उपयोगी बनाए बिना उसका मूल्य बढ़ा सकता है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p06", "csat_order": 41}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is valid. The passage says that what sets a price is how much people care about the next unit; if a drought made water scarce, the next litre would matter much more and its price would rise, even though water had become no more useful in total. 1 misreads the passage: it says the whole supply of water is ''beyond price'', so a low price does not show that water matters little to people overall.','केवल 2 वैध है। परिच्छेद कहता है कि मूल्य इससे तय होता है कि लोग अगली इकाई की कितनी परवाह करते हैं; यदि सूखा पानी को दुर्लभ कर दे, तो अगला लीटर कहीं अधिक मायने रखेगा और उसका मूल्य बढ़ेगा, यद्यपि कुल मिलाकर पानी अधिक उपयोगी नहीं हुआ। 1 परिच्छेद को ग़लत पढ़ता है: वह कहता है कि पानी की पूरी आपूर्ति ''अमूल्य'' है, इसलिए कम मूल्य यह नहीं दिखाता कि पानी लोगों के लिए कुल मिलाकर कम मायने रखता है।','csat-l4-s05-rc-p06-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Adam Smith noticed a puzzle in 1776. Nothing is more useful than water, yet it will buy scarcely anything; a diamond has hardly any use, yet a great quantity of other goods can be had in exchange for it. Economists of the following century found the answer in the difference between the value of a whole supply and the value of one more unit of it. Price is set at the margin -- by how much people care about the next litre or the next stone. Water is usually so plentiful that one more litre matters little, though the whole supply is beyond price; diamonds are so scarce that one more is greatly prized. The answer also explains why the puzzle can vanish: to a traveller lost in a desert, the next litre of water is worth more than any diamond. Price, then, measures what a thing is worth at the margin, not how much it matters overall.

Which one of the following best fits the passage''s explanation of prices?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
एडम स्मिथ ने 1776 में एक पहेली देखी। पानी से अधिक उपयोगी कुछ नहीं, फिर भी उससे शायद ही कुछ ख़रीदा जा सकता है; हीरे का लगभग कोई उपयोग नहीं, फिर भी उसके बदले बहुत-सी अन्य वस्तुएँ मिल सकती हैं। अगली शताब्दी के अर्थशास्त्रियों ने इसका उत्तर पूरी आपूर्ति के मूल्य और उसकी एक और इकाई के मूल्य के अंतर में पाया। मूल्य सीमांत पर तय होता है -- इससे कि लोग अगले लीटर या अगले पत्थर की कितनी परवाह करते हैं। पानी प्रायः इतना प्रचुर होता है कि एक और लीटर का कम महत्त्व है, यद्यपि पूरी आपूर्ति अमूल्य है; हीरे इतने दुर्लभ हैं कि एक और का बहुत मूल्य है। यह उत्तर यह भी समझाता है कि पहेली ग़ायब क्यों हो सकती है: रेगिस्तान में भटके यात्री के लिए पानी का अगला लीटर किसी भी हीरे से अधिक मूल्यवान है। अतः मूल्य यह मापता है कि कोई वस्तु सीमांत पर कितनी मूल्यवान है, यह नहीं कि वह कुल मिलाकर कितनी मायने रखती है।

निम्नलिखित में से कौन-सा मूल्यों की परिच्छेद की व्याख्या पर सबसे अच्छा बैठता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p06", "csat_order": 42}'::jsonb,'[{"id": "a", "body": "A government fixes the price of bread by law and keeps it the same for many years.", "body_hi": "सरकार क़ानून द्वारा रोटी का मूल्य तय करती है और उसे कई वर्षों तक एक-सा रखती है।", "isCorrect": false}, {"id": "b", "body": "Bottled water costs far more on a mountain top, where each bottle must be carried up.", "body_hi": "पानी की एक बोतल पहाड़ की चोटी पर कहीं महँगी है, जहाँ हर बोतल ऊपर ढोनी पड़ती है।", "isCorrect": true}, {"id": "c", "body": "A gem falls in price after it goes out of fashion among the people who buy jewellery.", "body_hi": "आभूषणों के ख़रीदारों में फ़ैशन से बाहर होने के बाद किसी रत्न का मूल्य गिर जाता है।", "isCorrect": false}, {"id": "d", "body": "A shop charges the same price for a large loaf and a small one, out of long custom.", "body_hi": "एक दुकान पुराने रिवाज से बड़ी और छोटी डबलरोटी का एक ही मूल्य लेती है।", "isCorrect": false}]'::jsonb,2.5,0.83,'On the passage''s account a price rises when the next unit becomes scarcer. A bottle of water that costs far more at the top of a mountain, where every bottle must be carried up, fits that exactly: the next bottle is scarce there. A price set by law, a fall in the price of a gem that has gone out of fashion and an equal price for unequal goods are explained by other things -- rules, taste and custom -- that the passage does not discuss.','परिच्छेद के अनुसार मूल्य तब बढ़ता है जब अगली इकाई अधिक दुर्लभ हो जाती है। पहाड़ की चोटी पर, जहाँ हर बोतल ऊपर ढोनी पड़ती है, कहीं महँगी बिकने वाली पानी की बोतल इस पर ठीक बैठती है: वहाँ अगली बोतल दुर्लभ है। क़ानून द्वारा तय मूल्य, फ़ैशन से बाहर हुए रत्न के मूल्य में गिरावट और असमान वस्तुओं का समान मूल्य अन्य बातों -- नियमों, रुचि और रिवाज -- से समझाए जाते हैं, जिनकी परिच्छेद चर्चा नहीं करता।','csat-l4-s05-rc-p06-what-fits-the-explanation-of-prices','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','Take a four-digit number whose digits are not all the same. Arrange its digits in descending order and in ascending order, and subtract the smaller of the two numbers from the larger. Repeat this with each result, keeping any zero as a digit (so that 378 is treated as 0378). Starting from 3524, after how many subtractions does the result first become 6174?','चार अंकों की ऐसी संख्या लीजिए जिसके सभी अंक एक जैसे न हों। उसके अंकों को घटते क्रम में और बढ़ते क्रम में रखिए, और दोनों संख्याओं में से छोटी को बड़ी में से घटाइए। हर परिणाम के साथ यही दोहराइए, किसी भी शून्य को अंक मानते हुए (ताकि 378 को 0378 माना जाए)। 3524 से शुरू करने पर कितने घटावों के बाद परिणाम पहली बार 6174 बनता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 43}'::jsonb,'[{"id": "a", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "b", "body": "2", "body_hi": "2", "isCorrect": false}, {"id": "c", "body": "3", "body_hi": "3", "isCorrect": true}, {"id": "d", "body": "4", "body_hi": "4", "isCorrect": false}]'::jsonb,2.5,0.83,'5432 - 2345 = 3087; then 8730 - 0378 = 8352; then 8532 - 2358 = 6174. So 6174 appears after 3 subtractions -- and stays, since 7641 - 1467 = 6174 again. This is Kaprekar''s routine, named after the Indian mathematician D. R. Kaprekar. 2 stops one step short, at 8352; 4 counts one step past 6174; 1 has no basis.','5432 - 2345 = 3087; फिर 8730 - 0378 = 8352; फिर 8532 - 2358 = 6174। अतः 6174, 3 घटावों के बाद आता है -- और बना रहता है, क्योंकि 7641 - 1467 = 6174 फिर से। यह काप्रेकर की प्रक्रिया है, जिसका नाम भारतीय गणितज्ञ द. रा. काप्रेकर के नाम पर है। 2 एक चरण पहले, 8352 पर, रुक जाता है; 4, 6174 के बाद एक चरण और गिनता है; 1 का कोई आधार नहीं।','csat-l4-s05-qa-nt-kaprekar-s-routine','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Coding-Decoding','mcq','medium','In a code, the letter in position n of the alphabet (A = 1, B = 2, ..., Z = 26) is replaced by the letter in position 2n, counting on from A again after Z -- so M (13) becomes Z (26), and N (14) becomes B (28 - 26 = 2). How is CAKE written in this code?','एक कूट में वर्णमाला के n-वें स्थान का अक्षर (A = 1, B = 2, ..., Z = 26) 2n-वें स्थान के अक्षर से बदला जाता है, Z के बाद फिर A से गिनते हुए -- इसलिए M (13), Z (26) बन जाता है, और N (14), B (28 - 26 = 2)। इस कूट में CAKE कैसे लिखा जाता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 44}'::jsonb,'[{"id": "a", "body": "FBVJ", "body_hi": "FBVJ", "isCorrect": true}, {"id": "b", "body": "DBLF", "body_hi": "DBLF", "isCorrect": false}, {"id": "c", "body": "FBUJ", "body_hi": "FBUJ", "isCorrect": false}, {"id": "d", "body": "ECMG", "body_hi": "ECMG", "isCorrect": false}]'::jsonb,2.5,0.83,'C is 3rd, so it becomes the 6th letter, F; A (1) becomes B (2); K (11) becomes V (22); and E (5) becomes J (10). CAKE is written FBVJ. DBLF moves each letter on by one place; ECMG moves each on by two; FBUJ slips on K, sending it to the 21st letter instead of the 22nd.','C तीसरा है, इसलिए वह छठा अक्षर F बनता है; A (1), B (2) बनता है; K (11), V (22) बनता है; और E (5), J (10) बनता है। CAKE, FBVJ लिखा जाता है। DBLF हर अक्षर को एक स्थान आगे ले जाता है; ECMG दो स्थान; FBUJ, K पर चूकता है, उसे 22वें के बजाय 21वें अक्षर पर भेजता है।','csat-l4-s05-lr-cd-a-code-that-sends-each-letter-to-twice-its-place','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','medium','In the series 3, 6, 12, 24, ..., in which each term is double the one before it, which term is 768?','श्रेणी 3, 6, 12, 24, ... में, जिसमें हर पद पिछले पद का दोगुना है, 768 कौन-सा पद है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 45}'::jsonb,'[{"id": "a", "body": "8th", "body_hi": "8वाँ", "isCorrect": false}, {"id": "b", "body": "9th", "body_hi": "9वाँ", "isCorrect": true}, {"id": "c", "body": "10th", "body_hi": "10वाँ", "isCorrect": false}, {"id": "d", "body": "256th", "body_hi": "256वाँ", "isCorrect": false}]'::jsonb,2.5,0.83,'The n-th term is 3 × 2ⁿ⁻¹. 768 = 3 × 256 = 3 × 2⁸, so n - 1 = 8 and n = 9: 768 is the 9th term. 8th takes the power of 2 for the place, forgetting that the first term is 3 × 2⁰; 256th takes the multiplier for the place; 10th has no basis.','n-वाँ पद 3 × 2ⁿ⁻¹ है। 768 = 3 × 256 = 3 × 2⁸, इसलिए n - 1 = 8 और n = 9: 768, 9वाँ पद है। 8वाँ, 2 की घात को स्थान मान लेता है, यह भूलकर कि पहला पद 3 × 2⁰ है; 256वाँ गुणक को स्थान मान लेता है; 10वें का कोई आधार नहीं।','csat-l4-s05-qa-ss-the-place-of-768-in-a-doubling-series','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: What is the median of a set of five numbers?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: पाँच संख्याओं के एक समूह की माध्यिका क्या है?','{"statements": ["The mean of the five numbers is 14.", "Three of the numbers are 8, 10 and 12, and the other two are both greater than 12."], "statements_hi": ["पाँचों संख्याओं का माध्य 14 है।", "तीन संख्याएँ 8, 10 और 12 हैं, और बाक़ी दोनों 12 से बड़ी हैं।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 46}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement II alone settles it: in order the numbers are 8, 10, 12 and then the two larger ones, so the middle number is 12, whatever the two larger ones are. Statement I alone does not: a mean of 14 allows many different sets with different middle numbers. So one statement alone is enough, but not the other.','कथन II अकेले इसे तय कर देता है: क्रम में संख्याएँ 8, 10, 12 और फिर दोनों बड़ी संख्याएँ हैं, इसलिए बीच की संख्या 12 है, बड़ी संख्याएँ चाहे जो हों। कथन I अकेले नहीं: 14 का माध्य अलग-अलग बीच की संख्या वाले कई समूहों की अनुमति देता है। अतः एक कथन अकेले पर्याप्त है, पर दूसरा नहीं।','csat-l4-s05-qa-ds-a-median-from-part-of-the-data','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Data Sufficiency','mcq','hard','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: Is triangle PQR right-angled?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: क्या त्रिभुज PQR समकोण त्रिभुज है?','{"statements": ["Its sides are 5 cm, 12 cm and 13 cm.", "Two of its sides are 5 cm and 12 cm, and its area is 30 cm²."], "statements_hi": ["उसकी भुजाएँ 5 सेमी, 12 सेमी और 13 सेमी हैं।", "उसकी दो भुजाएँ 5 सेमी और 12 सेमी हैं, और उसका क्षेत्रफल 30 वर्ग सेमी है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 47}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": true}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone: 5² + 12² = 25 + 144 = 169 = 13², so the triangle is right-angled. Statement II alone: the area is ½ × 5 × 12 × (the sine of the angle between those sides), and this reaches 30 only when that angle is 90° -- at any other angle the area is less. So it is right-angled again. Either statement alone answers the question.','कथन I अकेले: 5² + 12² = 25 + 144 = 169 = 13², इसलिए त्रिभुज समकोण है। कथन II अकेले: क्षेत्रफल ½ × 5 × 12 × (उन भुजाओं के बीच के कोण की ज्या) है, और यह 30 तभी होता है जब वह कोण 90° हो -- किसी और कोण पर क्षेत्रफल कम होता है। अतः फिर समकोण। कोई भी एक कथन अकेले प्रश्न का उत्तर देता है।','csat-l4-s05-qa-ds-a-right-angle-from-the-sides-or-the-area','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: Four runners, P, Q, R and S, ran a race in which there were no ties. Who finished second?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: चार धावकों, P, Q, R और S, ने एक दौड़ लगाई जिसमें कोई बराबरी नहीं हुई। दूसरे स्थान पर कौन रहा?','{"statements": ["P finished ahead of Q but behind R.", "S finished last."], "statements_hi": ["P, Q से आगे पर R से पीछे रहा।", "S अंतिम रहा।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 48}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone fixes R ahead of P ahead of Q, but S could come anywhere, so the runner in second place could be S, R or P. Statement II alone says nothing about the other three. Together the order is R, P, Q, S, and P finished second. Both statements are needed.','कथन I अकेले R को P से और P को Q से आगे रखता है, पर S कहीं भी आ सकता है, इसलिए दूसरे स्थान पर S, R या P हो सकता है। कथन II अकेले बाक़ी तीन के बारे में कुछ नहीं कहता। दोनों मिलकर क्रम R, P, Q, S है, और P दूसरे स्थान पर रहा। दोनों कथन आवश्यक हैं।','csat-l4-s05-lr-ds-the-runner-who-came-second','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','hard','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: Is the light in the hall on?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: क्या हॉल की बत्ती जल रही है?','{"statements": ["Whenever the fan in the hall is on, the light in the hall is on too.", "The fan in the hall is off."], "statements_hi": ["जब भी हॉल का पंखा चलता है, हॉल की बत्ती भी जलती है।", "हॉल का पंखा बंद है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 49}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": true}]'::jsonb,2.5,0.83,'Statement I says only what happens when the fan is on. Statement II says the fan is off, and then Statement I says nothing at all: the light may be on or off. Even together the statements do not answer the question. The trap is to read I as ''the light is on only when the fan is on'' and conclude that the light is off.','कथन I केवल यह बताता है कि पंखा चलने पर क्या होता है। कथन II कहता है कि पंखा बंद है, और तब कथन I कुछ भी नहीं कहता: बत्ती जल भी सकती है और बुझी भी हो सकती है। दोनों कथन साथ मिलकर भी प्रश्न का उत्तर नहीं देते। जाल यह है कि I को ''बत्ती केवल तभी जलती है जब पंखा चलता है'' पढ़कर निष्कर्ष निकाल लिया जाए कि बत्ती बुझी है।','csat-l4-s05-lr-ds-a-light-that-goes-on-with-the-fan','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','hard','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: The six faces of a cube are painted red, blue, green, yellow, white and black, one colour to each face. Which colour is on the face opposite the red face?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: एक घन के छह फलक लाल, नीले, हरे, पीले, सफ़ेद और काले रंग से रँगे हैं, हर फलक पर एक रंग। लाल फलक के सामने वाले फलक पर कौन-सा रंग है?','{"statements": ["The blue face shares an edge with the red, the green and the yellow faces.", "The white face is opposite the yellow face."], "statements_hi": ["नीला फलक लाल, हरे और पीले फलकों से एक-एक किनारा साझा करता है।", "सफ़ेद फलक पीले फलक के सामने है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 50}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone: blue is next to red, green and yellow, so the face opposite blue is white or black -- and red''s opposite is still open. Statement II alone pairs white with yellow and says nothing about red. Together: white is opposite yellow, so blue, which cannot be opposite red, green or yellow, must be opposite black. The only pair left is red and green. Both statements are needed.','कथन I अकेले: नीला, लाल, हरे और पीले के बगल में है, इसलिए नीले के सामने सफ़ेद या काला है -- और लाल के सामने वाला फलक अब भी खुला है। कथन II अकेले सफ़ेद को पीले से जोड़ता है और लाल के बारे में कुछ नहीं कहता। दोनों मिलकर: सफ़ेद, पीले के सामने है, इसलिए नीला, जो लाल, हरे या पीले के सामने नहीं हो सकता, काले के सामने होगा। बचा हुआ एकमात्र जोड़ा लाल और हरा है। दोनों कथन आवश्यक हैं।','csat-l4-s05-lr-ds-the-colour-opposite-red','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','How many three-digit numbers are divisible by 13?','तीन अंकों की कितनी संख्याएँ 13 से विभाज्य हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 51}'::jsonb,'[{"id": "a", "body": "68", "body_hi": "68", "isCorrect": false}, {"id": "b", "body": "69", "body_hi": "69", "isCorrect": true}, {"id": "c", "body": "70", "body_hi": "70", "isCorrect": false}, {"id": "d", "body": "76", "body_hi": "76", "isCorrect": false}]'::jsonb,2.5,0.83,'The multiples of 13 up to 999 number 999 ÷ 13 = 76 (with remainder), and those up to 99 number 7. So the three-digit ones are 76 - 7 = 69, from 104 = 13 × 8 to 988 = 13 × 76. 76 counts the multiples from 13 itself; 68 is (988 - 104) ÷ 13, which forgets to count the first one; 70 has no basis.','999 तक 13 के गुणज 999 ÷ 13 = 76 (शेष सहित) हैं, और 99 तक 7। इसलिए तीन अंकों वाले 76 - 7 = 69 हैं, 104 = 13 × 8 से 988 = 13 × 76 तक। 76, स्वयं 13 से गुणज गिनता है; 68, (988 - 104) ÷ 13 है, जो पहले गुणज को गिनना भूल जाता है; 70 का कोई आधार नहीं।','csat-l4-s05-qa-nt-three-digit-multiples-of-13','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In The Death and Life of Great American Cities, published in 1961, the writer Jane Jacobs argued that city streets are kept safe less by the police than by the people who use them: shopkeepers, residents at their windows and passers-by, the ''eyes on the street''. Such eyes, she said, need a mix of uses -- homes, shops, workplaces and places to eat side by side -- so that people are about at different hours of the day and night. Planners of her time often did the opposite, separating offices from homes and shops into zones of their own, and the streets of a zone emptied whenever its one use ended for the day. Her critics point out that she drew mostly on dense old neighbourhoods, and that a mix of uses cannot by itself make a street safe if the people on it do not care what happens there. Even so, her basic point -- that busy streets watch themselves -- has shaped city planning ever since.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1961 में प्रकाशित ''द डेथ एंड लाइफ़ ऑफ़ ग्रेट अमेरिकन सिटीज़'' में लेखिका जेन जेकब्स ने तर्क दिया कि शहर की सड़कें पुलिस से कम और उनका उपयोग करने वाले लोगों से अधिक सुरक्षित रहती हैं: दुकानदार, अपनी खिड़कियों पर निवासी और राहगीर, ''सड़क पर आँखें''। उन्होंने कहा कि ऐसी आँखों के लिए उपयोगों का मिश्रण चाहिए -- घर, दुकानें, कार्यस्थल और खाने की जगहें साथ-साथ -- ताकि दिन और रात के अलग-अलग समय पर लोग आसपास रहें। उनके समय के योजनाकार प्रायः उलटा करते थे, दफ़्तरों को घरों और दुकानों से अलग अपने-अपने क्षेत्रों में बाँटकर, और किसी क्षेत्र की सड़कें तब ख़ाली हो जातीं जब उसका एकमात्र उपयोग दिन भर के लिए समाप्त हो जाता। उनके आलोचक बताते हैं कि उन्होंने अधिकतर घनी पुरानी बस्तियों से उदाहरण लिए, और कि उपयोगों का मिश्रण अकेले किसी सड़क को सुरक्षित नहीं बना सकता यदि उस पर के लोगों को परवाह न हो कि वहाँ क्या होता है। फिर भी उनकी मूल बात -- कि भीड़-भरी सड़कें स्वयं अपनी निगरानी करती हैं -- ने तब से शहरी योजना को आकार दिया है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p07", "csat_order": 52}'::jsonb,'[{"id": "a", "body": "Streets with a mix of uses keep people about at all hours, and their watching makes them safer.", "body_hi": "मिश्रित उपयोग वाली सड़कें हर समय लोगों को आसपास रखती हैं, और उनकी निगरानी सड़कों को सुरक्षित बनाती है।", "isCorrect": true}, {"id": "b", "body": "Cities should do away with their police forces, since busy streets can always look after themselves.", "body_hi": "शहरों को अपनी पुलिस समाप्त कर देनी चाहिए, क्योंकि भीड़-भरी सड़कें हमेशा अपनी देखभाल स्वयं कर सकती हैं।", "isCorrect": false}, {"id": "c", "body": "Mixing homes, shops and offices on the same street makes it more dangerous for those who live there.", "body_hi": "एक ही सड़क पर घर, दुकानें और दफ़्तर मिलाने से वह वहाँ रहने वालों के लिए अधिक ख़तरनाक हो जाती है।", "isCorrect": false}, {"id": "d", "body": "Planners were right to separate offices from homes and shops, so that each zone has a single use.", "body_hi": "योजनाकारों का दफ़्तरों को घरों और दुकानों से अलग करना सही था, ताकि हर क्षेत्र का एक ही उपयोग हो।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage presents Jacobs''s claim that streets with a mix of uses stay safe because people are always about to watch them, notes its limits, and credits its lasting influence. It says safety comes less from the police than from people, not that police are useless; the critics say a mix is not enough by itself, not that it is harmful; and the planners'' zoning is what Jacobs criticised, not what she recommended.','परिच्छेद जेकब्स का यह दावा रखता है कि उपयोगों के मिश्रण वाली सड़कें इसलिए सुरक्षित रहती हैं कि उन पर नज़र रखने को लोग हमेशा आसपास होते हैं, उसकी सीमाएँ बताता है, और उसके स्थायी प्रभाव का श्रेय देता है। वह कहता है कि सुरक्षा पुलिस से कम और लोगों से अधिक आती है, यह नहीं कि पुलिस बेकार है; आलोचक कहते हैं कि मिश्रण अकेले पर्याप्त नहीं, यह नहीं कि वह हानिकारक है; और योजनाकारों का क्षेत्र-विभाजन वह है जिसकी जेकब्स ने आलोचना की, सलाह नहीं दी।','csat-l4-s05-rc-p07-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In The Death and Life of Great American Cities, published in 1961, the writer Jane Jacobs argued that city streets are kept safe less by the police than by the people who use them: shopkeepers, residents at their windows and passers-by, the ''eyes on the street''. Such eyes, she said, need a mix of uses -- homes, shops, workplaces and places to eat side by side -- so that people are about at different hours of the day and night. Planners of her time often did the opposite, separating offices from homes and shops into zones of their own, and the streets of a zone emptied whenever its one use ended for the day. Her critics point out that she drew mostly on dense old neighbourhoods, and that a mix of uses cannot by itself make a street safe if the people on it do not care what happens there. Even so, her basic point -- that busy streets watch themselves -- has shaped city planning ever since.

On Jacobs''s reasoning, which one of the following streets is likely to be the least safe late in the evening?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1961 में प्रकाशित ''द डेथ एंड लाइफ़ ऑफ़ ग्रेट अमेरिकन सिटीज़'' में लेखिका जेन जेकब्स ने तर्क दिया कि शहर की सड़कें पुलिस से कम और उनका उपयोग करने वाले लोगों से अधिक सुरक्षित रहती हैं: दुकानदार, अपनी खिड़कियों पर निवासी और राहगीर, ''सड़क पर आँखें''। उन्होंने कहा कि ऐसी आँखों के लिए उपयोगों का मिश्रण चाहिए -- घर, दुकानें, कार्यस्थल और खाने की जगहें साथ-साथ -- ताकि दिन और रात के अलग-अलग समय पर लोग आसपास रहें। उनके समय के योजनाकार प्रायः उलटा करते थे, दफ़्तरों को घरों और दुकानों से अलग अपने-अपने क्षेत्रों में बाँटकर, और किसी क्षेत्र की सड़कें तब ख़ाली हो जातीं जब उसका एकमात्र उपयोग दिन भर के लिए समाप्त हो जाता। उनके आलोचक बताते हैं कि उन्होंने अधिकतर घनी पुरानी बस्तियों से उदाहरण लिए, और कि उपयोगों का मिश्रण अकेले किसी सड़क को सुरक्षित नहीं बना सकता यदि उस पर के लोगों को परवाह न हो कि वहाँ क्या होता है। फिर भी उनकी मूल बात -- कि भीड़-भरी सड़कें स्वयं अपनी निगरानी करती हैं -- ने तब से शहरी योजना को आकार दिया है।

जेकब्स के तर्क के अनुसार, देर शाम को निम्नलिखित में से कौन-सी सड़क सबसे कम सुरक्षित होने की संभावना है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p07", "csat_order": 53}'::jsonb,'[{"id": "a", "body": "A street of small shops with families living in the flats above them", "body_hi": "छोटी दुकानों वाली सड़क, जिनके ऊपर के फ़्लैटों में परिवार रहते हैं", "isCorrect": false}, {"id": "b", "body": "A street with a cinema, two late-night cafes and some homes nearby", "body_hi": "एक सिनेमा, देर रात तक खुले दो कैफ़े और पास में कुछ घरों वाली सड़क", "isCorrect": false}, {"id": "c", "body": "A street lined only with office towers that close at six in the evening", "body_hi": "केवल ऐसे दफ़्तर भवनों वाली सड़क जो शाम छह बजे बंद हो जाते हैं", "isCorrect": true}, {"id": "d", "body": "A market street where the stallholders'' families live behind their stalls", "body_hi": "बाज़ार की ऐसी सड़क जहाँ दुकानदारों के परिवार अपनी दुकानों के पीछे रहते हैं", "isCorrect": false}]'::jsonb,2.5,0.83,'Jacobs''s argument is that safety comes from people being about at different hours. A street of office towers with nothing else on it empties once the offices close, so in the evening it has no eyes at all. A street with homes above shops, one with a cinema and late cafes, and a market street with families living behind the stalls all keep people about after dark.','जेकब्स का तर्क है कि सुरक्षा अलग-अलग समय पर लोगों के आसपास होने से आती है। केवल दफ़्तर भवनों वाली सड़क, जिस पर और कुछ नहीं, दफ़्तर बंद होते ही ख़ाली हो जाती है, इसलिए शाम को उस पर कोई आँखें नहीं होतीं। दुकानों के ऊपर घरों वाली सड़क, सिनेमा और देर तक खुले कैफ़े वाली सड़क, और दुकानों के पीछे रहने वाले परिवारों वाली बाज़ार की सड़क, सब अँधेरा होने के बाद भी लोगों को आसपास रखती हैं।','csat-l4-s05-rc-p07-the-least-safe-street-in-the-evening','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In The Death and Life of Great American Cities, published in 1961, the writer Jane Jacobs argued that city streets are kept safe less by the police than by the people who use them: shopkeepers, residents at their windows and passers-by, the ''eyes on the street''. Such eyes, she said, need a mix of uses -- homes, shops, workplaces and places to eat side by side -- so that people are about at different hours of the day and night. Planners of her time often did the opposite, separating offices from homes and shops into zones of their own, and the streets of a zone emptied whenever its one use ended for the day. Her critics point out that she drew mostly on dense old neighbourhoods, and that a mix of uses cannot by itself make a street safe if the people on it do not care what happens there. Even so, her basic point -- that busy streets watch themselves -- has shaped city planning ever since.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1961 में प्रकाशित ''द डेथ एंड लाइफ़ ऑफ़ ग्रेट अमेरिकन सिटीज़'' में लेखिका जेन जेकब्स ने तर्क दिया कि शहर की सड़कें पुलिस से कम और उनका उपयोग करने वाले लोगों से अधिक सुरक्षित रहती हैं: दुकानदार, अपनी खिड़कियों पर निवासी और राहगीर, ''सड़क पर आँखें''। उन्होंने कहा कि ऐसी आँखों के लिए उपयोगों का मिश्रण चाहिए -- घर, दुकानें, कार्यस्थल और खाने की जगहें साथ-साथ -- ताकि दिन और रात के अलग-अलग समय पर लोग आसपास रहें। उनके समय के योजनाकार प्रायः उलटा करते थे, दफ़्तरों को घरों और दुकानों से अलग अपने-अपने क्षेत्रों में बाँटकर, और किसी क्षेत्र की सड़कें तब ख़ाली हो जातीं जब उसका एकमात्र उपयोग दिन भर के लिए समाप्त हो जाता। उनके आलोचक बताते हैं कि उन्होंने अधिकतर घनी पुरानी बस्तियों से उदाहरण लिए, और कि उपयोगों का मिश्रण अकेले किसी सड़क को सुरक्षित नहीं बना सकता यदि उस पर के लोगों को परवाह न हो कि वहाँ क्या होता है। फिर भी उनकी मूल बात -- कि भीड़-भरी सड़कें स्वयं अपनी निगरानी करती हैं -- ने तब से शहरी योजना को आकार दिया है।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["For a street to be safe, the people on it must also care about what happens there.", "Separating uses into zones could leave streets deserted for part of each day."], "statements_hi": ["किसी सड़क के सुरक्षित होने के लिए उस पर के लोगों को यह परवाह भी होनी चाहिए कि वहाँ क्या होता है।", "उपयोगों को क्षेत्रों में बाँटना हर दिन के कुछ भाग में सड़कों को सुनसान छोड़ सकता था।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p07", "csat_order": 54}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are valid. The critics say a mix of uses cannot by itself make a street safe if the people on it do not care what happens there, so people''s willingness to notice and act matters too (1). And the passage says that a zone''s streets emptied whenever its one use ended for the day, so separating uses into zones could leave streets deserted for part of the day (2).','दोनों वैध हैं। आलोचक कहते हैं कि उपयोगों का मिश्रण अकेले सड़क को सुरक्षित नहीं बना सकता यदि उस पर के लोगों को परवाह न हो कि वहाँ क्या होता है, इसलिए लोगों की ध्यान देने और कुछ करने की इच्छा भी मायने रखती है (1)। और परिच्छेद कहता है कि किसी क्षेत्र की सड़कें तब ख़ाली हो जातीं जब उसका एकमात्र उपयोग दिन भर के लिए समाप्त होता, इसलिए उपयोगों को क्षेत्रों में बाँटना दिन के कुछ भाग में सड़कों को सुनसान छोड़ सकता था (2)।','csat-l4-s05-rc-p07-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','statement_based','medium','Statement: A city corporation orders that, from 1 June, every shop selling food in the city must display its prices clearly in both Hindi and English.

Which of the following assumptions is/are implicit in the statement?','कथन: एक नगर निगम आदेश देता है कि 1 जून से शहर में खाद्य पदार्थ बेचने वाली हर दुकान को अपने मूल्य हिंदी और अंग्रेज़ी दोनों में स्पष्ट रूप से प्रदर्शित करने होंगे।

निम्नलिखित में से कौन-सी पूर्वधारणा/एँ कथन में निहित है/हैं?','{"statements": ["Customers find it useful to be able to read the prices before they buy.", "Every customer in the city can read both Hindi and English."], "statements_hi": ["ग्राहकों के लिए ख़रीदने से पहले मूल्य पढ़ पाना उपयोगी है।", "शहर का हर ग्राहक हिंदी और अंग्रेज़ी दोनों पढ़ सकता है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "numbering": "roman", "csat_set": "csat-l4-s05", "csat_order": 55}'::jsonb,'[{"id": "a", "body": "I only", "body_hi": "केवल I", "isCorrect": true}, {"id": "b", "body": "II only", "body_hi": "केवल II", "isCorrect": false}, {"id": "c", "body": "Both I and II", "body_hi": "I और II दोनों", "isCorrect": false}, {"id": "d", "body": "Neither I nor II", "body_hi": "न तो I, न ही II", "isCorrect": false}]'::jsonb,2.5,0.83,'Only I is implicit. An order to display prices clearly makes sense only if being able to read them before buying is of use to customers. II is not assumed; the order points the other way. Requiring both languages makes sense precisely because some customers read one language but not the other; if everyone read both, one would do.','केवल I निहित है। मूल्य स्पष्ट रूप से प्रदर्शित करने का आदेश तभी समझ में आता है जब ख़रीदने से पहले उन्हें पढ़ पाना ग्राहकों के लिए उपयोगी हो। II पूर्वधारणा नहीं है; आदेश उलटी ओर संकेत करता है। दोनों भाषाओं की अनिवार्यता इसीलिए समझ में आती है कि कुछ ग्राहक एक भाषा पढ़ते हैं पर दूसरी नहीं; यदि सब दोनों पढ़ते, तो एक ही पर्याप्त होती।','csat-l4-s05-lr-sc-the-assumptions-behind-a-rule-on-price-labels','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','medium','A moving walkway at an airport is 120 m long and moves at 1 m/s. A traveller who walks at 1.5 m/s walks along it. How many seconds does the traveller save, compared with walking the same distance on the floor beside it?','एक हवाई अड्डे पर चलने वाला पथ (मूविंग वॉकवे) 120 मीटर लंबा है और 1 मीटर/सेकंड से चलता है। 1.5 मीटर/सेकंड से चलने वाला एक यात्री उस पर चलता है। उसके बगल के फ़र्श पर उतनी ही दूरी चलने की तुलना में यात्री कितने सेकंड बचाता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 56}'::jsonb,'[{"id": "a", "body": "32 s", "body_hi": "32 सेकंड", "isCorrect": true}, {"id": "b", "body": "40 s", "body_hi": "40 सेकंड", "isCorrect": false}, {"id": "c", "body": "48 s", "body_hi": "48 सेकंड", "isCorrect": false}, {"id": "d", "body": "80 s", "body_hi": "80 सेकंड", "isCorrect": false}]'::jsonb,2.5,0.83,'On the floor the traveller takes 120 ÷ 1.5 = 80 seconds. On the walkway the speeds add, 1.5 + 1 = 2.5 m/s, so it takes 120 ÷ 2.5 = 48 seconds. The saving is 80 - 48 = 32 seconds. 48 s and 80 s are the two times, not the saving; 40 s compares standing still on the walkway (120 s) with walking on the floor.','फ़र्श पर यात्री को 120 ÷ 1.5 = 80 सेकंड लगते हैं। चलने वाले पथ पर चालें जुड़ जाती हैं, 1.5 + 1 = 2.5 मीटर/सेकंड, इसलिए 120 ÷ 2.5 = 48 सेकंड लगते हैं। बचत 80 - 48 = 32 सेकंड है। 48 और 80 सेकंड दोनों समय हैं, बचत नहीं; 40 सेकंड पथ पर खड़े रहने (120 सेकंड) की तुलना फ़र्श पर चलने से करता है।','csat-l4-s05-qa-sdt-a-moving-walkway','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','hard','In the sequence 1, 11, 21, 1211, 111221, ..., each term describes the term before it: 1 is ''one 1'', written 11; 11 is ''two 1s'', written 21; 21 is ''one 2, one 1'', written 1211; and so on. What is the next term?','अनुक्रम 1, 11, 21, 1211, 111221, ... में हर पद अपने से पहले वाले पद का वर्णन करता है: 1 है ''एक 1'', लिखा गया 11; 11 है ''दो 1'', लिखा गया 21; 21 है ''एक 2, एक 1'', लिखा गया 1211; और इसी तरह। अगला पद क्या है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 57}'::jsonb,'[{"id": "a", "body": "311221", "body_hi": "311221", "isCorrect": false}, {"id": "b", "body": "3112211", "body_hi": "3112211", "isCorrect": false}, {"id": "c", "body": "1321211", "body_hi": "1321211", "isCorrect": false}, {"id": "d", "body": "312211", "body_hi": "312211", "isCorrect": true}]'::jsonb,2.5,0.83,'111221 reads as three 1s, two 2s and one 1: 31 22 11, that is 312211. 311221 writes ''three 1s, one 2, two 1s'', miscounting the 2s; 3112211 treats the two 2s as separate groups; 1321211 describes 111221 digit by digit in the wrong order.','111221 को पढ़ते हैं तीन 1, दो 2 और एक 1: 31 22 11, यानी 312211। 311221 लिखता है ''तीन 1, एक 2, दो 1'', जो 2 को ग़लत गिनता है; 3112211 दोनों 2 को अलग-अलग समूह मानता है; 1321211, 111221 का अंक-दर-अंक ग़लत क्रम में वर्णन करता है।','csat-l4-s05-qa-ss-a-sequence-that-describes-the-term-before-it','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','hard','Six people -- A, B, C, D, E and F -- sit at a hexagonal table, one on each side, all facing the centre, so that each person sits directly opposite one other. A sits opposite D. B sits to A''s immediate left. E does not sit next to A, and F sits opposite E. Which one of the following is correct?','छह लोग -- A, B, C, D, E और F -- एक षट्भुजाकार मेज़ पर, हर भुजा पर एक, सभी केंद्र की ओर मुख करके बैठे हैं, ऐसे कि हर व्यक्ति किसी एक के ठीक सामने बैठा है। A, D के सामने बैठा है। B, A के ठीक बाईं ओर बैठा है। E, A के बगल में नहीं बैठा, और F, E के सामने बैठा है। निम्नलिखित में से कौन-सा सही है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 58}'::jsonb,'[{"id": "a", "body": "C sits to D''s immediate left.", "body_hi": "C, D के ठीक बाईं ओर बैठा है।", "isCorrect": true}, {"id": "b", "body": "E sits to B''s immediate right.", "body_hi": "E, B के ठीक दाईं ओर बैठा है।", "isCorrect": false}, {"id": "c", "body": "F sits opposite C.", "body_hi": "F, C के सामने बैठा है।", "isCorrect": false}, {"id": "d", "body": "C sits next to A.", "body_hi": "C, A के बगल में बैठा है।", "isCorrect": false}]'::jsonb,2.5,0.83,'Go round the table from A towards A''s left: A, then B, then one seat, then D (opposite A), then one more seat, then the seat at A''s right. E is not next to A, so E takes one of the two seats beside D. The seat opposite the one between D and A''s right is B''s, so E there would leave no seat opposite E for F. Hence E sits between B and D, F sits opposite E at A''s right, and C takes the seat between D and F. Facing the centre, C is then at D''s immediate left. B''s immediate right is A, not E; F sits opposite E, not C; and A''s neighbours are B and F, not C.','A से A के बाईं ओर मेज़ पर घूमिए: A, फिर B, फिर एक सीट, फिर D (A के सामने), फिर एक और सीट, फिर A के दाईं ओर की सीट। E, A के बगल में नहीं है, इसलिए E, D के पास की दो सीटों में से एक लेता है। D और A के दाईं ओर की सीट के बीच वाली सीट के सामने B की सीट है, इसलिए E वहाँ हो तो F के लिए E के सामने कोई सीट न बचे। अतः E, B और D के बीच बैठता है, F, E के सामने A के दाईं ओर, और C, D और F के बीच की सीट लेता है। केंद्र की ओर मुख होने पर C तब D के ठीक बाईं ओर है। B के ठीक दाईं ओर A है, E नहीं; F, E के सामने बैठा है, C के नहीं; और A के पड़ोसी B और F हैं, C नहीं।','csat-l4-s05-lr-sa-a-hexagonal-table-with-opposite-seats','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Cholera and other diarrhoeal diseases kill mainly by draining the body of water and salts. For long the standard treatment was to replace them through a vein, which needs trained staff, sterile equipment and large stocks of fluid. In the 1960s researchers found that glucose helps the gut to absorb salt and water, so that a simple solution of salt and sugar in clean water, taken by mouth, could replace much of what was lost. In 1971, during the war that led to the birth of Bangladesh, the Indian doctor Dilip Mahalanabis used such a solution in refugee camps near the border, where fluid for drips was running out, and deaths among the cholera patients fell far below the usual rate. A few years later the medical journal The Lancet called the discovery potentially the most important medical advance of the century. The drink does not cure the infection; it keeps the patient alive while the body fights it. Its power lies in being cheap, simple and safe enough for a mother to give at home.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हैज़ा और दस्त के अन्य रोग मुख्यतः शरीर से पानी और लवणों को निकालकर मारते हैं। लंबे समय तक सामान्य उपचार उन्हें नस के माध्यम से वापस देना था, जिसके लिए प्रशिक्षित कर्मचारी, कीटाणुरहित उपकरण और तरल के बड़े भंडार चाहिए। 1960 के दशक में शोधकर्ताओं ने पाया कि ग्लूकोज़ आँत को लवण और पानी सोखने में सहायता करता है, इसलिए साफ़ पानी में नमक और चीनी का एक साधारण घोल, मुँह से लिया जाकर, खोए हुए का बड़ा भाग वापस दे सकता है। 1971 में, बांग्लादेश के जन्म तक ले जाने वाले युद्ध के दौरान, भारतीय डॉक्टर दिलीप महालनबीस ने सीमा के पास के शरणार्थी शिविरों में, जहाँ ड्रिप का तरल समाप्त हो रहा था, ऐसे घोल का उपयोग किया, और हैज़े के रोगियों में मौतें सामान्य दर से बहुत नीचे आ गईं। कुछ वर्ष बाद चिकित्सा पत्रिका ''द लैंसेट'' ने इस खोज को संभवतः शताब्दी की सबसे महत्त्वपूर्ण चिकित्सा उपलब्धि कहा। यह पेय संक्रमण का इलाज नहीं करता; यह रोगी को तब तक जीवित रखता है जब तक शरीर संक्रमण से लड़ता है। इसकी शक्ति इसके सस्ते, सरल और इतना सुरक्षित होने में है कि एक माँ इसे घर पर दे सके।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p08", "csat_order": 59}'::jsonb,'[{"id": "a", "body": "The salt-and-sugar drink cures cholera by killing the germs that cause the disease.", "body_hi": "नमक-चीनी का पेय रोग पैदा करने वाले कीटाणुओं को मारकर हैज़े का इलाज करता है।", "isCorrect": false}, {"id": "b", "body": "Treatment through a vein is useless and should no longer be given to any cholera patient.", "body_hi": "नस के माध्यम से उपचार बेकार है और अब किसी भी हैज़ा रोगी को नहीं दिया जाना चाहिए।", "isCorrect": false}, {"id": "c", "body": "Dilip Mahalanabis discovered in 1971 that glucose helps the gut to absorb salt and water.", "body_hi": "दिलीप महालनबीस ने 1971 में खोजा कि ग्लूकोज़ आँत को लवण और पानी सोखने में सहायता करता है।", "isCorrect": false}, {"id": "d", "body": "A cheap drink that keeps patients alive can save lives where elaborate care is lacking.", "body_hi": "रोगियों को जीवित रखने वाला सस्ता पेय वहाँ जीवन बचा सकता है जहाँ विस्तृत देखभाल न हो।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage shows that a cheap drink of salt and sugar, which replaces lost water and salts while the body fights the infection, saved lives where drips could not reach -- its value lies in being simple and safe. It says the drink does not cure the infection; it does not say drips are useless, only that they need staff and supplies; and it does not credit any single discovery made in 1971.','परिच्छेद दिखाता है कि नमक और चीनी का एक सस्ता पेय, जो शरीर के संक्रमण से लड़ते समय खोया पानी और लवण वापस देता है, उन जगहों पर जीवन बचाता था जहाँ ड्रिप नहीं पहुँच सकती थी -- उसका मूल्य उसके सरल और सुरक्षित होने में है। वह कहता है कि पेय संक्रमण का इलाज नहीं करता; वह यह नहीं कहता कि ड्रिप बेकार है, केवल यह कि उसके लिए कर्मचारी और सामग्री चाहिए; और वह 1971 में हुई किसी एक खोज को श्रेय नहीं देता।','csat-l4-s05-rc-p08-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Cholera and other diarrhoeal diseases kill mainly by draining the body of water and salts. For long the standard treatment was to replace them through a vein, which needs trained staff, sterile equipment and large stocks of fluid. In the 1960s researchers found that glucose helps the gut to absorb salt and water, so that a simple solution of salt and sugar in clean water, taken by mouth, could replace much of what was lost. In 1971, during the war that led to the birth of Bangladesh, the Indian doctor Dilip Mahalanabis used such a solution in refugee camps near the border, where fluid for drips was running out, and deaths among the cholera patients fell far below the usual rate. A few years later the medical journal The Lancet called the discovery potentially the most important medical advance of the century. The drink does not cure the infection; it keeps the patient alive while the body fights it. Its power lies in being cheap, simple and safe enough for a mother to give at home.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हैज़ा और दस्त के अन्य रोग मुख्यतः शरीर से पानी और लवणों को निकालकर मारते हैं। लंबे समय तक सामान्य उपचार उन्हें नस के माध्यम से वापस देना था, जिसके लिए प्रशिक्षित कर्मचारी, कीटाणुरहित उपकरण और तरल के बड़े भंडार चाहिए। 1960 के दशक में शोधकर्ताओं ने पाया कि ग्लूकोज़ आँत को लवण और पानी सोखने में सहायता करता है, इसलिए साफ़ पानी में नमक और चीनी का एक साधारण घोल, मुँह से लिया जाकर, खोए हुए का बड़ा भाग वापस दे सकता है। 1971 में, बांग्लादेश के जन्म तक ले जाने वाले युद्ध के दौरान, भारतीय डॉक्टर दिलीप महालनबीस ने सीमा के पास के शरणार्थी शिविरों में, जहाँ ड्रिप का तरल समाप्त हो रहा था, ऐसे घोल का उपयोग किया, और हैज़े के रोगियों में मौतें सामान्य दर से बहुत नीचे आ गईं। कुछ वर्ष बाद चिकित्सा पत्रिका ''द लैंसेट'' ने इस खोज को संभवतः शताब्दी की सबसे महत्त्वपूर्ण चिकित्सा उपलब्धि कहा। यह पेय संक्रमण का इलाज नहीं करता; यह रोगी को तब तक जीवित रखता है जब तक शरीर संक्रमण से लड़ता है। इसकी शक्ति इसके सस्ते, सरल और इतना सुरक्षित होने में है कि एक माँ इसे घर पर दे सके।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["The effect of glucose on the gut was first discovered in the refugee camps of 1971.", "The drink saves a patient by buying time for the body to fight off the infection, not by attacking the germ."], "statements_hi": ["आँत पर ग्लूकोज़ का प्रभाव पहली बार 1971 के शरणार्थी शिविरों में खोजा गया।", "पेय रोगी को कीटाणु पर हमला करके नहीं, बल्कि शरीर को संक्रमण से लड़ने का समय देकर बचाता है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p08", "csat_order": 60}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is valid. The drink works by replacing water and salts while the body fights the infection, so it would save a patient only if the patient could be kept alive long enough for the body to win; it is not a remedy for the germ itself. 1 misreads the history: the passage says researchers found the effect of glucose in the 1960s; Mahalanabis used the solution in 1971 -- he did not discover it.','केवल 2 वैध है। पेय शरीर के संक्रमण से लड़ते समय पानी और लवण वापस देकर काम करता है, इसलिए वह रोगी को तभी बचाएगा जब रोगी को इतने समय तक जीवित रखा जा सके कि शरीर जीत जाए; वह स्वयं कीटाणु का उपचार नहीं है। 1 इतिहास को ग़लत पढ़ता है: परिच्छेद कहता है कि शोधकर्ताओं ने ग्लूकोज़ का प्रभाव 1960 के दशक में पाया; महालनबीस ने 1971 में घोल का उपयोग किया -- उन्होंने उसकी खोज नहीं की।','csat-l4-s05-rc-p08-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Cholera and other diarrhoeal diseases kill mainly by draining the body of water and salts. For long the standard treatment was to replace them through a vein, which needs trained staff, sterile equipment and large stocks of fluid. In the 1960s researchers found that glucose helps the gut to absorb salt and water, so that a simple solution of salt and sugar in clean water, taken by mouth, could replace much of what was lost. In 1971, during the war that led to the birth of Bangladesh, the Indian doctor Dilip Mahalanabis used such a solution in refugee camps near the border, where fluid for drips was running out, and deaths among the cholera patients fell far below the usual rate. A few years later the medical journal The Lancet called the discovery potentially the most important medical advance of the century. The drink does not cure the infection; it keeps the patient alive while the body fights it. Its power lies in being cheap, simple and safe enough for a mother to give at home.

Why, according to the passage, did the drink work so well in the refugee camps of 1971?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
हैज़ा और दस्त के अन्य रोग मुख्यतः शरीर से पानी और लवणों को निकालकर मारते हैं। लंबे समय तक सामान्य उपचार उन्हें नस के माध्यम से वापस देना था, जिसके लिए प्रशिक्षित कर्मचारी, कीटाणुरहित उपकरण और तरल के बड़े भंडार चाहिए। 1960 के दशक में शोधकर्ताओं ने पाया कि ग्लूकोज़ आँत को लवण और पानी सोखने में सहायता करता है, इसलिए साफ़ पानी में नमक और चीनी का एक साधारण घोल, मुँह से लिया जाकर, खोए हुए का बड़ा भाग वापस दे सकता है। 1971 में, बांग्लादेश के जन्म तक ले जाने वाले युद्ध के दौरान, भारतीय डॉक्टर दिलीप महालनबीस ने सीमा के पास के शरणार्थी शिविरों में, जहाँ ड्रिप का तरल समाप्त हो रहा था, ऐसे घोल का उपयोग किया, और हैज़े के रोगियों में मौतें सामान्य दर से बहुत नीचे आ गईं। कुछ वर्ष बाद चिकित्सा पत्रिका ''द लैंसेट'' ने इस खोज को संभवतः शताब्दी की सबसे महत्त्वपूर्ण चिकित्सा उपलब्धि कहा। यह पेय संक्रमण का इलाज नहीं करता; यह रोगी को तब तक जीवित रखता है जब तक शरीर संक्रमण से लड़ता है। इसकी शक्ति इसके सस्ते, सरल और इतना सुरक्षित होने में है कि एक माँ इसे घर पर दे सके।

परिच्छेद के अनुसार, 1971 के शरणार्थी शिविरों में पेय ने इतना अच्छा काम क्यों किया?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p08", "csat_order": 61}'::jsonb,'[{"id": "a", "body": "The camps had far more doctors and nurses than the hospitals of the region.", "body_hi": "शिविरों में उस क्षेत्र के सभी अस्पतालों को मिलाकर भी उनसे कहीं अधिक डॉक्टर और नर्सें थीं।", "isCorrect": false}, {"id": "b", "body": "It needed no drips, sterile equipment or trained staff, which the camps lacked.", "body_hi": "उसे ड्रिप, कीटाणुरहित उपकरण या प्रशिक्षित कर्मचारी नहीं चाहिए थे, जो शिविरों में कम थे।", "isCorrect": true}, {"id": "c", "body": "The cholera that broke out in the camps was a much milder form of the disease.", "body_hi": "शिविरों में फैला हैज़ा रोग का कहीं अधिक हल्का रूप था।", "isCorrect": false}, {"id": "d", "body": "It killed the germs in the water that the refugees in the camps had been drinking.", "body_hi": "उसने उस पानी के कीटाणु मार दिए जो शिविरों के शरणार्थी पी रहे थे।", "isCorrect": false}]'::jsonb,2.5,0.83,'The camps were running out of fluid for drips, which also need trained staff and sterile equipment; a drink of salt and sugar needed none of these and could be given to many patients at once. The passage does not say the camps had more doctors, that the cholera there was milder, or that the drink killed the germs.','शिविरों में ड्रिप का तरल समाप्त हो रहा था, जिसके लिए प्रशिक्षित कर्मचारी और कीटाणुरहित उपकरण भी चाहिए; नमक और चीनी के पेय को इनमें से किसी की आवश्यकता नहीं थी और उसे एक साथ कई रोगियों को दिया जा सकता था। परिच्छेद यह नहीं कहता कि शिविरों में अधिक डॉक्टर थे, कि वहाँ हैज़ा हल्का था, या कि पेय कीटाणुओं को मारता था।','csat-l4-s05-rc-p08-why-the-drink-worked-in-the-camps','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','hard','A dealer buys 120 identical items at the same price. A third of them are sold at a profit of 20 per cent, half of them at a loss of 10 per cent, and the rest at a profit of 30 per cent. What is the dealer''s overall result?','एक व्यापारी एक ही मूल्य पर 120 एक जैसी वस्तुएँ ख़रीदता है। उनमें से एक-तिहाई 20 प्रतिशत लाभ पर, आधी 10 प्रतिशत हानि पर, और बाक़ी 30 प्रतिशत लाभ पर बेची जाती हैं। व्यापारी का कुल परिणाम क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 62}'::jsonb,'[{"id": "a", "body": "A loss of 6⅔ per cent", "body_hi": "6⅔ प्रतिशत हानि", "isCorrect": false}, {"id": "b", "body": "A profit of 5 per cent", "body_hi": "5 प्रतिशत लाभ", "isCorrect": false}, {"id": "c", "body": "A profit of 6⅔ per cent", "body_hi": "6⅔ प्रतिशत लाभ", "isCorrect": true}, {"id": "d", "body": "A profit of 13⅓ per cent", "body_hi": "13⅓ प्रतिशत लाभ", "isCorrect": false}]'::jsonb,2.5,0.83,'Take each item to cost ₹1. 40 items sell for 40 × 1.2 = 48, 60 for 60 × 0.9 = 54, and 20 for 20 × 1.3 = 26: ₹128 in all against a cost of ₹120. The profit is 8 on 120, that is 6⅔ per cent. 13⅓ per cent averages 20, -10 and 30 without weighting them by the number of items; a loss of 6⅔ per cent gets the sign wrong; 5 per cent has no basis.','हर वस्तु का मूल्य ₹1 मानिए। 40 वस्तुएँ 40 × 1.2 = 48 में, 60 वस्तुएँ 60 × 0.9 = 54 में, और 20 वस्तुएँ 20 × 1.3 = 26 में बिकती हैं: कुल ₹128, लागत ₹120 के मुक़ाबले। लाभ 120 पर 8, यानी 6⅔ प्रतिशत। 13⅓ प्रतिशत 20, -10 और 30 का वस्तुओं की संख्या से भारित किए बिना औसत लेता है; 6⅔ प्रतिशत हानि चिह्न ग़लत कर देता है; 5 प्रतिशत का कोई आधार नहीं।','csat-l4-s05-qa-pp-a-stock-sold-in-three-lots','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','easy','A lift rises at a steady rate and takes 30 seconds to go from the 1st floor to the 4th. How long does it take to go from the 1st floor to the 10th?','एक लिफ़्ट स्थिर दर से ऊपर जाती है और पहली मंज़िल से चौथी मंज़िल तक जाने में 30 सेकंड लेती है। पहली मंज़िल से दसवीं मंज़िल तक जाने में उसे कितना समय लगता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 63}'::jsonb,'[{"id": "a", "body": "67.5 s", "body_hi": "67.5 सेकंड", "isCorrect": false}, {"id": "b", "body": "75 s", "body_hi": "75 सेकंड", "isCorrect": false}, {"id": "c", "body": "80 s", "body_hi": "80 सेकंड", "isCorrect": false}, {"id": "d", "body": "90 s", "body_hi": "90 सेकंड", "isCorrect": true}]'::jsonb,2.5,0.83,'From the 1st floor to the 4th the lift climbs 3 floors, not 4, so it takes 10 seconds a floor. From the 1st to the 10th it climbs 9 floors: 90 seconds. 75 s and 67.5 s divide the 30 seconds among 4 floors (7.5 seconds each) and then count 10 or 9 floors; 80 s has no basis.','पहली से चौथी मंज़िल तक लिफ़्ट 4 नहीं, 3 मंज़िलें चढ़ती है, इसलिए प्रति मंज़िल 10 सेकंड लेती है। पहली से दसवीं तक वह 9 मंज़िलें चढ़ती है: 90 सेकंड। 75 और 67.5 सेकंड, 30 सेकंड को 4 मंज़िलों में बाँटते हैं (हर एक के 7.5 सेकंड) और फिर 10 या 9 मंज़िलें गिनते हैं; 80 सेकंड का कोई आधार नहीं।','csat-l4-s05-qa-ph-a-lift-timed-between-floors','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','easy','In how many ways can a captain and a vice-captain be chosen from a team of 11 players?','11 खिलाड़ियों की एक टीम में से एक कप्तान और एक उप-कप्तान कितने तरीक़ों से चुने जा सकते हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 64}'::jsonb,'[{"id": "a", "body": "55", "body_hi": "55", "isCorrect": false}, {"id": "b", "body": "110", "body_hi": "110", "isCorrect": true}, {"id": "c", "body": "121", "body_hi": "121", "isCorrect": false}, {"id": "d", "body": "220", "body_hi": "220", "isCorrect": false}]'::jsonb,2.5,0.83,'Any of the 11 can be captain, and then any of the other 10 vice-captain: 11 × 10 = 110. The two posts are different, so the order of choosing matters. 55 counts pairs of players without saying who holds which post; 121 lets one player hold both posts; 220 has no basis.','11 में से कोई भी कप्तान हो सकता है, और फिर बाक़ी 10 में से कोई भी उप-कप्तान: 11 × 10 = 110। दोनों पद अलग हैं, इसलिए चुनने का क्रम मायने रखता है। 55 खिलाड़ियों के जोड़े गिनता है, यह बताए बिना कि कौन-सा पद किसके पास है; 121 एक ही खिलाड़ी को दोनों पद दे देता है; 220 का कोई आधार नहीं।','csat-l4-s05-qa-pc-a-captain-and-a-vice-captain','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','medium','''The village fair has been held in the first week of March for more than a hundred years, so the first week of March must be the best time to hold it.'' Which one of the following best describes the flaw in this reasoning?','''गाँव का मेला सौ से अधिक वर्षों से मार्च के पहले सप्ताह में लगता आया है, इसलिए मार्च का पहला सप्ताह ही उसे लगाने का सबसे अच्छा समय होगा।'' निम्नलिखित में से कौन-सा इस तर्क की त्रुटि का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 65}'::jsonb,'[{"id": "a", "body": "It treats the age of a custom as if that alone proved the custom to be the best choice.", "body_hi": "यह किसी प्रथा के पुरानेपन को ही उसके सबसे अच्छा होने का प्रमाण मान लेता है।", "isCorrect": true}, {"id": "b", "body": "It assumes that the people who come to the fair would never accept any change of date.", "body_hi": "यह मान लेता है कि मेले में आने वाले लोग तारीख़ का कोई भी बदलाव कभी स्वीकार नहीं करेंगे।", "isCorrect": false}, {"id": "c", "body": "It judges the fair by the opinions of a few visitors rather than those of everyone.", "body_hi": "यह मेले को सबकी नहीं, कुछ आगंतुकों की राय के आधार पर आँकता है।", "isCorrect": false}, {"id": "d", "body": "It confuses the cause of the fair''s popularity with one of the effects of that popularity.", "body_hi": "यह मेले की लोकप्रियता के कारण को उस लोकप्रियता के किसी प्रभाव से भ्रमित कर देता है।", "isCorrect": false}]'::jsonb,2.5,0.83,'That something has long been done shows only that it has been done. The date may once have suited conditions -- a harvest, the roads, the weather of an earlier time -- that no longer hold, and a better date may never have been tried. Age alone is not evidence of being best. The argument says nothing about whether visitors would accept a change; it cites no visitors'' opinions at all; and it makes no claim about what causes the fair''s popularity.','किसी काम का लंबे समय से होते आना केवल यह दिखाता है कि वह होता आया है। हो सकता है वह तारीख़ कभी ऐसी परिस्थितियों -- फ़सल, सड़कों, पहले के समय के मौसम -- के अनुकूल रही हो जो अब नहीं हैं, और कोई बेहतर तारीख़ कभी आज़माई ही न गई हो। केवल पुरानापन सबसे अच्छा होने का प्रमाण नहीं है। तर्क इस बारे में कुछ नहीं कहता कि आगंतुक बदलाव स्वीकार करेंगे या नहीं; वह आगंतुकों की कोई राय उद्धृत नहीं करता; और वह मेले की लोकप्रियता के कारण के बारे में कोई दावा नहीं करता।','csat-l4-s05-lr-sc-a-date-defended-by-its-age','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','What is the product of all the factors of 12, including 1 and 12 itself?','1 और स्वयं 12 सहित, 12 के सभी गुणनखंडों का गुणनफल क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 66}'::jsonb,'[{"id": "a", "body": "28", "body_hi": "28", "isCorrect": false}, {"id": "b", "body": "144", "body_hi": "144", "isCorrect": false}, {"id": "c", "body": "864", "body_hi": "864", "isCorrect": false}, {"id": "d", "body": "1,728", "body_hi": "1,728", "isCorrect": true}]'::jsonb,2.5,0.83,'The factors are 1, 2, 3, 4, 6 and 12. They pair off as 1 × 12, 2 × 6 and 3 × 4, and each pair multiplies to 12, so the product is 12 × 12 × 12 = 1,728. 28 is the sum of the factors, not their product; 144 = 12² counts only two of the three pairs; 864 has no basis.','गुणनखंड 1, 2, 3, 4, 6 और 12 हैं। वे 1 × 12, 2 × 6 और 3 × 4 के जोड़ों में बँटते हैं, और हर जोड़े का गुणनफल 12 है, इसलिए गुणनफल 12 × 12 × 12 = 1,728 है। 28 गुणनखंडों का योग है, गुणनफल नहीं; 144 = 12², तीन में से केवल दो जोड़े गिनता है; 864 का कोई आधार नहीं।','csat-l4-s05-qa-nt-the-product-of-the-factors-of-12','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In the 1760s the English jurist William Blackstone wrote that it is better for ten guilty persons to escape than for one innocent person to suffer. The maxim is really a judgement about mistakes. Every system of trial makes two kinds of error -- convicting the innocent and acquitting the guilty -- and the rules of evidence that make one rarer tend to make the other more common. Demanding proof beyond reasonable doubt is a choice to accept more wrongful acquittals in order to have fewer wrongful convictions. Blackstone''s ten is not a figure found by measurement; it states which error a society fears more and by how much. Others have named different numbers, and a society that lowered the standard of proof would be choosing, whether it said so or not, a different ratio.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1760 के दशक में अंग्रेज़ विधिवेत्ता विलियम ब्लैकस्टोन ने लिखा कि दस अपराधियों का बच निकलना एक निर्दोष के कष्ट पाने से बेहतर है। यह सूक्ति वास्तव में भूलों के बारे में एक निर्णय है। हर मुक़दमा-व्यवस्था दो प्रकार की भूल करती है -- निर्दोष को दोषी ठहराना और दोषी को बरी करना -- और साक्ष्य के जो नियम एक को कम करते हैं वे प्रायः दूसरे को बढ़ाते हैं। उचित संदेह से परे प्रमाण माँगना कम ग़लत दोषसिद्धियों के लिए अधिक ग़लत बरियों को स्वीकार करने का चुनाव है। ब्लैकस्टोन का दस कोई मापकर निकाला गया आँकड़ा नहीं; वह बताता है कि कोई समाज किस भूल से अधिक डरता है और कितना। दूसरों ने अलग संख्याएँ बताई हैं, और जो समाज प्रमाण का मानक घटाए वह, कहे या न कहे, एक अलग अनुपात चुन रहा होगा।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p09", "csat_order": 67}'::jsonb,'[{"id": "a", "body": "Blackstone measured that exactly ten guilty people go free for every innocent one convicted.", "body_hi": "ब्लैकस्टोन ने मापा कि दोषी ठहराए गए हर निर्दोष के बदले ठीक दस अपराधी छूट जाते हैं।", "isCorrect": false}, {"id": "b", "body": "Lowering the standard of proof would remove both kinds of error from a system of trial.", "body_hi": "प्रमाण का मानक घटाने से मुक़दमा-व्यवस्था से दोनों प्रकार की भूलें मिट जाएँगी।", "isCorrect": false}, {"id": "c", "body": "A standard of proof is a choice about which of two unavoidable errors a society fears more.", "body_hi": "प्रमाण का मानक यह चुनाव है कि समाज दो अपरिहार्य भूलों में से किससे अधिक डरता है।", "isCorrect": true}, {"id": "d", "body": "Under proof beyond reasonable doubt, guilty people almost never escape conviction.", "body_hi": "उचित संदेह से परे प्रमाण के अंतर्गत अपराधी लगभग कभी दोषसिद्धि से नहीं बचते।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage reads Blackstone''s maxim as a choice between two kinds of error, which trade off against each other: the standard of proof expresses how much more a society fears convicting the innocent. It calls the ten a judgement, not a measured fact; it says lowering the standard changes the ratio, not that it removes errors; and it does not say that guilty people rarely escape.','परिच्छेद ब्लैकस्टोन की सूक्ति को दो प्रकार की भूलों के बीच एक चुनाव के रूप में पढ़ता है, जो एक-दूसरे के बदले घटती-बढ़ती हैं: प्रमाण का मानक बताता है कि कोई समाज निर्दोष को दोषी ठहराने से कितना अधिक डरता है। वह दस को एक निर्णय कहता है, मापा गया तथ्य नहीं; वह कहता है कि मानक घटाने से अनुपात बदलता है, यह नहीं कि भूलें मिट जाती हैं; और वह यह नहीं कहता कि अपराधी शायद ही बचते हैं।','csat-l4-s05-rc-p09-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In the 1760s the English jurist William Blackstone wrote that it is better for ten guilty persons to escape than for one innocent person to suffer. The maxim is really a judgement about mistakes. Every system of trial makes two kinds of error -- convicting the innocent and acquitting the guilty -- and the rules of evidence that make one rarer tend to make the other more common. Demanding proof beyond reasonable doubt is a choice to accept more wrongful acquittals in order to have fewer wrongful convictions. Blackstone''s ten is not a figure found by measurement; it states which error a society fears more and by how much. Others have named different numbers, and a society that lowered the standard of proof would be choosing, whether it said so or not, a different ratio.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1760 के दशक में अंग्रेज़ विधिवेत्ता विलियम ब्लैकस्टोन ने लिखा कि दस अपराधियों का बच निकलना एक निर्दोष के कष्ट पाने से बेहतर है। यह सूक्ति वास्तव में भूलों के बारे में एक निर्णय है। हर मुक़दमा-व्यवस्था दो प्रकार की भूल करती है -- निर्दोष को दोषी ठहराना और दोषी को बरी करना -- और साक्ष्य के जो नियम एक को कम करते हैं वे प्रायः दूसरे को बढ़ाते हैं। उचित संदेह से परे प्रमाण माँगना कम ग़लत दोषसिद्धियों के लिए अधिक ग़लत बरियों को स्वीकार करने का चुनाव है। ब्लैकस्टोन का दस कोई मापकर निकाला गया आँकड़ा नहीं; वह बताता है कि कोई समाज किस भूल से अधिक डरता है और कितना। दूसरों ने अलग संख्याएँ बताई हैं, और जो समाज प्रमाण का मानक घटाए वह, कहे या न कहे, एक अलग अनुपात चुन रहा होगा।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["With careful enough rules of evidence, a system of trial could avoid both kinds of error.", "Lowering the standard of proof would convict more of the guilty without convicting any more of the innocent."], "statements_hi": ["पर्याप्त सावधान साक्ष्य-नियमों से कोई मुक़दमा-व्यवस्था दोनों प्रकार की भूलों से बच सकती है।", "प्रमाण का मानक घटाने से अधिक निर्दोषों को दोषी ठहराए बिना अधिक अपराधी दोषी ठहराए जाएँगे।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p09", "csat_order": 68}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2.5,0.83,'Neither is valid. 1 goes beyond the passage: it says the rules that make one error rarer tend to make the other more common, not that a perfect system with neither error could be designed -- if anything, it implies the opposite. 2 also goes too far: the passage says a society that lowered the standard of proof would be choosing a different ratio, not that it would therefore convict more guilty people without convicting any more innocent ones.','कोई भी वैध नहीं। 1 परिच्छेद से आगे जाता है: वह कहता है कि जो नियम एक भूल को कम करते हैं वे प्रायः दूसरी को बढ़ाते हैं, यह नहीं कि बिना किसी भूल वाली पूर्ण व्यवस्था बनाई जा सकती है -- बल्कि वह उलटा संकेत करता है। 2 भी बहुत आगे जाता है: परिच्छेद कहता है कि प्रमाण का मानक घटाने वाला समाज एक अलग अनुपात चुन रहा होगा, यह नहीं कि वह इसलिए अधिक निर्दोषों को दोषी ठहराए बिना अधिक अपराधियों को दोषी ठहराएगा।','csat-l4-s05-rc-p09-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In the 1760s the English jurist William Blackstone wrote that it is better for ten guilty persons to escape than for one innocent person to suffer. The maxim is really a judgement about mistakes. Every system of trial makes two kinds of error -- convicting the innocent and acquitting the guilty -- and the rules of evidence that make one rarer tend to make the other more common. Demanding proof beyond reasonable doubt is a choice to accept more wrongful acquittals in order to have fewer wrongful convictions. Blackstone''s ten is not a figure found by measurement; it states which error a society fears more and by how much. Others have named different numbers, and a society that lowered the standard of proof would be choosing, whether it said so or not, a different ratio.

A society moves from Blackstone''s ten to a ratio of a hundred guilty escaping for every innocent person convicted. According to the passage''s reasoning, what would that change most likely involve?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1760 के दशक में अंग्रेज़ विधिवेत्ता विलियम ब्लैकस्टोन ने लिखा कि दस अपराधियों का बच निकलना एक निर्दोष के कष्ट पाने से बेहतर है। यह सूक्ति वास्तव में भूलों के बारे में एक निर्णय है। हर मुक़दमा-व्यवस्था दो प्रकार की भूल करती है -- निर्दोष को दोषी ठहराना और दोषी को बरी करना -- और साक्ष्य के जो नियम एक को कम करते हैं वे प्रायः दूसरे को बढ़ाते हैं। उचित संदेह से परे प्रमाण माँगना कम ग़लत दोषसिद्धियों के लिए अधिक ग़लत बरियों को स्वीकार करने का चुनाव है। ब्लैकस्टोन का दस कोई मापकर निकाला गया आँकड़ा नहीं; वह बताता है कि कोई समाज किस भूल से अधिक डरता है और कितना। दूसरों ने अलग संख्याएँ बताई हैं, और जो समाज प्रमाण का मानक घटाए वह, कहे या न कहे, एक अलग अनुपात चुन रहा होगा।

एक समाज ब्लैकस्टोन के दस से ऐसे अनुपात पर जाता है जिसमें दोषी ठहराए गए हर निर्दोष के बदले सौ अपराधी छूटें। परिच्छेद के तर्क के अनुसार, इस बदलाव में सबसे अधिक संभावना किसकी है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p09", "csat_order": 69}'::jsonb,'[{"id": "a", "body": "A stricter standard of proof, with more of the guilty going free", "body_hi": "प्रमाण का अधिक कड़ा मानक, जिसमें अधिक अपराधी छूटें", "isCorrect": true}, {"id": "b", "body": "A lower standard of proof, so that fewer of the guilty go free", "body_hi": "प्रमाण का निचला मानक, ताकि कम अपराधी छूटें", "isCorrect": false}, {"id": "c", "body": "Fewer acquittals of the guilty, with no other change to the trials", "body_hi": "अपराधियों की कम बरियाँ, मुक़दमों में कोई और बदलाव किए बिना", "isCorrect": false}, {"id": "d", "body": "Many more judges, so that every case can be heard more quickly", "body_hi": "कहीं अधिक न्यायाधीश, ताकि हर मामले की सुनवाई जल्दी हो सके", "isCorrect": false}]'::jsonb,2.5,0.83,'A higher ratio means fearing wrongful conviction even more, which calls for a still stricter standard of proof -- and, because the two errors trade off, more of the guilty going free. A lower standard of proof would move the ratio the other way; fewer acquittals of the guilty is the opposite of what a stricter standard brings; and nothing in the passage ties the ratio to the number of judges.','ऊँचे अनुपात का अर्थ है ग़लत दोषसिद्धि से और भी अधिक डरना, जिसके लिए प्रमाण का और कड़ा मानक चाहिए -- और, चूँकि दोनों भूलें एक-दूसरे के बदले घटती-बढ़ती हैं, अधिक अपराधियों का छूटना। प्रमाण का निचला मानक अनुपात को उलटी ओर ले जाएगा; अपराधियों की कम बरियाँ वह नहीं जो कड़ा मानक लाता है; और परिच्छेद में कुछ भी अनुपात को न्यायाधीशों की संख्या से नहीं जोड़ता।','csat-l4-s05-rc-p09-what-a-higher-ratio-involves','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Time & Work','mcq','easy','5 printers, working at the same steady rate, print 5 pages in 5 minutes. How many such printers are needed to print 100 pages in 5 minutes?','एक ही स्थिर दर से काम करने वाले 5 प्रिंटर 5 मिनट में 5 पृष्ठ छापते हैं। 5 मिनट में 100 पृष्ठ छापने के लिए ऐसे कितने प्रिंटर चाहिए?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 70}'::jsonb,'[{"id": "a", "body": "5", "body_hi": "5", "isCorrect": false}, {"id": "b", "body": "20", "body_hi": "20", "isCorrect": false}, {"id": "c", "body": "25", "body_hi": "25", "isCorrect": false}, {"id": "d", "body": "100", "body_hi": "100", "isCorrect": true}]'::jsonb,2.5,0.83,'5 printers make 5 pages in 5 minutes, so each printer makes one page in 5 minutes. To make 100 pages in those 5 minutes, 100 printers are needed. 5 keeps the number of printers unchanged; 20 divides 100 by 5; 25 has no basis.','5 प्रिंटर 5 मिनट में 5 पृष्ठ बनाते हैं, इसलिए हर प्रिंटर 5 मिनट में एक पृष्ठ बनाता है। उन्हीं 5 मिनट में 100 पृष्ठ बनाने के लिए 100 प्रिंटर चाहिए। 5 प्रिंटरों की संख्या नहीं बदलता; 20, 100 को 5 से भाग देता है; 25 का कोई आधार नहीं।','csat-l4-s05-qa-tw-five-printers-and-five-pages','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','statement_based','medium','Statement: Several children at a government school fell ill after eating the midday meal served there.

Which of the following courses of action follow(s) for pursuing?','कथन: एक सरकारी विद्यालय में वहाँ परोसा गया मध्याह्न भोजन खाने के बाद कई बच्चे बीमार पड़ गए।

निम्नलिखित में से कौन-सी कार्यवाही/याँ अपनाने योग्य है/हैं?','{"statements": ["Samples of the food should be tested, and the school''s kitchen and the supplier inspected.", "The midday meal scheme should be stopped in every school of the State."], "statements_hi": ["भोजन के नमूनों की जाँच हो, और विद्यालय की रसोई तथा आपूर्तिकर्ता का निरीक्षण किया जाए।", "राज्य के हर विद्यालय में मध्याह्न भोजन योजना बंद कर दी जाए।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "numbering": "roman", "csat_set": "csat-l4-s05", "csat_order": 71}'::jsonb,'[{"id": "a", "body": "I only", "body_hi": "केवल I", "isCorrect": true}, {"id": "b", "body": "II only", "body_hi": "केवल II", "isCorrect": false}, {"id": "c", "body": "Both I and II", "body_hi": "I और II दोनों", "isCorrect": false}, {"id": "d", "body": "Neither I nor II", "body_hi": "न तो I, न ही II", "isCorrect": false}]'::jsonb,2.5,0.83,'Only I follows. Testing the food and inspecting the kitchen and supplier deals directly with the problem: it finds the cause and lets it be put right. II does not follow. One school''s bad meal is no reason to deprive children in every school of a meal many of them depend on; a course of action should be in proportion to the problem.','केवल I अपनाने योग्य है। भोजन की जाँच और रसोई तथा आपूर्तिकर्ता का निरीक्षण समस्या से सीधे निपटता है: वह कारण खोजता है और उसे ठीक करने देता है। II नहीं। एक विद्यालय का ख़राब भोजन हर विद्यालय के बच्चों को उस भोजन से वंचित करने का कारण नहीं, जिस पर उनमें से कई निर्भर हैं; कार्यवाही समस्या के अनुपात में होनी चाहिए।','csat-l4-s05-lr-sc-after-a-midday-meal-makes-children-ill','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','hard','Triangles are drawn by joining three of the six corners of a regular hexagon. How many of these triangles have no side in common with the hexagon?','एक सम षट्भुज के छह कोनों में से तीन को जोड़कर त्रिभुज बनाए जाते हैं। इनमें से कितने त्रिभुजों की कोई भी भुजा षट्भुज की भुजा नहीं है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 72}'::jsonb,'[{"id": "a", "body": "2", "body_hi": "2", "isCorrect": true}, {"id": "b", "body": "4", "body_hi": "4", "isCorrect": false}, {"id": "c", "body": "6", "body_hi": "6", "isCorrect": false}, {"id": "d", "body": "8", "body_hi": "8", "isCorrect": false}]'::jsonb,2.5,0.83,'A triangle avoids every side of the hexagon only if no two of its corners are next to each other on the hexagon. With six corners round a ring, that means taking every other corner: corners 1, 3, 5 or corners 2, 4, 6. So there are just 2. Check by counting the rest: of the 6C3 = 20 triangles, 6 use two sides (three corners in a row) and 12 use exactly one (a side, plus one of the two corners not next to it), leaving 20 - 18 = 2. 6 and 8 miscount these groups; 4 has no basis.','कोई त्रिभुज षट्भुज की हर भुजा से तभी बचता है जब उसके कोई दो कोने षट्भुज पर पास-पास न हों। एक घेरे में छह कोनों के साथ इसका अर्थ है एक छोड़कर एक कोना लेना: कोने 1, 3, 5 या कोने 2, 4, 6। अतः केवल 2। बाक़ी को गिनकर जाँचिए: 6C3 = 20 त्रिभुजों में से 6 दो भुजाएँ लेते हैं (लगातार तीन कोने) और 12 ठीक एक (एक भुजा, और उससे सटे न होने वाले दो कोनों में से एक), जिससे 20 - 18 = 2 बचते हैं। 6 और 8 इन समूहों को ग़लत गिनते हैं; 4 का कोई आधार नहीं।','csat-l4-s05-qa-pc-triangles-in-a-hexagon-with-no-side-on-it','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','How many perfect squares lie between 1,000 and 2,000?','1,000 और 2,000 के बीच कितने पूर्ण वर्ग हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 73}'::jsonb,'[{"id": "a", "body": "13", "body_hi": "13", "isCorrect": true}, {"id": "b", "body": "14", "body_hi": "14", "isCorrect": false}, {"id": "c", "body": "15", "body_hi": "15", "isCorrect": false}, {"id": "d", "body": "16", "body_hi": "16", "isCorrect": false}]'::jsonb,2.5,0.83,'31² = 961 is below 1,000 and 32² = 1,024 is the first square above it; 44² = 1,936 is the last below 2,000, since 45² = 2,025. The squares are 32² to 44²: 44 - 32 + 1 = 13 of them. 14 counts 45² = 2,025 as well, which is over 2,000; 15 also counts 31² = 961, which is under 1,000; 16 has no basis.','31² = 961, 1,000 से नीचे है और 32² = 1,024 उसके ऊपर पहला वर्ग है; 44² = 1,936, 2,000 से नीचे अंतिम है, क्योंकि 45² = 2,025। वर्ग 32² से 44² तक हैं: 44 - 32 + 1 = 13। 14, 45² = 2,025 को भी गिनता है, जो 2,000 से ऊपर है; 15, 31² = 961 को भी गिनता है, जो 1,000 से नीचे है; 16 का कोई आधार नहीं।','csat-l4-s05-qa-nt-the-squares-between-1000-and-2000','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','easy','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Lichens -- partnerships of a fungus with an alga -- grow as crusts and tufts on bark and stone. They have no roots, and they take most of their water and nourishment straight from rain and the air. Lacking the protective outer layer of a leaf, they absorb whatever the air carries, and many kinds are harmed by sulphur dioxide, a gas given off when coal and oil are burnt. That makes them useful as indicators of pollution: where the air is heavy with sulphur dioxide, sensitive lichens die out, and in some cities they have returned to the trees only as the air has been cleaned. Lichens are a cheap gauge that anyone can read. But they are a rough one. Their absence says that something is wrong with the air without saying exactly what or how much, and a lichen may also be missing for reasons that have nothing to do with pollution, such as dry weather or the wrong kind of bark.

According to the passage, why are lichens so easily harmed by what the air carries?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
लाइकेन -- किसी कवक और शैवाल की साझेदारियाँ -- छाल और पत्थर पर पपड़ी और गुच्छों के रूप में उगते हैं। उनकी जड़ें नहीं होतीं, और वे अपना अधिकांश पानी और पोषण सीधे वर्षा और वायु से लेते हैं। पत्ती जैसी सुरक्षात्मक बाहरी परत न होने के कारण वे वायु में जो कुछ भी हो उसे सोख लेते हैं, और कई प्रकार सल्फ़र डाइऑक्साइड से हानि पाते हैं, जो कोयला और तेल जलाने पर निकलने वाली गैस है। इससे वे प्रदूषण के सूचक के रूप में उपयोगी होते हैं: जहाँ वायु में सल्फ़र डाइऑक्साइड अधिक है, संवेदनशील लाइकेन समाप्त हो जाते हैं, और कुछ शहरों में वे पेड़ों पर तभी लौटे जब वायु साफ़ की गई। लाइकेन एक सस्ता मापक हैं जिसे कोई भी पढ़ सकता है। पर वे एक मोटा मापक हैं। उनकी अनुपस्थिति बताती है कि वायु में कुछ गड़बड़ है, यह बताए बिना कि ठीक-ठीक क्या या कितना, और कोई लाइकेन ऐसे कारणों से भी अनुपस्थित हो सकता है जिनका प्रदूषण से कोई संबंध नहीं, जैसे सूखा मौसम या ग़लत प्रकार की छाल।

परिच्छेद के अनुसार, लाइकेन वायु में मौजूद चीज़ों से इतनी आसानी से हानि क्यों पाते हैं?','{"craft": "precision", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p10", "csat_order": 74}'::jsonb,'[{"id": "a", "body": "Their roots draw polluted water up from the soil into the rest of the plant.", "body_hi": "उनकी जड़ें मिट्टी से प्रदूषित पानी पौधे के बाक़ी भाग तक खींचती हैं।", "isCorrect": false}, {"id": "b", "body": "They take in water and food straight from the air, with no protective outer layer.", "body_hi": "वे पानी और भोजन सीधे वायु से लेते हैं, किसी सुरक्षात्मक बाहरी परत के बिना।", "isCorrect": true}, {"id": "c", "body": "They grow only in cities, where the air is always heavy with smoke and gases.", "body_hi": "वे केवल शहरों में उगते हैं, जहाँ वायु हमेशा धुएँ और गैसों से भरी रहती है।", "isCorrect": false}, {"id": "d", "body": "They need sulphur dioxide to grow, and are harmed when the air has too much of it.", "body_hi": "उन्हें उगने के लिए सल्फ़र डाइऑक्साइड चाहिए, और वायु में उसके बहुत अधिक होने पर वे हानि पाते हैं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says lichens take their water and nourishment straight from rain and air and, lacking a leaf''s protective outer layer, absorb whatever the air carries. It does not say they grow only in cities, that they need sulphur dioxide, or that their roots draw pollution from the soil -- they have no roots.','परिच्छेद कहता है कि लाइकेन अपना पानी और पोषण सीधे वर्षा और वायु से लेते हैं और, पत्ती की सुरक्षात्मक बाहरी परत न होने से, वायु में जो कुछ भी हो उसे सोख लेते हैं। वह यह नहीं कहता कि वे केवल शहरों में उगते हैं, कि उन्हें सल्फ़र डाइऑक्साइड चाहिए, या कि उनकी जड़ें मिट्टी से प्रदूषण खींचती हैं -- उनकी जड़ें नहीं होतीं।','csat-l4-s05-rc-p10-why-lichens-are-easily-harmed','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Lichens -- partnerships of a fungus with an alga -- grow as crusts and tufts on bark and stone. They have no roots, and they take most of their water and nourishment straight from rain and the air. Lacking the protective outer layer of a leaf, they absorb whatever the air carries, and many kinds are harmed by sulphur dioxide, a gas given off when coal and oil are burnt. That makes them useful as indicators of pollution: where the air is heavy with sulphur dioxide, sensitive lichens die out, and in some cities they have returned to the trees only as the air has been cleaned. Lichens are a cheap gauge that anyone can read. But they are a rough one. Their absence says that something is wrong with the air without saying exactly what or how much, and a lichen may also be missing for reasons that have nothing to do with pollution, such as dry weather or the wrong kind of bark.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
लाइकेन -- किसी कवक और शैवाल की साझेदारियाँ -- छाल और पत्थर पर पपड़ी और गुच्छों के रूप में उगते हैं। उनकी जड़ें नहीं होतीं, और वे अपना अधिकांश पानी और पोषण सीधे वर्षा और वायु से लेते हैं। पत्ती जैसी सुरक्षात्मक बाहरी परत न होने के कारण वे वायु में जो कुछ भी हो उसे सोख लेते हैं, और कई प्रकार सल्फ़र डाइऑक्साइड से हानि पाते हैं, जो कोयला और तेल जलाने पर निकलने वाली गैस है। इससे वे प्रदूषण के सूचक के रूप में उपयोगी होते हैं: जहाँ वायु में सल्फ़र डाइऑक्साइड अधिक है, संवेदनशील लाइकेन समाप्त हो जाते हैं, और कुछ शहरों में वे पेड़ों पर तभी लौटे जब वायु साफ़ की गई। लाइकेन एक सस्ता मापक हैं जिसे कोई भी पढ़ सकता है। पर वे एक मोटा मापक हैं। उनकी अनुपस्थिति बताती है कि वायु में कुछ गड़बड़ है, यह बताए बिना कि ठीक-ठीक क्या या कितना, और कोई लाइकेन ऐसे कारणों से भी अनुपस्थित हो सकता है जिनका प्रदूषण से कोई संबंध नहीं, जैसे सूखा मौसम या ग़लत प्रकार की छाल।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["The return of sensitive lichens to a city''s trees is a sign that its air has become cleaner.", "A single tree without lichens proves that the air around it is polluted with sulphur dioxide."], "statements_hi": ["किसी शहर के पेड़ों पर संवेदनशील लाइकेनों की वापसी इस बात का संकेत है कि उसकी वायु साफ़ हुई है।", "लाइकेन रहित एक पेड़ सिद्ध करता है कि उसके आसपास की वायु सल्फ़र डाइऑक्साइड से प्रदूषित है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p10", "csat_order": 75}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 1 is valid. The passage says lichens returned to the trees of some cities only as the air was cleaned, so their return is a sign that sulphur dioxide has fallen. 2 goes too far: the passage warns that a lichen may be missing for reasons that have nothing to do with pollution, such as dry weather or the wrong bark, so a single tree without lichens proves nothing on its own.','केवल 1 वैध है। परिच्छेद कहता है कि कुछ शहरों के पेड़ों पर लाइकेन तभी लौटे जब वायु साफ़ की गई, इसलिए उनकी वापसी इस बात का संकेत है कि सल्फ़र डाइऑक्साइड घटी है। 2 बहुत आगे जाता है: परिच्छेद चेताता है कि कोई लाइकेन ऐसे कारणों से भी अनुपस्थित हो सकता है जिनका प्रदूषण से कोई संबंध नहीं, जैसे सूखा मौसम या ग़लत छाल, इसलिए लाइकेन रहित एक पेड़ अकेले कुछ सिद्ध नहीं करता।','csat-l4-s05-rc-p10-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Lichens -- partnerships of a fungus with an alga -- grow as crusts and tufts on bark and stone. They have no roots, and they take most of their water and nourishment straight from rain and the air. Lacking the protective outer layer of a leaf, they absorb whatever the air carries, and many kinds are harmed by sulphur dioxide, a gas given off when coal and oil are burnt. That makes them useful as indicators of pollution: where the air is heavy with sulphur dioxide, sensitive lichens die out, and in some cities they have returned to the trees only as the air has been cleaned. Lichens are a cheap gauge that anyone can read. But they are a rough one. Their absence says that something is wrong with the air without saying exactly what or how much, and a lichen may also be missing for reasons that have nothing to do with pollution, such as dry weather or the wrong kind of bark.

A town wants to know whether a new power station has changed its air. Which one of the following uses lichens in the way the passage suggests?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
लाइकेन -- किसी कवक और शैवाल की साझेदारियाँ -- छाल और पत्थर पर पपड़ी और गुच्छों के रूप में उगते हैं। उनकी जड़ें नहीं होतीं, और वे अपना अधिकांश पानी और पोषण सीधे वर्षा और वायु से लेते हैं। पत्ती जैसी सुरक्षात्मक बाहरी परत न होने के कारण वे वायु में जो कुछ भी हो उसे सोख लेते हैं, और कई प्रकार सल्फ़र डाइऑक्साइड से हानि पाते हैं, जो कोयला और तेल जलाने पर निकलने वाली गैस है। इससे वे प्रदूषण के सूचक के रूप में उपयोगी होते हैं: जहाँ वायु में सल्फ़र डाइऑक्साइड अधिक है, संवेदनशील लाइकेन समाप्त हो जाते हैं, और कुछ शहरों में वे पेड़ों पर तभी लौटे जब वायु साफ़ की गई। लाइकेन एक सस्ता मापक हैं जिसे कोई भी पढ़ सकता है। पर वे एक मोटा मापक हैं। उनकी अनुपस्थिति बताती है कि वायु में कुछ गड़बड़ है, यह बताए बिना कि ठीक-ठीक क्या या कितना, और कोई लाइकेन ऐसे कारणों से भी अनुपस्थित हो सकता है जिनका प्रदूषण से कोई संबंध नहीं, जैसे सूखा मौसम या ग़लत प्रकार की छाल।

एक नगर जानना चाहता है कि एक नए बिजलीघर ने उसकी वायु को बदला है या नहीं। निम्नलिखित में से कौन-सा लाइकेनों का उस तरह उपयोग करता है जैसा परिच्छेद सुझाता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "passage_group": "csat-l4-s05-p10", "csat_order": 76}'::jsonb,'[{"id": "a", "body": "Count the lichens on a single dry wall near the station, once, after it opens", "body_hi": "बिजलीघर खुलने के बाद एक बार उसके पास की एक सूखी दीवार पर लाइकेन गिनना", "isCorrect": false}, {"id": "b", "body": "Use the number of lichens on a tree to state exactly how much gas is in the air", "body_hi": "किसी पेड़ पर लाइकेनों की संख्या से यह बताना कि वायु में ठीक कितनी गैस है", "isCorrect": false}, {"id": "c", "body": "Ignore the lichens, since anything so cheap to observe cannot tell anything useful", "body_hi": "लाइकेनों को अनदेखा करना, क्योंकि इतनी सस्ती देखी जाने वाली चीज़ कुछ उपयोगी नहीं बता सकती", "isCorrect": false}, {"id": "d", "body": "Compare the same trees'' lichens before and after, and test the air if they decline", "body_hi": "उन्हीं पेड़ों पर पहले और बाद के लाइकेनों की तुलना करना, और घटें तो वायु मापना", "isCorrect": true}]'::jsonb,2.5,0.83,'Lichens are a cheap but rough gauge, and their absence can have other causes. Comparing the same trees, of the same kind, before and after the station opened -- and then measuring the air directly if the lichens decline -- uses them as an early warning while guarding against the other causes. Counting lichens on one dry wall mixes in the effect of dry weather; reading the exact amount of gas from them asks more than they can tell; and ignoring them because they are cheap throws away a useful signal.','लाइकेन सस्ते पर मोटे मापक हैं, और उनकी अनुपस्थिति के अन्य कारण हो सकते हैं। बिजलीघर खुलने से पहले और बाद में उसी प्रकार के उन्हीं पेड़ों की तुलना करना -- और लाइकेन घटें तो वायु को सीधे मापना -- उन्हें अन्य कारणों से बचाव करते हुए पूर्व चेतावनी के रूप में उपयोग करता है। एक सूखी दीवार पर लाइकेन गिनना सूखे मौसम का प्रभाव मिला देता है; उनसे गैस की ठीक मात्रा पढ़ना उनसे अधिक माँगना है जितना वे बता सकते हैं; और सस्ते होने के कारण उन्हें अनदेखा करना एक उपयोगी संकेत फेंक देना है।','csat-l4-s05-rc-p10-using-lichens-to-watch-a-power-station','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Cube Painting','mcq','hard','Only the twelve edges of a wooden cube are painted, as thin lines; the rest of its faces are left bare. The cube is then cut into 27 equal smaller cubes. How many of the small cubes have some paint on them?','लकड़ी के एक घन के केवल बारह किनारे पतली रेखाओं के रूप में रँगे जाते हैं; उसके फलकों का बाक़ी भाग बिना रंग के छोड़ा जाता है। फिर घन को 27 बराबर छोटे घनों में काटा जाता है। कितने छोटे घनों पर कुछ रंग है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 77}'::jsonb,'[{"id": "a", "body": "8", "body_hi": "8", "isCorrect": false}, {"id": "b", "body": "20", "body_hi": "20", "isCorrect": true}, {"id": "c", "body": "24", "body_hi": "24", "isCorrect": false}, {"id": "d", "body": "26", "body_hi": "26", "isCorrect": false}]'::jsonb,2.5,0.83,'A small cube gets paint only if it lies along an edge of the big cube. That means the 8 corner cubes, each on three edges, and the 12 cubes in the middle of the edges, one to each edge. The 6 cubes at the centres of the faces touch no edge, since the painted lines run round the borders of each face, and the cube at the very centre is hidden. So 8 + 12 = 20. 26 counts every cube on the surface, as if the faces had been painted; 8 counts only the corners; 24 has no basis.','किसी छोटे घन पर रंग तभी आता है जब वह बड़े घन के किसी किनारे के साथ हो। यानी 8 कोने वाले घन, हर एक तीन किनारों पर, और किनारों के बीच के 12 घन, हर किनारे पर एक। फलकों के केंद्र वाले 6 घन किसी किनारे को नहीं छूते, क्योंकि रँगी रेखाएँ हर फलक की सीमा के चारों ओर चलती हैं, और ठीक केंद्र वाला घन छिपा है। अतः 8 + 12 = 20। 26 सतह के हर घन को गिनता है, मानो फलक रँगे गए हों; 8 केवल कोनों को गिनता है; 24 का कोई आधार नहीं।','csat-l4-s05-lr-cp-a-cube-with-only-its-edges-painted','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','medium','A game costs ₹2 to play. A fair die is rolled once, and the player wins ₹10 if it shows a six and nothing otherwise. Over many games, what happens to a player on average in each game?','एक खेल खेलने के ₹2 लगते हैं। एक निष्पक्ष पासा एक बार फेंका जाता है, और छह आने पर खिलाड़ी ₹10 जीतता है, अन्यथा कुछ नहीं। बहुत-से खेलों में, हर खेल में औसतन खिलाड़ी के साथ क्या होता है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 78}'::jsonb,'[{"id": "a", "body": "A gain of about ₹1.67", "body_hi": "लगभग ₹1.67 का लाभ", "isCorrect": false}, {"id": "b", "body": "A loss of about 33 paise", "body_hi": "लगभग 33 पैसे की हानि", "isCorrect": true}, {"id": "c", "body": "Neither a gain nor a loss", "body_hi": "न लाभ न हानि", "isCorrect": false}, {"id": "d", "body": "A loss of the full ₹2", "body_hi": "हर खेल में पूरे ₹2 की हानि", "isCorrect": false}]'::jsonb,2.5,0.83,'A six comes up in 1 game in 6 on average, so the average winnings are ₹10 ÷ 6 ≈ ₹1.67 a game. Against the ₹2 paid, the player loses about ₹0.33 -- 33 paise -- a game on average. ₹1.67 is the average winnings before the cost of playing is taken off; ''neither a gain nor a loss'' would need a prize of ₹12; the full ₹2 is lost only in games without a six.','औसतन 6 में से 1 खेल में छह आता है, इसलिए औसत जीत ₹10 ÷ 6 ≈ ₹1.67 प्रति खेल है। चुकाए गए ₹2 के मुक़ाबले खिलाड़ी औसतन हर खेल में लगभग ₹0.33 -- 33 पैसे -- हारता है। ₹1.67 खेलने का मूल्य घटाने से पहले की औसत जीत है; ''न लाभ न हानि'' के लिए ₹12 का इनाम चाहिए; पूरे ₹2 केवल उन खेलों में जाते हैं जिनमें छह नहीं आता।','csat-l4-s05-qa-pc-the-average-result-of-a-dice-game','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','A model of a ship is built to a scale of 1 : 100. When full, the model''s hold carries 2 litres of water. How much would the hold of the real ship carry?','एक जहाज़ का मॉडल 1 : 100 के पैमाने पर बनाया गया है। भरा होने पर मॉडल के माल-कक्ष (होल्ड) में 2 लीटर पानी आता है। असली जहाज़ के माल-कक्ष में कितना आएगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s05", "csat_order": 79}'::jsonb,'[{"id": "a", "body": "200 litres", "body_hi": "200 लीटर", "isCorrect": false}, {"id": "b", "body": "20,000 litres", "body_hi": "20,000 लीटर", "isCorrect": false}, {"id": "c", "body": "2,00,000 litres", "body_hi": "2,00,000 लीटर", "isCorrect": false}, {"id": "d", "body": "20,00,000 litres", "body_hi": "20,00,000 लीटर", "isCorrect": true}]'::jsonb,2.5,0.83,'Every length of the real ship is 100 times the model''s, so every volume is 100 × 100 × 100 = 10,00,000 times as large: 2 × 10,00,000 = 20,00,000 litres (2,000 cubic metres). 200 litres scales by length alone and 20,000 litres by area; 2,00,000 litres has no basis.','असली जहाज़ की हर लंबाई मॉडल की 100 गुना है, इसलिए हर आयतन 100 × 100 × 100 = 10,00,000 गुना है: 2 × 10,00,000 = 20,00,000 लीटर (2,000 घन मीटर)। 200 लीटर केवल लंबाई से और 20,000 लीटर क्षेत्रफल से बढ़ाता है; 2,00,000 लीटर का कोई आधार नहीं।','csat-l4-s05-qa-rm-a-scale-model-s-hold','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Blood Relation','mcq','medium','Rina is the wife of the brother of Asha''s husband. How is Rina related to Asha''s son?','रीना, आशा के पति के भाई की पत्नी है। रीना, आशा के बेटे की क्या लगती है?','{"craft": "inference", "csat_set": "csat-l4-s05", "csat_order": 80}'::jsonb,'[{"id": "a", "body": "She is the wife of his mother''s brother.", "body_hi": "वह उसकी माँ के भाई की पत्नी, यानी उसकी मामी, है।", "isCorrect": false}, {"id": "b", "body": "She is his mother''s sister.", "body_hi": "वह उसकी माँ की बहन (मौसी) है।", "isCorrect": false}, {"id": "c", "body": "She is his father''s sister.", "body_hi": "वह उसके पिता की बहन (बुआ) है।", "isCorrect": false}, {"id": "d", "body": "She is the wife of his father''s brother.", "body_hi": "वह उसके पिता के भाई की पत्नी (चाची या ताई) है।", "isCorrect": true}]'::jsonb,2.5,0.83,'Asha''s husband is the son''s father, so the brother of Asha''s husband is the son''s father''s brother, and Rina, his wife, is the wife of the son''s father''s brother -- his chachi or tai. The mother''s brother and the mother''s sister are on Asha''s side of the family, not her husband''s; and Rina married into the father''s family rather than being born in it, so she is not his father''s sister.','आशा का पति उस बेटे का पिता है, इसलिए आशा के पति का भाई बेटे के पिता का भाई है, और रीना, उसकी पत्नी, बेटे के पिता के भाई की पत्नी है -- उसकी चाची या ताई। मामा और मौसी आशा के परिवार की ओर हैं, उसके पति के नहीं; और रीना पिता के परिवार में ब्याह कर आई है, उसमें जन्मी नहीं, इसलिए वह बुआ नहीं है।','csat-l4-s05-lr-br-a-husband-s-brother-s-wife','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft')
returning concept_group_id;
